// Every speed, delay and threshold the product relies on, with where it came from (CLAUDE.md
// invariant 7). Site geometry is not here: it comes from hello (site.ts). "measured" values are from
// the live gateway (research/README.md); "decided" values are ours, with the reason recorded.

export type Source = 'spec' | 'measured' | 'decided';

export interface Param {
  readonly value: number;
  readonly unit: 'm/s' | 'ms' | 'm' | '%' | '%/s' | 'count' | 'ratio' | 'bytes';
  readonly source: Source;
  readonly ref: string;
}

const p = (value: number, unit: Param['unit'], source: Source, ref: string): Param => ({ value, unit, source, ref });

export const PARAMS = {
  // Speeds
  autoSpeedEmpty: p(3.0, 'm/s', 'spec', 'PROTOCOL.md §3, nominal speeds'),
  autoSpeedLoaded: p(2.0, 'm/s', 'spec', 'PROTOCOL.md §3, nominal speeds'),
  manualSpeedEmptyFull: p(4.0, 'm/s', 'spec', 'PROTOCOL.md §3, manual at full throttle'),
  manualSpeedLoadedFull: p(3.0, 'm/s', 'spec', 'PROTOCOL.md §3, manual at full throttle'),
  limpHomeSpeed: p(1.0, 'm/s', 'spec', 'PROTOCOL.md §6.6'),
  reverseSpeedEmpty: p(3.0, 'm/s', 'measured', 'research/README.md, probe S3: EXIT_ZONE reversed at 3.0 m/s'),
  reverseSpeedLoaded: p(2.0, 'm/s', 'measured', 'thinly: re-probe R1, 1.99 m/s by the truck\'s clock over only 2.4 m before it went silent (research/README.md); test 1.5 as the pessimistic case'),

  // Work cycle
  loadTime: p(20_000, 'ms', 'spec', 'PROTOCOL.md §3, loads for about 20 s'),
  dumpTime: p(12_000, 'ms', 'spec', 'PROTOCOL.md §3, dumps for about 12 s'),
  chargeBelow: p(25, '%', 'spec', 'PROTOCOL.md §3, charges below 25 % at the end of the bay'),
  chargeTo: p(90, '%', 'spec', 'PROTOCOL.md §3, charges to 90 %'),

  // Commands and control
  supervisoryDelayMax: p(6_000, 'ms', 'spec', 'PROTOCOL.md §5, take effect 1 to 6 s after acceptance'),
  deadman: p(500, 'ms', 'spec', 'PROTOCOL.md §6.3; ~0.4 s measured in probe S4'),
  leaseIdleTimeout: p(10_000, 'ms', 'spec', 'PROTOCOL.md §6.4; 10.1 s measured in probe S4'),
  driveInterval: p(100, 'ms', 'spec', 'PROTOCOL.md §6.2, stream at 10 to 20 Hz'),
  exitZoneStopOutside: p(2, 'm', 'spec', 'PROTOCOL.md §5, stops about 2 m outside; 2.0 m measured in probe S3'),
  heartbeatInterval: p(2_000, 'ms', 'spec', 'PROTOCOL.md §4.3; 2.006 to 2.014 s measured'),

  // Data-confidence thresholds (TESTING.md "Thresholds"; owned by the ingest task)
  truckOldAfter: p(2_000, 'ms', 'decided', 'longest normal gap between one truck\'s messages was 1.67 s'),
  truckSilentAfter: p(5_000, 'ms', 'decided', 'flags only the known silent trucks in all three captures; leaves 5 s of the 10 s alarm budget'),
  frozenAfter: p(3_000, 'ms', 'decided', 'flags exactly the one frozen truck per capture, nothing else'),
  frozenMinReportedSpeed: p(0.5, 'm/s', 'decided', 'below this a truck may honestly be creeping'),
  frozenMaxMovement: p(0.05, 'm', 'decided', 'frozen positions repeat exactly; real motion at 0.5 m/s moves 1.5 m in 3 s'),
  linkDownAfter: p(5_000, 'ms', 'decided', '2.5 heartbeat intervals'),

  // Ingest: ordering, time and field repair (owned by the ingest task)
  reorderWindow: p(50, 'count', 'decided', 'deepest reordering in any fixture is 6 seqs; 50 is 10 s at 5 Hz. A larger seq drop with the device clock moving forward is a controller restart'),
  serverTimeSamples: p(8, 'count', 'decided', 'server-time offset is the max over the last 8 samples (16 s of heartbeats): delay only makes a sample low'),
  telemetryLatencyAllowance: p(1_500, 'ms', 'measured', 'a truck\'s t_device - rx spread is up to 1.25 s within one fixture (seq-reset fixture: 1.07 to 2.32 s), so a message may describe the truck that much earlier than it arrived'),
  deviceSkewFlagAbove: p(10_000, 'ms', 'decided', 'every truck in every fixture is within 3 s of arrival time except the skewed one, at about +58 min'),
  offsetTolerance: p(0.5, 'm', 'decided', 'offset_m may sit this far past its segment ends before the position is treated as unknown; no fixture goes past at all'),
  fractionalSocJump: p(2, '%', 'decided', 'healthy drain is under 0.1 % per message even for the weak pack; a drop of more than 2 points into the 0-1 range is a fraction, not a drain'),

  // Battery (owned by the ingest task)
  drainWindow: p(500, 'm', 'decided', 'drain rate is measured over the last 500 m travelled in each load state'),
  drainMinEvidence: p(60, 'm', 'decided', 'about 20 s at 3 m/s; at 0.01 % SoC resolution a healthy 0.36 % over 60 m reads within 3 %. The fleet median needs 3 other trucks with this much too: weak-pack replay flags the weak truck 34 s in (64 s at 100 m)'),
  drainMaxGap: p(10_000, 'ms', 'decided', 'over a longer gap the path travelled is not known; the interval is skipped'),
  drainRatioFlag: p(2, 'ratio', 'decided', 'healthy trucks are within 1 % of the fleet median (6.0 %/km empty, 9.0 loaded, weak-pack fixture); the weak pack is 5x'),
  fleetMinTrucks: p(3, 'count', 'decided', 'a fleet median needs at least 3 other trucks with enough evidence'),
  loadedDrainFactor: p(1.5, 'ratio', 'measured', 'fleet median 9.0 %/km loaded against 6.0 empty (weak-pack fixture); used only until the fleet itself gives a ratio'),
  batteryReserveFactor: p(1.25, 'ratio', 'decided', 'warn when charge is below 1.25x the estimated need, so the warning comes while there is still time to act'),

  // Gateway link (task 3)
  linkBackoffBase: p(500, 'ms', 'decided', 'first retry after a drop; doubles per failed attempt. The live capture tool used 2 s doubling to 10 s and reconnected cleanly'),
  linkBackoffMax: p(5_000, 'ms', 'decided', 'cap: once the site link returns we reconnect within 5 s, so a 21-49 s live outage costs at most 5 s more of a 120 s blast notice'),
  linkBackoffBusyBase: p(5_000, 'ms', 'decided', 'TOO_MANY_CONNECTIONS and SERVER_FULL (PROTOCOL.md §1.1, "try again shortly"): the gateway is loaded, so start slower'),
  linkBackoffBusyMax: p(30_000, 'ms', 'decided', 'cap for a loaded gateway; the link status says why we are waiting'),
  helloTimeout: p(5_000, 'ms', 'decided', 'a login with no hello within 5 s is an outage; live, hello came 85 ms after connecting and outage logins closed within 52 ms (link-drop-in-notice)'),

  // Command registry (task 4)
  commandUplinkAllowance: p(500, 'ms', 'measured', 'the gateway stamped all 11 fixture acks 43-58 ms after the probe sent (probe clock against gateway clock, so uplink plus their offset); about 10x margin. Acks themselves arrived 0.31-2.58 s after sending'),
  immediateEffectDeadline: p(3_000, 'ms', 'decided', 'ESTOP and lease operations take effect on receipt (PROTOCOL.md §5): uplink plus telemetry latency (1.5 s) plus margin'),
  commandMaxAttempts: p(3, 'count', 'decided', 'one accepted-then-ignored plus one more; both live retries worked first time (research/README.md). 3 x 8 s fits well inside a 120 s notice'),
  estopMaxAttempts: p(5, 'count', 'decided', 'an e-stop is worth more tries; 5 x 3 s is still 15 s'),
  chargeRate: p(0.1, '%/s', 'decided', 'guessed: no CHARGING was ever captured; Sam\'s "ten-minute charge". Used only for an estimate, never a deadline'),
  reconnectVerifyGrace: p(2_500, 'ms', 'decided', 'after a reconnect, a command too old to replay is checked against telemetry for this long (latency 1.5 s plus margin) before it is marked expired'),

  // Blast safety and operator attention
  cantClearAlarmWithin: p(10_000, 'ms', 'decided', 'CLAUDE.md invariant 5; TESTING.md L4.R1'),
  autoResumeWithin: p(15_000, 'ms', 'decided', 'TESTING.md L4.R3: command delay plus one retry, with margin'),
  estopAutoSendWithin: p(10_000, 'ms', 'decided', 'TESTING.md L7.8: a pending e-stop is sent on reconnect only within 10 s'),
  realertAfter: p(15 * 60_000, 'ms', 'decided', 'TESTING.md L2.63'),
  escalateAfter: p(30 * 60_000, 'ms', 'decided', 'TESTING.md L2.63'),

  // The service and the operators' browsers (task 6b)
  livePushMinInterval: p(250, 'ms', 'decided', 'at most 4 pictures a second to each browser: faster than a person reads, slow enough that 140 trucks fit; trucks report at 5 Hz and chips glide between frames'),
  liveFrameMaxInterval: p(1_000, 'ms', 'decided', 'a frame at least every second even when nothing arrived, so ages keep counting on screen and the frame doubles as the service heartbeat'),
  browserStaleAfter: p(3_000, 'ms', 'decided', 'the browser says "service disconnected" after 3 missed frames; src/ui/app.ts reads it from here'),
  liveMaxBufferedBytes: p(1_048_576, 'bytes', 'decided', 'a browser this far behind skips frames rather than queueing old pictures'),
  sessionIdleTimeout: p(30 * 60_000, 'ms', 'decided', 'a session ends 30 min after its last request with no screen open; an open screen keeps it alive, because logging out a watched control-room screen mid-shift hides alarms'),
  sessionMaxAge: p(14 * 3_600_000, 'ms', 'decided', 'a 12-hour shift plus handover: every session ends by then, screen open or not'),
  loginMaxFailures: p(5, 'count', 'decided', 'failed logins for one user name, or from one address, before further attempts are refused for the window'),
  loginFailureWindow: p(15 * 60_000, 'ms', 'decided', 'the window the failure count covers'),
  browserMessagesPerSecond: p(10, 'count', 'decided', 'a person presses at most a few buttons a second; more is a stuck script or an attack, refused and logged'),
} as const satisfies Record<string, Param>;

export type ParamName = keyof typeof PARAMS;
// One-dimensional geometry on the loop (TESTING.md L2.1-L2.6). Positions are metres along the
// loop; everything wraps at the loop length, which comes from hello. A Range is closed at both
// ends: a range that touches a zone's boundary counts as inside it, because "might be inside" is
// the safe reading (CLAUDE.md invariant 6).
import { PARAMS } from './params.ts';
import type { Direction } from './protocol.ts';
import type { Range, Site } from './site.ts';

export function normalise(loopM: number, p: number): number {
  if (p >= 0 && p < loopM) return p;
  const r = ((p % loopM) + loopM) % loopM;
  return r === loopM ? 0 : r;
}

// Distance travelling forward (increasing position) from `from` to `to`, in [0, loop).
export function forwardDistance(loopM: number, from: number, to: number): number {
  return normalise(loopM, to - from);
}

export interface ZoneExit {
  zoneId: string;
  fwdM: number; // distance forward to the end of the zone's stretch containing the position
  revM: number; // distance back to its start
  fwdBoundaryM: number; // loop position of each boundary
  revBoundaryM: number;
  direction: Direction; // the nearer boundary; a tie goes forward, the normal direction of travel
  distanceM: number;
}

// Where the nearest way out of the zone at `positionM` is.
export function zoneExit(site: Site, positionM: number): ZoneExit | undefined {
  const L = site.loopLengthM;
  const p = normalise(L, positionM);
  const zone = site.zoneAt(p);
  if (!zone) return undefined;
  for (const r of zone.ranges) {
    const into = forwardDistance(L, r.startM, p);
    if (into < r.lengthM || (r.lengthM >= L)) {
      const revM = into;
      const fwdM = r.lengthM - into;
      const direction: Direction = fwdM <= revM ? 'FWD' : 'REV';
      return {
        zoneId: zone.zoneId, fwdM, revM,
        fwdBoundaryM: normalise(L, r.startM + r.lengthM), revBoundaryM: normalise(L, r.startM),
        direction, distanceM: Math.min(fwdM, revM),
      };
    }
  }
  return undefined;
}

export interface ClearOptions {
  loaded: boolean;
  direction: Direction;
  speedMps?: number; // overrides the parameter, e.g. the pessimistic loaded reverse speed (L0.P)
  delayMs?: number; // overrides the supervisory command delay
}

// Time for a truck to cover `distanceM` under a supervisory command: speed by load and direction
// (autonomous forward, EXIT_ZONE reverse), plus the time the command takes to take effect.
export function timeToClearMs(distanceM: number, o: ClearOptions): number {
  const speed = o.speedMps ?? speedFor(o.loaded, o.direction);
  const delay = o.delayMs ?? PARAMS.supervisoryDelayMax.value;
  return (Math.max(0, distanceM) / speed) * 1000 + delay;
}

function speedFor(loaded: boolean, direction: Direction): number {
  if (direction === 'FWD') return loaded ? PARAMS.autoSpeedLoaded.value : PARAMS.autoSpeedEmpty.value;
  return loaded ? PARAMS.reverseSpeedLoaded.value : PARAMS.reverseSpeedEmpty.value;
}

// Everywhere a truck could be `elapsedMs` after it was at `anchorM`, moving forward at up to
// `fwdMps` or back at up to `revMps`. Never more than the whole loop.
export function reachableRange(loopM: number, anchorM: number, elapsedMs: number, fwdMps: number, revMps: number): Range {
  const t = Math.max(0, elapsedMs) / 1000;
  const back = Math.max(0, revMps) * t;
  const ahead = Math.max(0, fwdMps) * t;
  if (back + ahead >= loopM) return { startM: 0, lengthM: loopM };
  return { startM: normalise(loopM, anchorM - back), lengthM: back + ahead };
}

// Closed-interval overlap on the loop, with wrap.
export function rangesOverlap(loopM: number, a: Range, b: Range): boolean {
  if (a.lengthM >= loopM || b.lengthM >= loopM) return true;
  const a0 = normalise(loopM, a.startM), a1 = a0 + a.lengthM;
  const b0 = normalise(loopM, b.startM), b1 = b0 + b.lengthM;
  for (const shift of [-loopM, 0, loopM]) {
    if (a0 <= b1 + shift && b0 + shift <= a1) return true;
  }
  return false;
}

// Zone ids the range touches, in route order.
export function zonesOverlapping(site: Site, range: Range): string[] {
  return site.zones.filter((z) => z.ranges.some((r) => rangesOverlap(site.loopLengthM, range, r))).map((z) => z.zoneId);
}
// The site as hello describes it (CLAUDE.md invariant 7): route, zones, loop length and vehicles.
// Nothing here knows this particular mine. A route that doesn't add up is reported in `issues`
// rather than silently trusted; a hello with no usable route is refused.
import type { Hello, RouteSegment } from './protocol.ts';

const EPS_M = 0.01;

export interface Range {
  startM: number;
  lengthM: number; // startM + lengthM may pass the loop end, meaning the range wraps
}

export interface Segment {
  segmentId: string;
  zoneId: string;
  kind: string;
  startM: number;
  lengthM: number;
}

export interface Zone {
  zoneId: string;
  ranges: Range[];
  lengthM: number;
  segmentIds: string[];
  kinds: string[];
}

export interface Site {
  readonly siteId: string;
  readonly loopLengthM: number;
  readonly segments: readonly Segment[];
  readonly zones: readonly Zone[]; // in the order they first appear along the route
  readonly vehicles: readonly string[];
  segment(segmentId: string): Segment | undefined;
  zone(zoneId: string): Zone | undefined;
  toLoop(segmentId: string, offsetM: number): number | undefined;
  zoneAt(positionM: number): Zone | undefined;
  bayZones(): Zone[];
}

export class SiteError extends Error {}

export function buildSite(hello: Hello): { site: Site; issues: string[] } {
  const loop = hello.loop_length_m;
  if (!Array.isArray(hello.route) || hello.route.length === 0) throw new SiteError('hello has no route');
  if (!(loop > 0)) throw new SiteError(`hello has no usable loop length (${loop})`);

  const issues: string[] = [];
  const segments = [...hello.route].sort((a, b) => a.start_m - b.start_m).map(toSegment);

  const seen = new Set<string>();
  for (const s of segments) {
    if (seen.has(s.segmentId)) issues.push(`duplicate segment id ${s.segmentId}`);
    seen.add(s.segmentId);
  }
  for (let i = 1; i < segments.length; i++) {
    const prev = segments[i - 1]!, cur = segments[i]!;
    const prevEnd = prev.startM + prev.lengthM;
    if (cur.startM > prevEnd + EPS_M) issues.push(`gap of ${round(cur.startM - prevEnd)} m between ${prev.segmentId} and ${cur.segmentId}`);
    if (cur.startM < prevEnd - EPS_M) issues.push(`${prev.segmentId} and ${cur.segmentId} overlap by ${round(prevEnd - cur.startM)} m`);
  }
  const covered = segments.reduce((sum, s) => sum + s.lengthM, 0);
  if (Math.abs(covered - loop) > EPS_M) issues.push(`route covers ${round(covered)} m of a ${round(loop)} m loop`);

  const zones = buildZones(segments, loop);
  for (const z of zones) {
    if (z.ranges.length > 1) issues.push(`zone ${z.zoneId} is in ${z.ranges.length} separate stretches`);
  }

  const bySegment = new Map(segments.map((s) => [s.segmentId, s]));
  const byZone = new Map(zones.map((z) => [z.zoneId, z]));
  const norm = (p: number) => ((p % loop) + loop) % loop;

  const site: Site = {
    siteId: hello.site_id,
    loopLengthM: loop,
    segments,
    zones,
    vehicles: [...hello.vehicles],
    segment: (id) => bySegment.get(id),
    zone: (id) => byZone.get(id),
    toLoop(segmentId, offsetM) {
      const s = bySegment.get(segmentId);
      return s && Number.isFinite(offsetM) ? s.startM + offsetM : undefined;
    },
    zoneAt(positionM) {
      if (!Number.isFinite(positionM)) return undefined;
      const p = norm(positionM);
      const s = segments.find((x) => p >= x.startM - EPS_M / 2 && p < x.startM + x.lengthM);
      return s && byZone.get(s.zoneId);
    },
    bayZones: () => zones.filter((z) => z.kinds.includes('bay')),
  };
  return { site, issues };
}

function toSegment(r: RouteSegment): Segment {
  return { segmentId: r.segment_id, zoneId: r.zone_id, kind: r.kind, startM: r.start_m, lengthM: r.length_m };
}

// Consecutive segments of one zone make a range; a zone at both ends of the route is one range
// across the wrap.
function buildZones(segments: Segment[], loop: number): Zone[] {
  const runs: Array<{ zoneId: string; range: Range }> = [];
  for (const s of segments) {
    const last = runs.at(-1);
    if (last && last.zoneId === s.zoneId && Math.abs(last.range.startM + last.range.lengthM - s.startM) <= EPS_M) {
      last.range.lengthM += s.lengthM;
    } else {
      runs.push({ zoneId: s.zoneId, range: { startM: s.startM, lengthM: s.lengthM } });
    }
  }
  const first = runs[0], last = runs.at(-1);
  if (first && last && runs.length > 1 && first.zoneId === last.zoneId &&
      Math.abs(first.range.startM) <= EPS_M && Math.abs(last.range.startM + last.range.lengthM - loop) <= EPS_M) {
    last.range.lengthM += first.range.lengthM;
    runs.shift();
  }

  const order: string[] = [];
  for (const s of segments) if (!order.includes(s.zoneId)) order.push(s.zoneId);
  return order.map((zoneId) => {
    const mine = segments.filter((s) => s.zoneId === zoneId);
    const ranges = runs.filter((r) => r.zoneId === zoneId).map((r) => r.range).sort((a, b) => a.startM - b.startM);
    return {
      zoneId,
      ranges,
      lengthM: ranges.reduce((sum, r) => sum + r.lengthM, 0),
      segmentIds: mine.map((s) => s.segmentId),
      kinds: [...new Set(mine.map((s) => s.kind))],
    };
  });
}

const round = (x: number) => Math.round(x * 100) / 100;
// Injected time (CLAUDE.md invariant 1). This is the only module that touches the wall clock or
// timers; everything else takes a Clock. Times are Unix milliseconds.

export interface TimerHandle {
  readonly id: number;
}

export interface Clock {
  now(): number;
  setTimeout(fn: () => void, ms: number): TimerHandle;
  clearTimeout(handle: TimerHandle): void;
}

export class SystemClock implements Clock {
  readonly #timers = new Map<number, ReturnType<typeof globalThis.setTimeout>>();
  #nextId = 1;

  now(): number {
    return Date.now();
  }

  setTimeout(fn: () => void, ms: number): TimerHandle {
    const id = this.#nextId++;
    this.#timers.set(id, globalThis.setTimeout(() => { this.#timers.delete(id); fn(); }, ms));
    return { id };
  }

  clearTimeout(handle: TimerHandle): void {
    const t = this.#timers.get(handle.id);
    if (t !== undefined) globalThis.clearTimeout(t);
    this.#timers.delete(handle.id);
  }
}

interface Pending {
  id: number;
  due: number;
  fn: () => void;
}

// For tests: time moves only when advanced, and due timers run in order (by due time, then by the
// order they were set), each seeing now() equal to its own due time.
export class ManualClock implements Clock {
  #now: number;
  #nextId = 1;
  #pending: Pending[] = [];

  constructor(start: number) {
    this.#now = start;
  }

  now(): number {
    return this.#now;
  }

  setTimeout(fn: () => void, ms: number): TimerHandle {
    const id = this.#nextId++;
    this.#pending.push({ id, due: this.#now + Math.max(0, ms), fn });
    return { id };
  }

  clearTimeout(handle: TimerHandle): void {
    this.#pending = this.#pending.filter((p) => p.id !== handle.id);
  }

  pending(): number {
    return this.#pending.length;
  }

  advance(ms: number): void {
    if (ms < 0) throw new RangeError('a clock cannot go backwards');
    const target = this.#now + ms;
    for (let fired = 0; ; fired++) {
      if (fired > 1_000_000) throw new Error('runaway timers: over a million fired in one advance');
      const next = this.#nextDue(target);
      if (!next) break;
      this.#pending = this.#pending.filter((p) => p !== next);
      this.#now = next.due;
      next.fn();
    }
    this.#now = target;
  }

  #nextDue(target: number): Pending | undefined {
    let best: Pending | undefined;
    for (const p of this.#pending) {
      if (p.due <= target && (!best || p.due < best.due || (p.due === best.due && p.id < best.id))) best = p;
    }
    return best;
  }
}

// A time as an ISO 8601 string, for log lines. Here because this is the one module allowed to use
// Date; it formats the time it is given and never reads the clock itself.
export function isoTime(ms: number): string {
  return new Date(ms).toISOString();
}
// The one shape every source of operator attention uses: the registry (commands that failed, e-stops
// not delivered), the link, the blast engine (can't-clear), battery and data quality. The attention
// tray (UI.md) shows them; the alerting rules (TESTING.md L2.60-L2.64) decide which interrupt.
// Types only: the blast engine and the attention tray are built in parallel against this.

export type AlarmSource = 'blast' | 'registry' | 'link' | 'battery' | 'data' | 'service';

export interface AlarmRaise {
  type: 'raise';
  source: AlarmSource;
  kind: string;            // e.g. 'cant_clear', 'command_failed', 'estop_undelivered', 'controller_restart'
  key: string;             // one cause, one alarm (L2.64): the same key is the same alarm, raised once
  vehicleId: string | null;
  zoneId: string | null;
  message: string;         // in the operator's words
  action: string | null;   // the next step, e.g. "Radio the shot firer to hold the shot"
  interrupt: boolean;      // true: sound and an acknowledgement; false: visible but silent (L2.60, L2.61)
  rule: string;            // what raised it, or kept it silent, e.g. "B9" (L2.62)
  atServerMs: number;
}

export interface AlarmClear {
  type: 'clear';
  key: string;
  reason: string;          // why it cleared, e.g. "truck confirmed outside DECLINE"
  atServerMs: number;
}

export type AlarmEvent = AlarmRaise | AlarmClear;
// Is this zone clear? From belief only (CLAUDE.md invariant 6: never wrongly clear).
//
// PROVISIONAL: the blast engine (PLAN.md task 5) will own this verdict, adding "can't get out in
// time", hold-before-entry and command outcomes. Until then the UI uses this, which implements only
// invariant 6:
//   NOT_CLEAR  a live or old truck reports a position inside the zone;
//   UNSURE     otherwise, any truck whose reachable range touches the zone: silent, contradicted or
//              never heard from, or a live truck at the boundary that might already be in;
//   CLEAR      no truck might be inside.
// NOT_CLEAR and UNSURE carry the same action, because in doubt the shot is held (CONTEXT.md answer 1).
// CLEAR here says nothing about trucks that may still drive in before the zone closes.
import type { TruckView, ZoneView } from './fleet.ts';
import { age, faultWords, positionAgeMs } from './words.ts';

export type Verdict = 'CLEAR' | 'NOT_CLEAR' | 'UNSURE';

export const HOLD_THE_SHOT = 'Radio the shot firer to hold the shot';

export interface ClearanceReason {
  vehicleIds: string[];
  certainty: 'inside' | 'might';
  why: string;
}

export interface Clearance {
  zoneId: string;
  verdict: Verdict;
  action: string | null;
  reasons: ClearanceReason[]; // the certain ones first
}

export function mightBeIn(t: TruckView, zoneId: string): boolean {
  return t.range === null || t.mightBeIn.includes(zoneId);
}

export function zoneClearance(zone: ZoneView, trucks: readonly TruckView[]): Clearance {
  const inside: ClearanceReason[] = [];
  const might: ClearanceReason[] = [];
  const neverHeard: string[] = [];
  for (const t of trucks) {
    if (!mightBeIn(t, zone.zoneId)) continue;
    const extra = [faultWords(t), t.state?.value === 'ESTOPPED' ? 'e-stopped' : null].filter((x) => x !== null);
    const tail = extra.length ? `; ${extra.join('; ')}` : '';
    const reportedIn = t.position?.value.zoneId === zone.zoneId;
    switch (t.confidence) {
      case 'live':
      case 'old': {
        const fresh = t.confidence === 'old' ? ` (old ${age(positionAgeMs(t) ?? 0)})` : '';
        if (reportedIn) inside.push({ vehicleIds: [t.vehicleId], certainty: 'inside', why: `inside${fresh}${tail}` });
        else might.push({ vehicleIds: [t.vehicleId], certainty: 'might', why: `at the boundary, might already be in${fresh}${tail}` });
        break;
      }
      case 'silent':
        might.push({ vehicleIds: [t.vehicleId], certainty: 'might', why: `silent ${age(positionAgeMs(t) ?? 0)}: could have reached it${lastSeen(t)}${tail}` });
        break;
      case 'contradicted':
        might.push({ vehicleIds: [t.vehicleId], certainty: 'might', why: `data frozen: reports moving but has not moved${lastSeen(t)}${tail}` });
        break;
      case 'unknown':
        if (t.ageMs === null) neverHeard.push(t.vehicleId);
        else might.push({ vehicleIds: [t.vehicleId], certainty: 'might', why: `no valid position: could be anywhere${tail}` });
        break;
    }
  }
  if (neverHeard.length) might.push({ vehicleIds: neverHeard, certainty: 'might', why: 'never reported: could be anywhere' });
  const verdict: Verdict = inside.length ? 'NOT_CLEAR' : might.length ? 'UNSURE' : 'CLEAR';
  return { zoneId: zone.zoneId, verdict, action: verdict === 'CLEAR' ? null : HOLD_THE_SHOT, reasons: [...inside, ...might] };
}

function lastSeen(t: TruckView): string {
  const z = t.position?.value.zoneId;
  return z ? `; last seen in ${z}` : '';
}

