325	    // The snapshot replaces what we knew. A route zone missing from it is unknown, not open.
326	    const at = serverTimeOf(h as unknown as Record<string, unknown>) ?? this.serverNow();
327	    const listed = new Set<string>();
328	    for (const raw of Array.isArray(h.zones) ? h.zones : []) {
329	      const { zone, issues } = validateZone(raw);
330	      for (const i of issues) this.#linkDq(i, JSON.stringify(raw));
331	      if (!zone) continue;
332	      listed.add(zone.zoneId);
333	      this.#setZone({ ...zone, updatedServerMs: at });
334	    }
335	    for (const z of built.site.zones) {
336	      if (!listed.has(z.zoneId)) this.#setZone({ zoneId: z.zoneId, status: null, reason: null, effectiveAtMs: null, updatedServerMs: at });
