341	  #zoneEvent(m: Record<string, unknown>, st: number | undefined): void {
342	    const { zone, issues } = validateZone(m);
343	    for (const i of issues) this.#linkDq(i, JSON.stringify(m));
344	    if (!zone) return;
345	    const prev = this.#zones.get(zone.zoneId);
346	    if (st !== undefined && prev?.updatedServerMs != null && st < prev.updatedServerMs) {
347	      this.#linkDq('zone_event:stale', `${zone.zoneId} ${zone.status} at ${st}, after ${prev.updatedServerMs}`);
348	      return;
349	    }
350	    this.#setZone({ ...zone, updatedServerMs: st ?? this.serverNow() });
351	  }
352	
353	  #setZone(z: ZoneRecord): void {
354	    const prev = this.#zones.get(z.zoneId);
355	    this.#zones.set(z.zoneId, z);
356	    if (!prev || prev.status !== z.status || prev.effectiveAtMs !== z.effectiveAtMs || prev.reason !== z.reason) {
357	      this.#emit({ type: 'zone', zoneId: z.zoneId, status: z.status, reason: z.reason, effectiveAtMs: z.effectiveAtMs, atServerMs: this.serverNow() });
