359	  }
360	
361	  // ---- telemetry ----
362	
363	  #telemetry(m: Record<string, unknown>): void {
364	    const v = validateTelemetry(m, this.#site);
365	    if (!v.fields) { this.#linkDq('bad_message', `telemetry: ${v.issues.map((i) => i.detail).join('; ')}`); return; }
366	    const f = v.fields;
367	    const t = this.#truckFor(f.vehicleId);
368	    if (f.seq === undefined) {
369	      this.#truckDq(t, 'seq:invalid', v.issues.find((i) => i.field === 'seq')?.detail ?? 'seq unusable');
370	      return;
371	    }
372	    if (f.tDeviceMs === undefined) {
373	      const i = v.issues.find((x) => x.field === 't_device_ms');
374	      if (i) this.#truckDq(t, i.kind, i.detail);
375	    }
376	    const body = JSON.stringify(m);
377	    const verdict = this.#order(t, f.seq, f.tDeviceMs, body);
378	    if (verdict === 'duplicate') { t.radio.duplicates++; return; }
379	    if (verdict === 'older') { t.radio.older++; return; }
380	    if (verdict === 'conflict') { this.#truckDq(t, 'seq:conflict', `seq ${f.seq} arrived twice with different contents`); return; }
381	    for (const i of v.issues) if (i.field !== 't_device_ms') this.#truckDq(t, i.kind, i.detail);
382	    this.#apply(t, f);
383	    this.#evaluate(t);
384	  }
385	
386	  // Order by seq within a controller run (CONTEXT.md assumption 3).
387	  #order(t: Truck, seq: number, tDev: number | undefined, body: string): 'apply' | 'duplicate' | 'older' | 'conflict' {
388	    const window = PARAMS.reorderWindow.value;
389	    const run = t.run;
390	    const begin = (index: number) => {
391	      t.run = { index, startTDev: tDev, maxSeq: seq, tDevAtMax: tDev, seen: new Map([[seq, body]]) };
392	    };
393	    if (!run) { begin(0); return 'apply'; }
394	    const seen = run.seen.get(seq);
395	    if (seen !== undefined) return seen === body ? 'duplicate' : 'conflict';
396	    if (seq > run.maxSeq) {
397	      // A late message from the previous run can carry a higher seq than the new run has reached;
398	      // its device time gives it away.
399	      if (t.restarts > 0 && tDev !== undefined && run.startTDev !== undefined && tDev < run.startTDev) return 'older';
400	      run.seen.set(seq, body);
401	      run.maxSeq = seq;
402	      run.tDevAtMax = tDev;
403	      for (const s of run.seen.keys()) if (s < seq - 4 * window) run.seen.delete(s);
404	      return 'apply';
405	    }
406	    const forward = tDev !== undefined && run.tDevAtMax !== undefined && tDev > run.tDevAtMax;
407	    if (forward && (run.maxSeq - seq > window || seq <= window)) {
408	      const from = run.maxSeq;
409	      t.restarts++;
410	      begin(run.index + 1);
411	      t.drainPrev = null;
412	      t.dq.controller_restart = (t.dq.controller_restart ?? 0) + 1;
413	      this.#emit({ type: 'controller_restart', vehicleId: t.vehicleId, detail: `seq went from ${from} to ${seq} while its clock moved forward: controller restarted`, atServerMs: this.serverNow() });
414	      return 'apply';
415	    }
416	    run.seen.set(seq, body);
417	    return 'older';
418	  }
419	
420	  #apply(t: Truck, f: TelemetryFields): void {
421	    const at = this.#clock.now();
422	    t.lastAccepted = at;
423	    t.radio.applied++;
424	    const set = <K extends 'state' | 'task' | 'speed' | 'direction' | 'payload' | 'faults' | 'control' | 'position'>(k: K, v: Truck[K] extends Stored<infer T> | undefined ? T | undefined : never) => {
425	      if (v !== undefined) (t as unknown as Record<string, unknown>)[k] = { value: v, atLocal: at };
426	    };
427	    if (f.state !== undefined && t.state?.value !== f.state) t.stateSince = at;
428	    set('state', f.state);
429	    set('task', f.task);
430	    set('speed', f.speedMps);
431	    set('direction', f.direction);
432	    set('payload', f.payloadKg);
433	    set('faults', f.faults);
434	    set('control', f.control);
435	
436	    if (f.socPct !== undefined) {
437	      const frac = this.#isFractional(t, f.socPct);
438	      if (frac && !t.socFractional) this.#truckDq(t, 'soc_pct:fractional', `soc_pct ${f.socPct} looks like a fraction of 1, not a percentage; shown as reported`);
439	      t.socFractional = frac;
440	      t.soc = { value: f.socPct, atLocal: at };
441	    }
442	
443	    if (f.tDeviceMs !== undefined) {
444	      t.skewMs = f.tDeviceMs - this.serverNow();
445	      const flagged = Math.abs(t.skewMs) > PARAMS.deviceSkewFlagAbove.value;
446	      if (flagged && !t.skewFlagged) this.#truckDq(t, 'clock_skew', `device clock is ${(t.skewMs / 60_000).toFixed(1)} min off server time`);
447	      t.skewFlagged = flagged;
448	    }
449	
450	    if (f.position) {
451	      t.position = { value: f.position, atLocal: at };
452	      this.#trackStill(t, f.position.loopM, at);
453	    }
454	    this.#trackDrain(t, at);
455	  }
456	
457	  // A value in 0..1 is a fraction unless the pack has been draining smoothly down into it. Zero
458	  // reads the same either way.
459	  #isFractional(t: Truck, soc: number): boolean {
460	    if (soc > 1 || soc === 0) return false;
461	    const prev = t.soc?.value;
462	    if (prev === undefined || t.socFractional) return true;
463	    return prev - soc > PARAMS.fractionalSocJump.value;
464	  }
465	
466	  #trackStill(t: Truck, pos: number, at: number): void {
467	    const speed = t.speed?.value;
468	    const moving = t.state !== undefined && MOVING_STATES.has(t.state.value) && speed !== undefined && speed >= PARAMS.frozenMinReportedSpeed.value;
469	    const s = t.still;
470	    if (!s || this.#gap(pos, s.pos) >= PARAMS.frozenMaxMovement.value) {
471	      t.still = { pos, firstAt: at, lastStationaryAt: moving ? null : at, movingSince: moving ? at : null, repeats: 0 };
472	    } else if (moving) {
473	      if (s.movingSince === null) { s.movingSince = at; s.repeats = 0; } else s.repeats++;
474	    } else {
475	      s.lastStationaryAt = at;
476	      s.movingSince = null;
477	      s.repeats = 0;
478	    }
479	  }
480	
481	  #gap(a: number, b: number): number {
482	    const L = this.#site?.loopLengthM;
483	    if (!L) return Math.abs(a - b);
484	    const d = forwardDistance(L, a, b);
485	    return Math.min(d, L - d);
486	  }
487	
488	  #isContradicted(t: Truck, now: number): boolean {
489	    const s = t.still;
490	    return !!s && s.movingSince !== null && s.repeats >= 1 && now - s.movingSince >= PARAMS.frozenAfter.value;
491	  }
492	
493	  #trackDrain(t: Truck, at: number): void {
494	    const site = this.#site;
495	    const pos = t.position, soc = t.soc, payload = t.payload;
496	    // Only an interval whose ends were both reported in this message pair counts.
497	    if (!site || !pos || pos.atLocal !== at || !soc || soc.atLocal !== at || !payload || t.socFractional) return;
498	    const cur: DrainPoint = { loopM: pos.value.loopM, soc: soc.value, loaded: payload.value > 0, atLocal: at, runIndex: t.run?.index ?? 0 };
499	    const prev = t.drainPrev;
500	    t.drainPrev = cur;
501	    if (!prev || prev.runIndex !== cur.runIndex || prev.loaded !== cur.loaded || at - prev.atLocal > PARAMS.drainMaxGap.value) return;
502	    if (t.state?.value === 'CHARGING' || this.#isContradicted(t, at)) return;
503	    const drop = prev.soc - cur.soc;
504	    if (drop < 0) return;
505	    const L = site.loopLengthM;
506	    const dist = t.direction?.value === 'REV' ? forwardDistance(L, cur.loopM, prev.loopM) : forwardDistance(L, prev.loopM, cur.loopM);
507	    const plausible = (PARAMS.manualSpeedEmptyFull.value * (at - prev.atLocal)) / 1000 + PARAMS.frozenMaxMovement.value;
508	    if (dist > plausible) return;
509	    t.drain.add(cur.loaded, drop, dist);
510	  }
511	
512	  // ---- evaluation ----
513	
514	  // Precedence: no data at all; then silence, the most basic fact; then contradiction; then the age
515	  // of the position. A frozen truck that goes quiet is silent, and its range keeps the pre-freeze
516	  // anchor (#rangeOf).
517	  #confidence(t: Truck, now: number): { c: Confidence; reason: string } {
518	    if (t.lastAccepted === null) return { c: 'unknown', reason: 'no data received yet' };
519	    const silent = PARAMS.truckSilentAfter.value, old = PARAMS.truckOldAfter.value;
520	    const msgAge = now - t.lastAccepted;
521	    const frozen = this.#isContradicted(t, now);
522	    if (msgAge >= silent && t.position) {
523	      return { c: 'silent', reason: `no message for ${secs(msgAge)}${frozen ? '; its last data was frozen' : ''}` };
524	    }
525	    if (frozen) {
526	      const s = t.still!;
527	      return { c: 'contradicted', reason: `reports ${t.state?.value ?? '?'} at ${t.speed?.value ?? '?'} m/s but has not moved for ${secs(now - s.movingSince!)}` };
528	    }
529	    if (!t.position) return { c: 'unknown', reason: msgAge >= silent ? `no message for ${secs(msgAge)}, and never a valid position` : 'no valid position reported yet' };
530	    const posAge = now - t.position.atLocal;
531	    if (posAge >= silent) return { c: 'silent', reason: `no valid position for ${secs(posAge)}; messages still arriving` };
532	    if (posAge >= old) return { c: 'old', reason: `last position ${secs(posAge)} ago` };
533	    const link = this.#link;
534	    if (link && !link.up) return { c: 'old', reason: `site link down for ${secs(now - link.sinceLocal)}; last position ${secs(posAge)} ago` };
535	    return { c: 'live', reason: 'reporting normally' };
536	  }
537	
538	  #rangeOf(t: Truck, now: number, c: Confidence): { anchor: { loopM: number; atLocal: number } | null; range: Range | null } {
539	    const site = this.#site;
540	    if (!site) return { anchor: null, range: null };
541	    if (!t.position) return { anchor: null, range: { startM: 0, lengthM: site.loopLengthM } };
542	    const s = t.still;
543	    const anchor = this.#isContradicted(t, now) && s
544	      ? { loopM: s.pos, atLocal: s.lastStationaryAt ?? s.firstAt }
545	      : { loopM: t.position.value.loopM, atLocal: t.position.atLocal };
546	    const manual = t.control?.value.mode === 'MANUAL' || t.state?.value === 'MANUAL' || (t.control?.value.operatorId ?? null) !== null;
547	    const top = Math.max(t.speed?.value ?? 0, manual ? PARAMS.manualSpeedEmptyFull.value : PARAMS.autoSpeedEmpty.value);
548	    // Blunter when stale (CONTEXT.md finding 4): a silent or contradicted truck may be going either way.
549	    const canReverse = c === 'silent' || c === 'contradicted' || manual || (t.task?.value ?? null) !== null ||
550	      t.direction?.value !== 'FWD' || t.state === undefined;
551	    const elapsed = now - anchor.atLocal + PARAMS.telemetryLatencyAllowance.value;
552	    return { anchor, range: reachableRange(site.loopLengthM, anchor.loopM, elapsed, top, canReverse ? top : 0) };
553	  }
554	
555	  #battery(t: Truck, fleet: { emptyPctPerM: number | null; loadedPctPerM: number | null }, rates: Rates): BatteryView {
556	    const ownEmpty = t.drain.empty.rate(), ownLoaded = t.drain.loaded.rate();
557	    const fleetEmpty = fleetMedianExcluding(rates.empty, t.vehicleId);
558	    const fleetLoaded = fleetMedianExcluding(rates.loaded, t.vehicleId);
559	    const ratio = { empty: ownEmpty !== null && fleetEmpty ? ownEmpty / fleetEmpty : null, loaded: ownLoaded !== null && fleetLoaded ? ownLoaded / fleetLoaded : null };
560	    const flag = PARAMS.drainRatioFlag.value;
561	    const a = assess({
562	      site: this.#site, socPct: t.soc?.value, socFractional: t.socFractional, positionM: t.position?.value.loopM,
563	      loaded: t.payload ? t.payload.value > 0 : undefined, state: t.state?.value, task: t.task?.value, faults: t.faults?.value,
564	      ownEmpty, ownLoaded, fleet,
565	    });
566	    return {
567	      drain: { emptyPctPerKm: perKm(ownEmpty), loadedPctPerKm: perKm(ownLoaded), emptyEvidenceM: t.drain.empty.evidenceM, loadedEvidenceM: t.drain.loaded.evidenceM },
568	      ratioToFleet: ratio,
569	      drainHigh: (ratio.empty ?? 0) >= flag || (ratio.loaded ?? 0) >= flag,
570	      reach: a.reach, warning: a.warning, message: a.message,
571	    };
572	  }
573	
574	  #rates(): Rates {
575	    const all = [...this.#trucks.values()];
576	    return {
577	      empty: all.map((t) => ({ id: t.vehicleId, rate: t.drain.empty.rate() })),
578	      loaded: all.map((t) => ({ id: t.vehicleId, rate: t.drain.loaded.rate() })),
579	    };
580	  }
581	
582	  #fleetDrain(): { emptyPctPerM: number | null; loadedPctPerM: number | null; rates: Rates } {
583	    const rates = this.#rates();
584	    const med = (xs: Array<{ rate: number | null }>) => {
585	      const known = xs.filter((x) => x.rate !== null).map((x) => x.rate!);
586	      return known.length >= PARAMS.fleetMinTrucks.value ? median(known) : null;
587	    };
588	    return { emptyPctPerM: med(rates.empty), loadedPctPerM: med(rates.loaded), rates };
589	  }
590	
591	  #evaluate(t: Truck): void {
592	    const now = this.#clock.now();
593	    const { c, reason } = this.#confidence(t, now);
594	    if (c !== t.lastConfidence) {
595	      if (c === 'contradicted') t.frozenEpisodes++;
596	      this.#emit({ type: 'confidence', vehicleId: t.vehicleId, from: t.lastConfidence, to: c, reason, atServerMs: this.serverNow() });
597	      t.lastConfidence = c;
598	    }
599	    const fleet = this.#fleetDrain();
600	    const b = this.#battery(t, fleet, fleet.rates);
601	    const key = `${b.warning}|${b.drainHigh}`;
602	    if (key !== t.lastBattery) {
603	      if (t.lastBattery !== '' || b.warning !== null || b.drainHigh) {
604	        this.#emit({ type: 'battery', vehicleId: t.vehicleId, warning: b.warning, drainHigh: b.drainHigh, message: b.message, atServerMs: this.serverNow() });
605	      }
606	      t.lastBattery = key;
607	    }
608	  }
609	
610	  #view(t: Truck, now: number, fleet: { emptyPctPerM: number | null; loadedPctPerM: number | null; rates: Rates }): TruckView {
611	    const { c, reason } = this.#confidence(t, now);
612	    const { anchor, range } = this.#rangeOf(t, now, c);
613	    const off = this.#offset();
614	    const known = <T>(s: Stored<T> | undefined): Known<T> | null => (s ? { value: s.value, atServerMs: s.atLocal + off, ageMs: now - s.atLocal } : null);
615	    const site = this.#site;
616	    return {
617	      vehicleId: t.vehicleId,
618	      onRoster: t.onRoster,
619	      confidence: c,
620	      confidenceReason: reason,
621	      lastMessageServerMs: t.lastAccepted === null ? null : t.lastAccepted + off,
622	      ageMs: t.lastAccepted === null ? null : now - t.lastAccepted,
623	      state: known(t.state),
624	      stateSinceServerMs: t.stateSince === null ? null : t.stateSince + off,
625	      task: known(t.task),
626	      socPct: known(t.soc),
627	      socFractional: t.socFractional,
628	      speedMps: known(t.speed),
629	      direction: known(t.direction),
630	      payloadKg: known(t.payload),
631	      loaded: t.payload ? t.payload.value > 0 : null,
632	      faults: known(t.faults),
633	      control: known(t.control),
634	      position: known(t.position),
635	      anchor: anchor && { loopM: anchor.loopM, atServerMs: anchor.atLocal + off },
636	      range,
637	      mightBeIn: site && range ? zonesOverlapping(site, range) : [],
638	      frozenEpisodes: t.frozenEpisodes,
639	      skewMs: t.skewMs,
640	      skewFlagged: t.skewFlagged,
641	      run: { index: t.run?.index ?? 0, restarts: t.restarts, seq: t.run?.maxSeq ?? null },
642	      radio: { ...t.radio },
643	      dataQuality: { ...t.dq },
644	      battery: this.#battery(t, fleet, fleet.rates),
645	    };
646	  }
647	
648	  // ---- bookkeeping ----
649	
650	  #truckFor(id: string): Truck {
651	    let t = this.#trucks.get(id);
652	    if (!t) {
653	      t = new Truck(id);
654	      this.#trucks.set(id, t);
655	      if (this.#site) {
656	        t.onRoster = this.#roster.includes(id);
657	        if (!t.onRoster) this.#truckDq(t, 'unknown_vehicle', `${id} is not on the roster from hello`);
658	      }
659	    }
660	    return t;
661	  }
662	
663	  #orderedTrucks(): Truck[] {
664	    const rostered = this.#roster.map((id) => this.#trucks.get(id)).filter((t): t is Truck => !!t);
665	    const others = [...this.#trucks.values()].filter((t) => !this.#roster.includes(t.vehicleId)).sort((a, b) => a.vehicleId.localeCompare(b.vehicleId));
666	    return [...rostered, ...others];
667	  }
668	
669	  #truckDq(t: Truck, kind: string, detail: string): void {
670	    t.dq[kind] = (t.dq[kind] ?? 0) + 1;
671	    this.#emit({ type: 'data_quality', vehicleId: t.vehicleId, kind, detail, atServerMs: this.serverNow() });
672	  }
673	
674	  #linkDq(kind: string, detail: string): void {
675	    this.#dqTotal[kind] = (this.#dqTotal[kind] ?? 0) + 1;
676	    this.#dqConnection[kind] = (this.#dqConnection[kind] ?? 0) + 1;
677	    if (kind !== 'blank') this.#emit({ type: 'data_quality', vehicleId: null, kind, detail: detail.slice(0, 200), atServerMs: this.serverNow() });
678	  }
679	
680	  #sample(serverMs: number): void {
681	    this.#offsets.push(serverMs - this.#clock.now());
682	    while (this.#offsets.length > PARAMS.serverTimeSamples.value) this.#offsets.shift();
683	  }
684	
685	  #offset(): number {
686	    return this.#offsets.length ? Math.max(...this.#offsets) : 0;
687	  }
688	
689	  #emit(e: FleetEvent): void {
690	    for (const fn of this.#listeners) fn(e);
691	  }
692	}
