193	  systemOperatorId?: string;                                 // prefix of the operator_id the gateway sees for the system: "<prefix>:<rule>"
194	  keepClosed?: number;                                       // closed records kept in memory
195	}
196	
197	// ---- action classes ----
198	
199	const SUPERVISORY: ReadonlySet<Action> = new Set<Action>(['HOLD', 'RESUME', 'RETURN_TO_BAY', 'EXIT_ZONE']);
200	const QUEUEABLE: ReadonlySet<Action> = new Set<Action>(['HOLD', 'RETURN_TO_BAY', 'EXIT_ZONE']); // PROTOCOL.md §5 Queuing
201	const IMMEDIATE: ReadonlySet<Action> = new Set<Action>(['ESTOP', 'TAKE_CONTROL', 'RELEASE_CONTROL']);  // §5: on receipt
202	const WORK: ReadonlySet<string> = new Set<WorkState>(['LOADING', 'DUMPING', 'CHARGING']);
203	const DUTY_CYCLE: ReadonlySet<string> = new Set<VehicleState>(['TRAMMING', 'LOADING', 'DUMPING', 'CHARGING']);
204	// Refusals the registry gives itself, not the site.
205	const LOCAL = { forceNeedsSupervisor: 'FORCE_NEEDS_SUPERVISOR', unknownAction: 'UNSUPPORTED_ACTION_LOCAL' } as const;
206	
207	// The effect deadline of a supervisory command, from its send: the site's 1-6 s delay, plus how
208	// late telemetry can describe the truck, plus the trip to the gateway.
209	export function supervisoryDeadlineMs(): number {
210	  return PARAMS.supervisoryDelayMax.value + PARAMS.telemetryLatencyAllowance.value + PARAMS.commandUplinkAllowance.value;
211	}
212	
213	const secs = (ms: number) => `${(ms / 1000).toFixed(1)} s`;
214	
215	export class CommandRegistry {
216	  readonly #clock: Clock;
217	  readonly #fleet: FleetState;
218	  readonly #store: Store;
219	  readonly #transport: CommandTransport;
220	  readonly #gate: SafetyGate;
221	  readonly #newId: () => string;
222	  readonly #commandIdFor: (recordId: string, attempt: number) => string;
223	  readonly #systemOperatorId: string;
224	  readonly #keepClosed: number;
225	  readonly #book = new AckBook();
226	  readonly #records = new Map<string, CommandRecord>();
227	  readonly #byCommandId = new Map<string, { rec: CommandRecord; attempt: Attempt }>();
228	  readonly #leases = new Map<string, LeaseInfo>();
229	  readonly #listeners = new Set<(e: RegistryEvent) => void>();
230	  #timer: TimerHandle | null = null;
231	
232	  constructor(o: RegistryOptions) {
233	    this.#clock = o.clock;
234	    this.#fleet = o.fleet;
235	    this.#store = o.store;
236	    this.#transport = o.transport;
237	    this.#gate = o.gate;
238	    this.#newId = o.newId ?? (() => crypto.randomUUID());
239	    this.#commandIdFor = o.commandIdFor ?? ((id, n) => `${id}-a${n}`);
240	    this.#systemOperatorId = o.systemOperatorId ?? 'system';
241	    this.#keepClosed = o.keepClosed ?? 500;
242	    this.#restore();
243	  }
244	
245	  subscribe(fn: (e: RegistryEvent) => void): () => void {
246	    this.#listeners.add(fn);
247	    return () => this.#listeners.delete(fn);
248	  }
249	
250	  start(intervalMs = 250): void {
251	    this.stop();
252	    const loop = () => { this.tick(); this.#timer = this.#clock.setTimeout(loop, intervalMs); };
253	    this.#timer = this.#clock.setTimeout(loop, intervalMs);
254	  }
255	
256	  stop(): void {
257	    if (this.#timer) this.#clock.clearTimeout(this.#timer);
258	    this.#timer = null;
259	  }
260	
261	  get(id: string): CommandRecord | undefined {
262	    const r = this.#records.get(id);
263	    return r && structuredClone(r);
264	  }
265	
266	  list(filter: { open?: boolean; vehicleId?: string } = {}): CommandRecord[] {
267	    return [...this.#records.values()]
268	      .filter((r) => (filter.open === undefined || OPEN_STATUSES.has(r.status) === filter.open) && (filter.vehicleId === undefined || r.vehicleId === filter.vehicleId))
269	      .map((r) => structuredClone(r));
270	  }
271	
272	  lease(vehicleId: string): LeaseInfo | undefined {
273	    const l = this.#leases.get(vehicleId);
274	    return l && { ...l };
275	  }
276	
277	  leases(): LeaseInfo[] {
278	    return [...this.#leases.values()].map((l) => ({ ...l }));
279	  }
280	
281	  // ---- callers ----
282	
283	  // The one way to command a truck. `actor` comes from the server's session or the rule that fired;
284	  // anything resembling an operator id inside `req` is ignored (L8.3).
285	  submit(req: SubmitRequest, actor: Actor): CommandRecord {
286	    const now = this.#clock.now();
287	    const vehicleId = String(req.vehicleId);
288	    const action = req.action;
289	
290	    if (action === 'ESTOP') {
291	      const open = this.#openOn(vehicleId).find((r) => r.action === 'ESTOP');
292	      if (open) {
293	        if (open.hold?.needsReconfirm) return this.reconfirm(open.id, actor) ?? structuredClone(open);
294	        return structuredClone(open);
295	      }
296	    }
297	
298	    const rec: CommandRecord = {
299	      id: this.#newId(), vehicleId, action, force: action === 'TAKE_CONTROL' && req.force === true,
300	      leaseId: action === 'RELEASE_CONTROL' ? (req.leaseId ?? this.#leaseIdFor(vehicleId, actor)) : null,
301	      actor: cloneActor(actor), why: req.why ?? (actor.kind === 'system' ? actor.rule : null),
302	      createdMs: now, createdServerMs: this.#fleet.serverNow(), updatedMs: now, closedServerMs: null,
303	      status: 'pending', attempts: [], maxAttempts: action === 'ESTOP' ? PARAMS.estopMaxAttempts.value : PARAMS.commandMaxAttempts.value,
304	      hold: null, deadlineMs: null, queued: null, targetZone: null, baselineState: null, started: null, effect: null,
305	      pendingRefusal: null, failure: null, supersededBy: null, summary: '',
306	    };
307	    this.#records.set(rec.id, rec);
308	    this.#audit(rec, 'submitted', `${action} ${vehicleId} requested`);
309	
310	    if (!(ACTIONS as readonly string[]).includes(action)) {
311	      this.#close(rec, 'refused', { code: LOCAL.unknownAction, message: `"${String(action)}" is not a command the site understands.`, ourFault: true });
312	      return structuredClone(rec);
313	    }
314	    if (rec.force && !(actor.kind === 'operator' && actor.role === 'supervisor')) {
315	      this.#close(rec, 'refused', { code: LOCAL.forceNeedsSupervisor, message: `Only a supervisor can take ${vehicleId} from another operator.`, ourFault: false });
316	      return structuredClone(rec);
317	    }
318	    const verdict = this.#gate.check({ record: rec, attempt: 1, replay: false, truck: this.#fleet.truck(vehicleId) });
319	    if (!verdict.allow) {
320	      this.#close(rec, 'refused', { code: verdict.code, message: verdict.reason, ourFault: false });
321	      return structuredClone(rec);
322	    }
323	
324	    this.#supersedeFor(rec);
325	    if (this.#transport.isUp()) {
326	      this.#sendAttempt(rec, 'first');
327	    } else {
328	      rec.hold = { sinceMs: now, autoSendUntilMs: now + PARAMS.estopAutoSendWithin.value, needsReconfirm: false };
329	      this.#save(rec, 'waiting', `${action} ${vehicleId} not sent: the site link is down. Sent automatically if it returns within ${secs(PARAMS.estopAutoSendWithin.value)}`);
330	      if (action === 'ESTOP') this.#emit({ type: 'alarm', kind: 'estop_undelivered', vehicleId, recordId: rec.id, message: `E-stop for ${vehicleId} NOT delivered: the site link is down. It will be sent if the link returns within ${secs(PARAMS.estopAutoSendWithin.value)}; you can cancel it.` });
331	    }
332	    return structuredClone(rec);
333	  }
334	
335	  // Cancel a command still waiting for the link (L7.8).
336	  cancel(id: string, actor: Actor): CommandRecord | undefined {
337	    const rec = this.#records.get(id);
338	    if (!rec) return undefined;
339	    if (rec.status !== 'pending' || !rec.hold) return structuredClone(rec);
340	    this.#close(rec, 'cancelled', null, actor, `${rec.action} ${rec.vehicleId} cancelled before it was sent`);
341	    return structuredClone(rec);
342	  }
343	
344	  // Confirm again a command that waited too long for the link (L7.8): the operator has now seen the
345	  // truck as it is.
346	  reconfirm(id: string, actor: Actor): CommandRecord | undefined {
347	    const rec = this.#records.get(id);
348	    if (!rec) return undefined;
349	    if (rec.status !== 'pending' || !rec.hold?.needsReconfirm) return structuredClone(rec);
350	    const now = this.#clock.now();
351	    this.#audit(rec, 'reconfirmed', `${rec.action} ${rec.vehicleId} confirmed again`, actor);
352	    if (this.#transport.isUp()) {
353	      rec.hold = null;
354	      this.#sendAttempt(rec, 'first');
355	    } else {
356	      rec.hold = { sinceMs: now, autoSendUntilMs: now + PARAMS.estopAutoSendWithin.value, needsReconfirm: false };
357	      this.#save(rec);
358	    }
359	    return structuredClone(rec);
360	  }
361	
362	  // ---- from the link ----
363	
364	  linkUp(hello: Hello): void {
365	    const at = this.#fleet.serverNow();
366	    this.#leases.clear();
367	    for (const l of Array.isArray(hello.leases) ? hello.leases : []) {
368	      if (l && typeof l.vehicle_id === 'string' && typeof l.operator_id === 'string') {
369	        this.#leases.set(l.vehicle_id, { vehicleId: l.vehicle_id, operatorId: l.operator_id, leaseId: null, sinceServerMs: at });
370	      }
371	    }
372	    const now = this.#clock.now();
373	    for (const rec of this.#openSorted()) {
374	      if (rec.hold) {
375	        if (rec.hold.needsReconfirm) continue;
376	        if (now <= rec.hold.autoSendUntilMs) {
377	          rec.hold = null;
378	          this.#sendAttempt(rec, rec.attempts.length === 0 ? 'first' : 'replay');
379	        } else {
380	          this.#holdTimedOut(rec);
381	        }
382	        continue;
383	      }
384	      if (rec.deadlineMs !== null && now > rec.deadlineMs) {
385	        this.#close(rec, 'expired', { code: 'LINK_DOWN_PAST_DEADLINE', message: `The site link was down past this command's deadline, so it was not sent again. Check ${rec.vehicleId} as it is now and send again if needed.`, ourFault: false });
386	        continue;
387	      }
388	      this.#sendAttempt(rec, 'replay');
389	    }
390	  }
391	
392	  // Deadlines stop while the link is down: nothing can be seen or sent. On reconnect, linkUp replays
393	  // what is still within its deadline and expires the rest.
394	  linkDown(reason: string): void {
395	    for (const rec of this.#openSorted()) {
396	      if (rec.status !== 'pending') this.#audit(rec, 'link_down', `site link down while ${rec.action} ${rec.vehicleId} was ${rec.status}: ${reason}`, { kind: 'system', rule: 'gateway-link' });
397	    }
398	  }
399	
400	  // Every message from the gateway, after fleet state has taken it in.
401	  message(m: { type?: unknown; [k: string]: unknown }): void {
402	    switch (m.type) {
403	      case 'telemetry':
404	        if (typeof m.vehicle_id === 'string' && this.#hasOpen(m.vehicle_id)) this.#evaluate(m.vehicle_id);
405	        break;
406	      case 'command_ack': this.#ack(m); break;
407	      case 'lease_event': this.#leaseEvent(m); break;
408	      default: break;
409	    }
410	  }
411	
412	  // Deadlines and the link-down hold window. Runs on a timer (start) or by hand in tests.
413	  tick(): void {
414	    const now = this.#clock.now();
415	    for (const rec of this.#openSorted()) {
416	      if (rec.hold) {
417	        if (!rec.hold.needsReconfirm && now > rec.hold.autoSendUntilMs) this.#holdTimedOut(rec);
418	        continue;
419	      }
420	      if (this.#transport.isUp() && rec.deadlineMs !== null && now >= rec.deadlineMs) this.#onDeadline(rec);
421	    }
422	  }
423	
424	  // ---- sending ----
425	
426	  #sendAttempt(rec: CommandRecord, kind: 'first' | 'retry' | 'replay'): void {
427	    const now = this.#clock.now();
428	    const replay = kind === 'replay';
429	    let attempt = rec.attempts.at(-1);
430	    if (!replay || !attempt) {
431	      const n = rec.attempts.length + 1;
432	      attempt = { n, commandId: this.#commandIdFor(rec.id, n), sends: [], ack: null, duplicateAcks: 0 };
433	    }
434	    const truck = this.#fleet.truck(rec.vehicleId);
435	    const verdict = this.#gate.check({ record: rec, attempt: attempt.n, replay, truck });
436	    if (!verdict.allow) {
437	      this.#close(rec, 'refused', { code: verdict.code, message: verdict.reason, ourFault: false });
438	      return;
439	    }
440	    if (!rec.attempts.includes(attempt)) {
441	      rec.attempts.push(attempt);
442	      this.#byCommandId.set(attempt.commandId, { rec, attempt });
443	    }
444	    if (attempt.n === 1 && !replay) {
445	      rec.baselineState = truck?.state?.value ?? null;
446	      if (rec.action === 'EXIT_ZONE') rec.targetZone = truck?.position?.value.zoneId ?? null;
447	    }
448	
449	    const msg: CommandMessage = {
450	      type: 'command', command_id: attempt.commandId, vehicle_id: rec.vehicleId, action: rec.action,
451	      operator_id: this.#operatorIdFor(rec.actor),
452	      ...(rec.force ? { force: true as const } : {}),
453	      ...(rec.action === 'RELEASE_CONTROL' && rec.leaseId ? { lease_id: rec.leaseId } : {}),
454	    };
455	    const line = JSON.stringify(msg);
456	    const send: SendInfo = { atMs: now, serverMs: this.#fleet.serverNow(), replay, ackRxMs: null };
457	    attempt.sends.push(send);
458	    this.#book.sent(attempt.commandId, now);
459	    // A new attempt has not been acknowledged yet, whatever the last one got. A replay keeps its
460	    // status: it is the same command, and the gateway will answer it with the original result.
461	    if (rec.status === 'pending' || kind === 'retry') rec.status = 'sent';
462	    rec.hold = null;
463	    rec.pendingRefusal = null;
464	    if (replay) {
465	      rec.deadlineMs = rec.deadlineMs === null ? null : Math.max(rec.deadlineMs, now + this.#baseDeadline(rec));
466	    } else {
467	      rec.queued = null;
468	      rec.started = null;
469	      rec.deadlineMs = this.#deadline(rec, truck, now);
470	    }
471	    const what = kind === 'first' ? `${rec.action} ${rec.vehicleId} sent` : kind === 'retry'
472	      ? `${rec.action} ${rec.vehicleId} sent again as attempt ${attempt.n} of ${rec.maxAttempts}` : `${rec.action} ${rec.vehicleId} replayed after reconnecting`;
473	    // Written down before it goes (L6.6).
474	    this.#store.tx(() => {
475	      this.#store.recordSend({ commandId: attempt.commandId, recordId: rec.id, attempt: attempt.n, replay, line, atMs: now, serverMs: send.serverMs });
476	      this.#save(rec, kind === 'first' ? 'sent' : kind === 'retry' ? 'retried' : 'replayed', what, undefined, attempt.commandId);
477	    });
478	    this.#transport.send(msg); // false means the link dropped under us: the replay on reconnect covers it
479	  }
480	
481	  #baseDeadline(rec: CommandRecord): number {
482	    return IMMEDIATE.has(rec.action) ? PARAMS.immediateEffectDeadline.value : supervisoryDeadlineMs();
483	  }
484	
485	  // L2.36: ~8 s normally; behind LOADING or DUMPING the work left plus that; behind CHARGING none.
486	  #deadline(rec: CommandRecord, truck: TruckView | undefined, now: number): number | null {
487	    const base = this.#baseDeadline(rec);
488	    if (QUEUEABLE.has(rec.action) && truck?.state && WORK.has(truck.state.value)) {
489	      return this.#markQueued(rec, truck, now);
490	    }
491	    return now + base;
492	  }
493	
494	  #markQueued(rec: CommandRecord, truck: TruckView, now: number): number | null {
495	    const behind = truck.state!.value as WorkState;
496	    const base = supervisoryDeadlineMs();
497	    if (behind === 'CHARGING') {
498	      const soc = truck.socPct?.value;
499	      const est = soc === undefined || truck.socFractional ? null : Math.max(0, ((PARAMS.chargeTo.value - soc) / PARAMS.chargeRate.value) * 1000);
500	      rec.queued = { behind, sinceMs: now, estimateMs: est };
501	      return null;
502	    }
503	    const full = behind === 'LOADING' ? PARAMS.loadTime.value : PARAMS.dumpTime.value;
504	    const since = truck.stateSinceServerMs;
505	    const elapsed = since === null ? 0 : Math.max(0, this.#fleet.serverNow() - since);
506	    const remaining = Math.max(0, full - elapsed);
507	    rec.queued = { behind, sinceMs: now, estimateMs: remaining };
508	    return now + remaining + base;
509	  }
510	
511	  // ---- outcomes ----
512	
513	  #evaluate(vehicleId: string): void {
514	    const truck = this.#fleet.truck(vehicleId);
515	    if (!truck) return;
516	    const now = this.#clock.now();
517	    for (const rec of this.#openOn(vehicleId)) {
518	      if (rec.hold || rec.attempts.length === 0) continue;
519	      const e = this.#effect(rec, truck);
520	      if (e.done) { this.#confirm(rec, e.detail); continue; }
521	      if (e.started && !rec.started) {
522	        rec.started = { atMs: now, detail: e.started };
523	        rec.queued = null;
524	        rec.deadlineMs = now + this.#exitDeadline(rec, truck);
525	        this.#save(rec, 'under_way', `${rec.action} ${rec.vehicleId} under way: ${e.started}`);
526	        continue;
527	      }
528	      if (rec.started || !QUEUEABLE.has(rec.action) || !this.#fresh(rec, truck)) continue;
529	      const state = truck.state!.value;
530	      if (!rec.queued && WORK.has(state)) {
531	        const d = this.#markQueued(rec, truck, now);
532	        rec.deadlineMs = d === null ? null : Math.max(d, rec.deadlineMs ?? 0);
533	        this.#save(rec, 'queued', `${rec.action} ${rec.vehicleId} queued behind ${state}`);
534	      } else if (rec.queued && !WORK.has(state)) {
535	        // The re-probe saw a queued HOLD accepted and never carried out: check the moment the work
536	        // ends, and retry at once if it hasn't taken effect.
537	        const behind = rec.queued.behind;
538	        rec.queued = null;
539	        this.#noEffect(rec, `${behind} ended and ${rec.vehicleId} is ${state}: the queued ${rec.action} was not carried out`);
540	      }
541	    }
542	  }
543	
544	  // Telemetry must be from after the first send, and believable: a frozen or silent truck confirms
545	  // nothing.
546	  #fresh(rec: CommandRecord, truck: TruckView): boolean {
547	    const first = rec.attempts[0]?.sends[0];
548	    if (!first || !truck.state) return false;
549	    if (truck.confidence === 'contradicted' || truck.confidence === 'silent' || truck.confidence === 'unknown') return false;
550	    return truck.state.atServerMs >= first.serverMs;
551	  }
552	
553	  // What the gateway's statutory log records as the operator. A system action carries its rule
554	  // ("system:B3"), so the why is in the site's log as well as ours (answer 4).
555	  #operatorIdFor(actor: Actor): string {
556	    return actor.kind === 'operator' ? actor.operatorId : `${this.#systemOperatorId}:${actor.rule}`;
557	  }
558	
559	  #effect(rec: CommandRecord, t: TruckView): { done: boolean; detail: string; started?: string } {
560	    const no = { done: false, detail: '' };
561	    if (!this.#fresh(rec, t)) return no;
562	    const state = t.state!.value;
563	    const control = t.control?.value;
564	    const opId = this.#operatorIdFor(rec.actor);
565	    const zone = t.position && t.position.atServerMs >= rec.attempts[0]!.sends[0]!.serverMs ? t.position.value.zoneId : null;
566	    switch (rec.action) {
567	      case 'HOLD':
568	        return state === 'HOLDING' ? { done: true, detail: `${rec.vehicleId} is holding` } : no;
569	      case 'RESUME': {
570	        // A truck already in its duty cycle when RESUME went out shows nothing new in telemetry: the
571	        // RESUME can only have cancelled a queued command, which only the ack says. Otherwise a
572	        // RESUME refused during another command's delay would look done (re-probe Q3).
573	        if (!DUTY_CYCLE.has(state) || control?.mode === 'MANUAL') return no;
574	        const wasMoving = rec.baselineState !== null && DUTY_CYCLE.has(rec.baselineState);
575	        if (wasMoving && rec.attempts.at(-1)?.ack?.status !== 'ACCEPTED') return no;
576	        return { done: true, detail: `${rec.vehicleId} is ${state}` };
577	      }
578	      case 'RETURN_TO_BAY': {
579	        if (t.task?.value === 'RETURN_TO_BAY') return { done: true, detail: `${rec.vehicleId} is returning to the bay` };
580	        const inBay = zone !== null && !!this.#fleet.site?.zone(zone)?.kinds.includes('bay');
581	        return inBay && (state === 'IDLE' || state === 'CHARGING') ? { done: true, detail: `${rec.vehicleId} is in the bay, ${state}` } : no;
582	      }
583	      case 'EXIT_ZONE':
584	        if (state === 'HOLDING' && zone !== null && zone !== rec.targetZone && (rec.targetZone !== null || rec.started)) {
585	          return { done: true, detail: `${rec.vehicleId} is holding outside ${rec.targetZone ?? 'the zone'}, in ${zone}` };
586	        }
587	        if (t.task?.value === 'EXIT_ZONE') return { done: false, detail: '', started: `leaving ${rec.targetZone ?? 'its zone'}` };
588	        return no;
589	      case 'ESTOP':
590	        return state === 'ESTOPPED' ? { done: true, detail: `${rec.vehicleId} is e-stopped` } : no;
591	      case 'CLEAR_ESTOP':
592	        return state !== 'ESTOPPED' ? { done: true, detail: `${rec.vehicleId} is out of e-stop, ${state}` } : no;
593	      case 'TAKE_CONTROL':
594	        return control?.mode === 'MANUAL' && control.operatorId === opId ? { done: true, detail: `${opId} has control of ${rec.vehicleId}` } : no;
595	      case 'RELEASE_CONTROL':
596	        return control && control.operatorId !== opId ? { done: true, detail: `${rec.vehicleId} handed back, ${state}` } : no;
597	      default:
598	        return no;
599	    }
600	  }
601	
602	  // EXIT_ZONE once under way: the time to the nearer boundary at the slowest speed it might use,
603	  // doubled for the thinly measured loaded reverse, plus the command delay as slack.
604	  #exitDeadline(_rec: CommandRecord, t: TruckView): number {
605	    const site = this.#fleet.site;
606	    const pos = t.position?.value.loopM;
607	    const exit = site && pos !== undefined ? zoneExit(site, pos) : undefined;
608	    const distance = (exit?.distanceM ?? 0) + PARAMS.exitZoneStopOutside.value;
609	    const speed = Math.min(PARAMS.reverseSpeedLoaded.value, PARAMS.autoSpeedLoaded.value);
610	    return 2 * (distance / speed) * 1000 + PARAMS.supervisoryDelayMax.value + PARAMS.telemetryLatencyAllowance.value;
611	  }
612	
613	  #onDeadline(rec: CommandRecord): void {
614	    const truck = this.#fleet.truck(rec.vehicleId);
615	    if (truck) {
616	      const e = this.#effect(rec, truck);
617	      if (e.done) { this.#confirm(rec, e.detail); return; }
618	    }
619	    if (rec.pendingRefusal) {
620	      this.#close(rec, 'failed', rec.pendingRefusal);
621	      return;
622	    }
623	    if (truck && QUEUEABLE.has(rec.action) && !rec.started && this.#fresh(rec, truck) && WORK.has(truck.state!.value)) {
624	      rec.deadlineMs = this.#markQueued(rec, truck, this.#clock.now());
625	      this.#save(rec, 'queued', `${rec.action} ${rec.vehicleId} still queued behind ${truck.state!.value}`);
626	      return;
627	    }
628	    const seen = truck?.state ? `last seen ${truck.state.value} ${secs(truck.state.ageMs)} ago` : 'no telemetry';
629	    const acked = rec.attempts.at(-1)?.ack?.status === 'ACCEPTED' ? 'accepted but not carried out' : 'no ack and no effect';
630	    this.#noEffect(rec, `${acked} within ${secs(this.#baseDeadline(rec))} (${seen})`);
631	  }
632	
633	  // No effect when there should have been one: retry under a new command_id, or fail and alarm.
634	  #noEffect(rec: CommandRecord, why: string): void {
635	    const truck = this.#fleet.truck(rec.vehicleId);
636	    if (rec.action === 'EXIT_ZONE' && rec.started) {
637	      this.#fail(rec, 'EXIT_NOT_CONFIRMED', `${rec.vehicleId} started leaving ${rec.targetZone ?? 'its zone'} but is not confirmed outside it (${why}). Not sent again: a new EXIT_ZONE could send it out of a different zone.`);
638	      return;
639	    }
640	    if (rec.attempts.length >= rec.maxAttempts) {
641	      this.#fail(rec, 'NO_EFFECT', `${rec.action} for ${rec.vehicleId} did not take effect after ${rec.attempts.length} attempts: ${why}.`);
642	      return;
643	    }
644	    if (rec.action === 'EXIT_ZONE') {
645	      // CONTEXT.md assumption 6: re-check zone membership before EXIT_ZONE goes out again.
646	      const zone = truck?.position?.value.zoneId ?? null;
647	      if (!truck || truck.confidence !== 'live' || zone === null || zone !== rec.targetZone) {
648	        this.#fail(rec, 'EXIT_ZONE_UNCERTAIN', `EXIT_ZONE for ${rec.vehicleId} not confirmed (${why}), and its position is not certain enough to send it again (${truck?.confidence ?? 'no data'}, in ${zone ?? 'unknown'}).`);
649	        return;
650	      }
651	    }
652	    this.#audit(rec, 'no_effect', `${rec.action} ${rec.vehicleId}: ${why}`);
653	    this.#sendAttempt(rec, 'retry');
654	  }
655	
656	  #confirm(rec: CommandRecord, detail: string): void {
657	    const now = this.#clock.now();
658	    const ackReceived = rec.attempts.some((a) => a.ack !== null);
659	    rec.effect = { atMs: now, serverMs: this.#fleet.serverNow(), detail, ackReceived };
660	    this.#close(rec, 'confirmed', null, undefined, `${rec.action} ${rec.vehicleId} confirmed: ${detail}${ackReceived ? '' : ' (no ack received)'}`);
661	  }
662	
663	  #fail(rec: CommandRecord, code: string, message: string): void {
664	    this.#close(rec, 'failed', { code, message, ourFault: false });
665	    this.#emit({ type: 'alarm', kind: 'command_failed', vehicleId: rec.vehicleId, recordId: rec.id, message });
666	  }
667	
668	  #holdTimedOut(rec: CommandRecord): void {
669	    if (rec.actor.kind === 'system') {
670	      this.#close(rec, 'expired', { code: 'LINK_DOWN_TOO_LONG', message: `The site link stayed down for more than ${secs(PARAMS.estopAutoSendWithin.value)}; not sent. The rule that asked for it decides again on reconnect.`, ourFault: false });
671	      return;
672	    }
673	    rec.hold!.needsReconfirm = true;
674	    const message = `${rec.action} for ${rec.vehicleId} was NOT sent: the site link was down for more than ${secs(PARAMS.estopAutoSendWithin.value)}. Look at ${rec.vehicleId} as it is now, then confirm again or cancel.`;
675	    this.#save(rec, 'needs_reconfirm', message);
676	    if (rec.action === 'ESTOP') this.#emit({ type: 'alarm', kind: 'estop_undelivered', vehicleId: rec.vehicleId, recordId: rec.id, message });
677	  }
678	
679	  // ---- acks and leases ----
680	
681	  #ack(m: Record<string, unknown>): void {
682	    const cid = typeof m.command_id === 'string' ? m.command_id : null;
683	    if (cid === null) return;
684	    const loc = this.#byCommandId.get(cid);
685	    if (!loc) return; // another client's command: acks are broadcast to everyone
686	    const now = this.#clock.now();
687	    const match = this.#book.ack(cid, now);
688	    if (!match) return;
689	    const { rec, attempt } = loc;
690	    const status = m.status === 'ACCEPTED' ? 'ACCEPTED' : 'REJECTED';
691	    const str = (x: unknown) => (typeof x === 'string' ? x : null);
692	    const info: AckInfo = {
693	      status, reason: str(m.reason), holder: str(m.holder), leaseId: str(m.lease_id),
694	      serverMs: typeof m.server_time_ms === 'number' ? m.server_time_ms : null, rxMs: now, sendIndex: match.sendIndex,
695	    };
696	    this.#store.recordAck({ commandId: cid, recordId: rec.id, status, reason: info.reason, holder: info.holder, leaseId: info.leaseId, serverMs: info.serverMs, rxMs: now, sendIndex: match.sendIndex, duplicate: match.duplicate });
697	    if (match.duplicate) { attempt.duplicateAcks++; this.#save(rec); return; } // L2.32: no state change
698	    attempt.sends[match.sendIndex]!.ackRxMs = now;
699	    attempt.ack = info;
700	
701	    if (status === 'ACCEPTED' && rec.action === 'TAKE_CONTROL' && info.leaseId && rec.actor.kind === 'operator') {
702	      this.#setLease({ vehicleId: rec.vehicleId, operatorId: rec.actor.operatorId, leaseId: info.leaseId, sinceServerMs: this.#fleet.serverNow() });
703	    }
704	    const current = attempt === rec.attempts.at(-1);
705	    if (rec.status === 'confirmed' && status === 'ACCEPTED' && rec.effect && !rec.effect.ackReceived) {
706	      rec.effect.ackReceived = true; // the ack came after the effect (L2.30): no longer "no ack received"
707	    }
708	    if (!OPEN_STATUSES.has(rec.status) || !current) {
709	      this.#save(rec, 'ack', `${status}${info.reason ? ` ${info.reason}` : ''} for ${cid} after the command was ${current ? rec.status : 'sent again'}`, undefined, cid);
710	      return;
711	    }
712	    if (status === 'ACCEPTED') {
713	      if (rec.status === 'sent') rec.status = 'acknowledged';
714	      this.#save(rec, 'ack', `${rec.action} ${rec.vehicleId} accepted by the site (not yet carried out)`, undefined, cid);
715	      if (rec.action === 'RESUME') this.#cancelQueuedBy(rec);
716	      this.#evaluate(rec.vehicleId); // the effect may already be in (L2.30)
717	      return;
718	    }
719	    this.#rejected(rec, attempt, info);
720	  }
721	
722	  #rejected(rec: CommandRecord, attempt: Attempt, info: AckInfo): void {
723	    const truck = this.#fleet.truck(rec.vehicleId);
724	    const reason = info.reason ?? 'UNKNOWN';
725	    const ref: Refusal = refusal(reason, {
726	      vehicleId: rec.vehicleId, action: rec.action, holder: info.holder, state: truck?.state?.value ?? null,
727	      faults: truck?.faults?.value ?? null, inFlight: this.#inFlight(rec),
728	    });
729	    if (reason === 'LEASE_HELD') {
730	      const sender = rec.actor.kind === 'operator' ? rec.actor.operatorId : `the system (${rec.actor.rule})`;
731	      const to = [info.holder, rec.actor.kind === 'operator' ? rec.actor.operatorId : null].filter((x): x is string => !!x);
732	      this.#emit({ type: 'notify', to: [...new Set(to)], vehicleId: rec.vehicleId, recordId: rec.id, message: `${sender} tried to ${rec.action} ${rec.vehicleId}, but ${info.holder ?? 'another operator'} holds its controls. The ${rec.action} was not carried out.` });
733	    }
734	    // A retry refused for the truck's state may only mean an earlier attempt already worked: give
735	    // that a moment to show before calling it failed.
736	    if (reason === 'INVALID_STATE' && attempt.n > 1) {
737	      rec.pendingRefusal = { code: reason, message: ref.message, ourFault: ref.ourFault };
738	      rec.deadlineMs = this.#clock.now() + PARAMS.telemetryLatencyAllowance.value + PARAMS.commandUplinkAllowance.value;
739	      this.#save(rec, 'ack', `${rec.action} ${rec.vehicleId} attempt ${attempt.n} refused (${reason}); checking whether an earlier attempt worked`, undefined, attempt.commandId);
740	      return;
741	    }
742	    this.#audit(rec, 'ack', `${rec.action} ${rec.vehicleId} refused by the site: ${reason}`, undefined, attempt.commandId);
743	    this.#close(rec, 'failed', { code: reason, message: ref.message, ourFault: ref.ourFault });
744	  }
745	
746	  // Another command of ours on the truck still within its delay, for INVALID_STATE (re-probe Q3).
747	  #inFlight(rec: CommandRecord): { action: string; sentAgoMs: number } | null {
748	    const now = this.#clock.now();
749	    for (const r of this.#openOn(rec.vehicleId)) {
750	      if (r === rec || !SUPERVISORY.has(r.action) || r.queued || r.hold) continue;
751	      const sent = r.attempts.at(-1)?.sends.at(-1);
752	      if (sent && now - sent.atMs < supervisoryDeadlineMs()) return { action: r.action, sentAgoMs: now - sent.atMs };
753	    }
754	    return null;
755	  }
756	
757	  #leaseEvent(m: Record<string, unknown>): void {
758	    const v = typeof m.vehicle_id === 'string' ? m.vehicle_id : null;
759	    const op = typeof m.operator_id === 'string' ? m.operator_id : null;
760	    if (!v) return;
761	    const at = typeof m.server_time_ms === 'number' ? m.server_time_ms : this.#fleet.serverNow();
762	    switch (m.event) {
763	      case 'GRANTED':
764	        if (op) this.#setLease({ vehicleId: v, operatorId: op, leaseId: typeof m.lease_id === 'string' ? m.lease_id : null, sinceServerMs: at });
765	        break;
766	      case 'RELEASED': case 'EXPIRED': case 'REVOKED': {
767	        this.#leases.delete(v);
768	        const by = typeof m.by_operator === 'string' ? m.by_operator : null;
769	        const message = m.event === 'RELEASED' ? `${op ?? 'The driver'} handed ${v} back; it is holding.`
770	          : m.event === 'EXPIRED' ? `${op ?? 'The driver'}'s control of ${v} expired: no drive input for ${secs(PARAMS.leaseIdleTimeout.value)}. It is holding and will not resume by itself.`
771	            : m.reason === 'FORCED_TAKEOVER' ? `${by ?? 'A supervisor'} took control of ${v} from ${op ?? 'its driver'}.`
772	              : m.reason === 'ESTOP' ? `${v} was e-stopped${by ? ` by ${by}` : ''}; ${op ?? 'its driver'} no longer has control.`
773	                : `${op ?? 'The driver'} lost control of ${v}: ${String(m.reason ?? 'revoked')}.`;
774	        this.#emit({ type: 'lease', vehicleId: v, lease: null, message });
775	        if (op) this.#emit({ type: 'notify', to: [op], vehicleId: v, recordId: null, message });
776	        break;
777	      }
778	      default: break;
779	    }
780	  }
781	
782	  #setLease(l: LeaseInfo): void {
783	    const prev = this.#leases.get(l.vehicleId);
784	    this.#leases.set(l.vehicleId, l);
785	    if (!prev || prev.operatorId !== l.operatorId || prev.leaseId !== l.leaseId) {
786	      this.#emit({ type: 'lease', vehicleId: l.vehicleId, lease: { ...l }, message: `${l.operatorId} has control of ${l.vehicleId}.` });
787	    }
788	  }
789	
790	  #leaseIdFor(vehicleId: string, actor: Actor): string | null {
791	    const l = this.#leases.get(vehicleId);
792	    return l && actor.kind === 'operator' && l.operatorId === actor.operatorId ? l.leaseId : null;
793	  }
794	
795	  // ---- superseding (L2.38) ----
796	
797	  // At most one of our supervisory commands is open on a truck, so a retry can never displace a
798	  // different command we queued. A newer HOLD, RETURN_TO_BAY or EXIT_ZONE replaces the older at the
799	  // truck anyway (one queued at a time; pending ones run in order, the newest last). An e-stop or a
800	  // takeover drops them at the truck. A RESUME replaces them only once accepted (#cancelQueuedBy):
801	  // refused, it changes nothing, because a command on its way can't be called back.
802	  #supersedeFor(newer: CommandRecord): void {
803	    const a = newer.action;
804	    const replaces = (older: CommandRecord): boolean => {
805	      if (a === 'ESTOP') return older.action !== 'ESTOP';
806	      if (a === 'TAKE_CONTROL') return SUPERVISORY.has(older.action);
807	      if (QUEUEABLE.has(a)) return SUPERVISORY.has(older.action);
808	      return false;
809	    };
810	    for (const older of this.#openOn(newer.vehicleId)) {
811	      if (older !== newer && replaces(older)) this.#supersede(older, newer, 'replaced by a newer command');
812	    }
813	  }
814	
815	  #cancelQueuedBy(resume: CommandRecord): void {
816	    for (const older of this.#openOn(resume.vehicleId)) {
817	      if (older !== resume && QUEUEABLE.has(older.action) && older.queued) this.#supersede(older, resume, `cancelled by RESUME while queued behind ${older.queued.behind}`);
818	    }
819	  }
820	
821	  #supersede(older: CommandRecord, newer: CommandRecord, why: string): void {
822	    older.supersededBy = newer.id;
823	    this.#close(older, 'superseded', null, newer.actor, `${older.action} ${older.vehicleId} ${why} (${newer.action})`);
824	  }
825	
826	  // ---- restart (L6.1, L6.6) ----
827	
828	  #restore(): void {
829	    const now = this.#clock.now();
830	    for (const rec of this.#store.openCommands()) {
831	      this.#records.set(rec.id, rec);
832	      for (const a of rec.attempts) {
833	        this.#byCommandId.set(a.commandId, { rec, attempt: a });
834	        for (const s of a.sends) this.#book.sent(a.commandId, s.atMs, s.ackRxMs !== null);
835	      }
836	      this.#audit(rec, 'restored', `${rec.action} ${rec.vehicleId} found ${rec.status} after a restart`, { kind: 'system', rule: 'restart-recovery' });
837	      if (rec.hold) {
838	        if (!rec.hold.needsReconfirm && now > rec.hold.autoSendUntilMs) this.#holdTimedOut(rec);
839	        continue;
840	      }
841	      if (rec.attempts.length === 0) {
842	        // Written, then killed before the first send went out: it has no deadline of its own yet.
843	        if (now - rec.createdMs > this.#baseDeadline(rec)) this.#close(rec, 'expired', { code: 'RESTART_PAST_DEADLINE', message: `The service restarted before this was sent, and it is now too old to send. Check ${rec.vehicleId} and send again if needed.`, ourFault: false });
844	        else rec.hold = { sinceMs: rec.createdMs, autoSendUntilMs: rec.createdMs + this.#baseDeadline(rec), needsReconfirm: false };
845	        continue;
846	      }
847	      if (rec.deadlineMs !== null && now > rec.deadlineMs) {
848	        this.#close(rec, 'expired', { code: 'RESTART_PAST_DEADLINE', message: `The service restarted after this was sent and it is now past its deadline, so it was not sent again. Check ${rec.vehicleId} as it is now and send again if needed.`, ourFault: false });
849	      }
850	      // The rest are replayed, under the same command_id, on the next hello.
851	    }
852	  }
853	
854	  // ---- bookkeeping ----
855	
856	  #close(rec: CommandRecord, status: CommandStatus, failure: CommandRecord['failure'], actor?: Actor, what?: string): void {
857	    rec.status = status;
858	    rec.failure = failure;
859	    rec.hold = null;
860	    rec.deadlineMs = null;
861	    rec.queued = null;
862	    rec.pendingRefusal = null;
863	    rec.closedServerMs = this.#fleet.serverNow();
864	    this.#save(rec, status, what ?? `${rec.action} ${rec.vehicleId} ${status}${failure ? `: ${failure.message}` : ''}`, actor);
865	    this.#trim();
866	  }
867	
868	  #save(rec: CommandRecord, event?: string, what?: string, actor?: Actor, commandId?: string): void {
869	    rec.updatedMs = this.#clock.now();
870	    rec.summary = summarise(rec, this.#clock.now());
871	    this.#store.tx(() => {
872	      this.#store.saveCommand(rec);
873	      if (event && what) this.#store.audit(this.#entry(rec, event, what, actor, commandId));
874	    });
875	    this.#emit({ type: 'command', record: structuredClone(rec) });
876	  }
877	
878	  #audit(rec: CommandRecord, event: string, what: string, actor?: Actor, commandId?: string): void {
879	    this.#store.audit(this.#entry(rec, event, what, actor, commandId));
880	  }
881	
882	  #entry(rec: CommandRecord, event: string, what: string, actor: Actor = rec.actor, commandId?: string): AuditEntry {
883	    return {
884	      atMs: this.#clock.now(), serverMs: this.#fleet.serverNow(),
885	      actorKind: actor.kind, actor: actor.kind === 'operator' ? actor.operatorId : 'system', rule: actor.kind === 'system' ? actor.rule : null,
886	      event, vehicleId: rec.vehicleId, recordId: rec.id, commandId: commandId ?? rec.attempts.at(-1)?.commandId ?? null,
887	      what, why: rec.why, inputs: actor.kind === 'system' ? actor.inputs ?? null : undefined,
888	    };
889	  }
890	
891	  #openOn(vehicleId: string): CommandRecord[] {
892	    return [...this.#records.values()].filter((r) => r.vehicleId === vehicleId && OPEN_STATUSES.has(r.status));
893	  }
894	
895	  #hasOpen(vehicleId: string): boolean {
896	    for (const r of this.#records.values()) if (r.vehicleId === vehicleId && OPEN_STATUSES.has(r.status)) return true;
897	    return false;
898	  }
899	
900	  #openSorted(): CommandRecord[] {
901	    return [...this.#records.values()].filter((r) => OPEN_STATUSES.has(r.status)).sort((a, b) => a.createdMs - b.createdMs);
902	  }
903	
904	  #trim(): void {
905	    const closed = [...this.#records.values()].filter((r) => !OPEN_STATUSES.has(r.status));
906	    for (const r of closed.slice(0, Math.max(0, closed.length - this.#keepClosed))) {
907	      this.#records.delete(r.id);
908	      for (const a of r.attempts) this.#byCommandId.delete(a.commandId);
909	    }
910	  }
911	
912	  #emit(e: RegistryEvent): void {
913	    for (const fn of this.#listeners) fn(e);
914	  }
915	}
916	
917	function cloneActor(a: Actor): Actor {
918	  return a.kind === 'operator'
919	    ? { kind: 'operator', operatorId: String(a.operatorId), role: a.role === 'supervisor' ? 'supervisor' : 'operator' }
920	    : { kind: 'system', rule: String(a.rule), ...(a.inputs === undefined ? {} : { inputs: structuredClone(a.inputs) }) };
921	}
922	
923	// One line for the operator: what is happening to this command now.
924	export function summarise(r: CommandRecord, nowMs: number): string {
925	  const n = r.attempts.length;
926	  const attempt = n > 1 ? ` (attempt ${n} of ${r.maxAttempts})` : '';
927	  switch (r.status) {
928	    case 'pending':
929	      if (r.hold?.needsReconfirm) return 'NOT sent: the site link was down too long. Check the truck, then confirm again or cancel';
930	      if (r.hold) return `NOT sent yet: waiting for the site link (sends by itself for ${secs(Math.max(0, r.hold.autoSendUntilMs - nowMs))} more)`;
931	      return 'about to send';
932	    case 'sent':
933	      if (r.queued) return `sent, queued behind ${r.queued.behind}${attempt}`;
934	      return `sent, no answer from the site yet${attempt}`;
935	    case 'acknowledged':
936	      if (r.started) return `under way: ${r.started.detail}${attempt}`;
937	      if (r.queued) {
938	        const est = r.queued.estimateMs === null ? '' : ` (~${Math.round(r.queued.estimateMs / 1000)} s left)`;
939	        return `accepted, queued until ${r.queued.behind} ends${est}${r.queued.behind === 'CHARGING' ? ': no fixed deadline' : ''}${attempt}`;
940	      }
941	      return `accepted, not carried out yet${attempt}`;
942	    case 'confirmed':
943	      return `done: ${r.effect?.detail ?? ''}${r.effect && !r.effect.ackReceived ? ' (no ack received)' : ''}${attempt}`;
944	    case 'failed': case 'refused': case 'expired':
945	      return r.failure?.message ?? r.status;
946	    case 'cancelled':
947	      return 'cancelled before it was sent';
948	    case 'superseded':
949	      return 'replaced by a newer command';
950	  }
951	}
