  link: Pick<GatewayLink, 'status' | 'subscribe'>;
  registry: CommandRegistry;
  sessions: Sessions;
  log: (line: string) => void;
}

export class LiveHub {
  readonly #o: LiveOptions;
  readonly #clients = new Set<Client>();
  readonly #alarms: Alarm[] = [];
  readonly #notices = new Map<string, Notice[]>();
  #nextId = 1;
  #seq = 0;
  #dirty = true;
  #lastSent = Number.NEGATIVE_INFINITY;
  #timer: TimerHandle | null = null;
  readonly #unsub: Array<() => void> = [];

  constructor(o: LiveOptions) {
    this.#o = o;
    const dirty = () => { this.#dirty = true; };
    this.#unsub.push(o.fleet.subscribe(dirty));
    this.#unsub.push(o.link.subscribe((e) => {
      this.#dirty = true;
      if (e.type === 'alarm') this.#alarm('site_link', null, e.message);
    }));
    this.#unsub.push(o.registry.subscribe((e) => this.#registryEvent(e)));
    this.#unsub.push(o.sessions.onEnd((s) => this.closeSession(s.id, 'session ended')));
  }

  start(): void {
    this.stop();
    const loop = () => { this.tick(); this.#timer = this.#o.clock.setTimeout(loop, PARAMS.livePushMinInterval.value); };
    this.#timer = this.#o.clock.setTimeout(loop, PARAMS.livePushMinInterval.value);
  }

  stop(): void {
    if (this.#timer) this.#o.clock.clearTimeout(this.#timer);
    this.#timer = null;
  }

  shutdown(): void {
    this.stop();
    for (const c of [...this.#clients]) this.#drop(c, 1001, 'service stopping');
    for (const u of this.#unsub) u();
  }

  get clientCount(): number { return this.#clients.size; }

  // Screens open on one session. The HTTP layer refuses more than MAX_SCREENS_PER_SESSION, so one
  // login can't open thousands of sockets.
  screensOf(sessionId: string): number {
    let n = 0;
    for (const c of this.#clients) if (c.session.id === sessionId) n++;
    return n;
  }

  // A browser has connected with a session the HTTP layer has already checked.
  connect(sock: LiveSocket, session: Session): { receive(data: unknown, isBinary: boolean): void; closed(): void } {
    const c: Client = { sock, session, tokens: this.#burst(), tokensAt: this.#o.clock.now(), refusals: 0, overLimit: 0, closed: false };
    this.#clients.add(c);
    this.#o.log(`browser connected: ${session.user.id} (${session.user.role}); ${this.#clients.size} open`);
    this.#push(c, this.#sharedFrame(false)); // its first picture at once
    this.#dirty = true;                       // and everyone else's who's-on changed
    return {
      receive: (data, isBinary) => this.#receive(c, data, isBinary),
      closed: () => {
        if (!this.#clients.delete(c)) return;
        c.closed = true;
        this.#dirty = true;
        this.#o.log(`browser disconnected: ${session.user.id}; ${this.#clients.size} open`);
      },
    };
  }

  // Logout or expiry: that session's screens are closed at once.
  closeSession(sessionId: string, reason: string): void {
    for (const c of [...this.#clients]) if (c.session.id === sessionId) this.#drop(c, 4401, reason);
  }

  // Runs on the timer; by hand in tests.
  tick(): void {
    const now = this.#o.clock.now();
    for (const c of [...this.#clients]) {
      // An open screen keeps its session alive; an ended session closes its screens.
      if (!this.#o.sessions.get(c.session.id)) { this.#drop(c, 4401, 'session ended'); continue; }
      this.#o.sessions.touch(c.session.id);
    }
    if (!this.#dirty && now - this.#lastSent < PARAMS.liveFrameMaxInterval.value) return;
    const shared = this.#sharedFrame(true);
    for (const c of this.#clients) this.#push(c, shared);
  }

  state(): LiveState {
    const now = this.#o.clock.now();
    const st = this.#o.link.status();
    const reg = this.#o.registry;
    return {
      link: {
        state: st.state, reason: st.reason, forMs: now - st.sinceMs, failures: st.failures,
        nextAttemptInMs: st.nextAttemptAtMs === null ? null : Math.max(0, st.nextAttemptAtMs - now), authError: st.authError,
      },
      blastSafety: { active: false, note: BLAST_SAFETY_OFF },
      who: this.#who(),
      leases: reg.leases().map((l) => ({ vehicleId: l.vehicleId, operatorId: l.operatorId, sinceServerMs: l.sinceServerMs })),
      commands: this.#commands(now),
      alarms: [...this.#alarms],
    };
  }

  // ---- out ----

  #sharedFrame(forAll: boolean): string {
    if (forAll) {
      this.#dirty = false;
      this.#lastSent = this.#o.clock.now();
    }
    const site = this.#o.fleet.site;
    const frame = { site: site ? siteData(site) : null, snapshot: this.#o.fleet.snapshot(), live: this.state() };
    return JSON.stringify({ seq: ++this.#seq, sentServerMs: this.#o.fleet.serverNow(), frame });
  }

  #push(c: Client, shared: string): void {
    if (c.closed) return;
    if (c.sock.bufferedAmount > PARAMS.liveMaxBufferedBytes.value) return; // behind: skip, never queue old pictures
    const you = c.session.user;
    const notices = this.#notices.get(you.id) ?? [];
    this.#send(c, `{"type":"frame","you":${JSON.stringify({ id: you.id, name: you.name, role: you.role })},"notices":${JSON.stringify(notices)},"body":${shared}}`);
  }

  #send(c: Client, text: string): void {
    try { c.sock.send(text); } catch (e) { this.#o.log(`send to ${c.session.user.id} failed: ${e instanceof Error ? e.message : String(e)}`); this.#drop(c, 1011, 'send failed'); }
  }

  #reply(c: Client, ref: string | null, body: Record<string, unknown>): void {
    this.#send(c, JSON.stringify({ type: 'result', ref, ...body }));
  }

  #who(): WhoView[] {
    const by = new Map<string, WhoView>();
    for (const c of this.#clients) {
      const u = c.session.user;
      const w = by.get(u.id) ?? { id: u.id, name: u.name, role: u.role, screens: 0 };
      w.screens++;
      by.set(u.id, w);
    }
    return [...by.values()].sort((a, b) => a.name.localeCompare(b.name));
  }

  // Open commands, plus the latest on each truck whatever its state, newest first.
  #commands(now: number): CommandView[] {
    const all = this.#o.registry.list();
    const latest = new Map<string, CommandRecord>();
    for (const r of all) {
      const prev = latest.get(r.vehicleId);
      if (!prev || r.createdMs >= prev.createdMs) latest.set(r.vehicleId, r);
    }
    const keep = all.filter((r) => !SETTLE_CLOSED.has(r.status) || latest.get(r.vehicleId) === r);
    return keep.sort((a, b) => b.createdMs - a.createdMs).map((r) => view(r, now));
  }

  #registryEvent(e: RegistryEvent): void {
    this.#dirty = true;
    if (e.type === 'alarm') this.#alarm(e.kind, e.vehicleId, e.message);
    else if (e.type === 'notify') {
      for (const to of e.to) {
        const list = this.#notices.get(to) ?? [];
        list.unshift({ id: this.#nextId++, atServerMs: this.#o.fleet.serverNow(), vehicleId: e.vehicleId, message: e.message });
        this.#notices.set(to, list.slice(0, MAX_NOTICES));
      }
    }
  }

  #alarm(kind: string, vehicleId: string | null, message: string): void {
    this.#alarms.unshift({ id: this.#nextId++, atServerMs: this.#o.fleet.serverNow(), kind, vehicleId, message });
    this.#alarms.length = Math.min(this.#alarms.length, MAX_ALARMS);
    this.#dirty = true;
  }

  // ---- in ----

  #receive(c: Client, data: unknown, isBinary: boolean): void {
    if (c.closed) return;
    try {
      this.#o.sessions.touch(c.session.id);
      if (!this.#o.sessions.get(c.session.id)) { this.#drop(c, 4401, 'session ended'); return; }
      if (!this.#take(c)) {
        // A flood: refused, and the socket closed if it keeps on.
        if (++c.overLimit >= REFUSALS_BEFORE_CLOSE) { this.#o.log(`closing ${c.session.user.id}'s connection: ${c.overLimit} messages over the limit`); this.#drop(c, 1008, 'too many messages'); return; }
        this.#refuse(c, null, 'too many messages: slow down');
        return;
      }
      if (isBinary) { this.#refuse(c, null, 'binary messages are not accepted'); return; }
      const text = typeof data === 'string' ? data : Buffer.isBuffer(data) ? data.toString('utf8') : null;
      if (text === null || Buffer.byteLength(text, 'utf8') > MAX_TEXT) { this.#refuse(c, null, 'message too large or not text'); return; }
      let m: unknown;
      try { m = JSON.parse(text); } catch { this.#refuse(c, null, 'not JSON'); return; }
      if (m === null || typeof m !== 'object' || Array.isArray(m)) { this.#refuse(c, null, 'not a JSON object'); return; }
      const msg = m as Incoming;
      const ref = typeof msg.ref === 'string' && /^[\w-]{1,64}$/.test(msg.ref) ? msg.ref : null;
      switch (msg.type) {
        case 'command': this.#command(c, ref, msg); break;
        case 'cancel': case 'reconfirm': this.#pending(c, ref, msg); break;
        case 'drive':
          // No drive path yet (L6.3's drive half waits for the driving task). Refused, and nothing is
          // sent to the gateway: the truck's deadman stops it.
          this.#refuse(c, ref, 'Driving from the browser is not available in this build yet. Nothing was sent to the truck.');
          break;
        default: this.#refuse(c, ref, `unknown message type ${JSON.stringify(String(msg.type)).slice(0, 40)}`);
      }
    } catch (e) {
      // Never let one browser's message take the service down.
      this.#o.log(`error handling a message from ${c.session.user.id}: ${e instanceof Error ? e.message : String(e)}`);
      this.#reply(c, null, { ok: false, error: 'The service could not handle that message.' });
    }
  }

  #command(c: Client, ref: string | null, m: Incoming): void {
    const action = m.action;
    if (typeof action !== 'string' || !(ACTIONS as readonly string[]).includes(action)) { this.#refuse(c, ref, 'unknown action'); return; }
    const vehicleId = m.vehicleId;
    if (typeof vehicleId !== 'string' || vehicleId.length > 64) { this.#refuse(c, ref, 'vehicleId must be a truck id'); return; }
    const roster = this.#o.fleet.snapshot().trucks.filter((t) => t.onRoster === true).map((t) => t.vehicleId);
    if (roster.length === 0) { this.#refuse(c, ref, 'No site description yet (no hello from the gateway), so no truck can be commanded.'); return; }
    if (!roster.includes(vehicleId)) { this.#refuse(c, ref, `${vehicleId} is not a truck on this site`); return; }
    if (m.force !== undefined && typeof m.force !== 'boolean') { this.#refuse(c, ref, 'force must be true or false'); return; }
    if (m.force === true && action !== 'TAKE_CONTROL') { this.#refuse(c, ref, 'force applies only to TAKE_CONTROL'); return; }
    if (m.why !== undefined && (typeof m.why !== 'string' || m.why.length > 200)) { this.#refuse(c, ref, 'why must be text, up to 200 characters'); return; }
    // L8.3: the operator is the session's. Anything in the message that claims otherwise is ignored,
    // and noted, because a browser that sends it is either out of date or trying something.
    const claimed = ['operator_id', 'operatorId', 'operator', 'actor', 'role', 'user'].filter((k) => k in m);
    if (claimed.length) this.#o.log(`ignored ${claimed.join(', ')} in a command from ${c.session.user.id}: the operator comes from the session`);
    const rec = this.#o.registry.submit(
      { vehicleId, action: action as Action, ...(m.force === true ? { force: true } : {}), ...(typeof m.why === 'string' && m.why.trim() ? { why: m.why.trim() } : {}) },
      this.#actor(c.session),
    );
    this.#dirty = true;
    this.#reply(c, ref, { ok: rec.status !== 'refused', command: view(rec, this.#o.clock.now()) });
  }

  // Cancel or confirm again a command waiting for the site link (L7.8). Cancelling an e-stop takes
  // away a stop someone asked for, so only whoever pressed it, or a supervisor, may.
  #pending(c: Client, ref: string | null, m: Incoming): void {
    const id = m.recordId;
    if (typeof id !== 'string' || id.length > 100) { this.#refuse(c, ref, 'recordId must be a command id'); return; }
    const rec = this.#o.registry.get(id);
    if (!rec) { this.#refuse(c, ref, 'no such command'); return; }
    const actor = this.#actor(c.session);
    if (m.type === 'cancel') {
      const own = rec.actor.kind === 'operator' && rec.actor.operatorId === c.session.user.id;
      if (!own && c.session.user.role !== 'supervisor') { this.#refuse(c, ref, `Only ${rec.actor.kind === 'operator' ? rec.actor.operatorId : 'the system'} or a supervisor can cancel this ${rec.action}.`); return; }
      const out = this.#o.registry.cancel(id, actor)!;
      this.#reply(c, ref, { ok: out.status === 'cancelled', command: view(out, this.#o.clock.now()) });
    } else {
      const out = this.#o.registry.reconfirm(id, actor)!;
      this.#reply(c, ref, { ok: true, command: view(out, this.#o.clock.now()) });
    }
    this.#dirty = true;
  }

  #actor(s: Session): Actor {
    return { kind: 'operator', operatorId: s.user.id, role: s.user.role };
  }

  #burst(): number { return PARAMS.browserMessagesPerSecond.value * 2; }

  #take(c: Client): boolean {
    const now = this.#o.clock.now();
    c.tokens = Math.min(this.#burst(), c.tokens + ((now - c.tokensAt) / 1000) * PARAMS.browserMessagesPerSecond.value);
    c.tokensAt = now;
    if (c.tokens < 1) return false;
    c.tokens -= 1;
    return true;
  }

  #refuse(c: Client, ref: string | null, reason: string): void {
    c.refusals++;
    if (c.refusals <= LOGGED_REFUSALS || c.refusals % 100 === 0) this.#o.log(`browser message refused (${c.session.user.id}, refusal ${c.refusals}): ${reason}`);
    this.#reply(c, ref, { ok: false, error: reason });
  }

  #drop(c: Client, code: number, reason: string): void {
    if (c.closed) return;
    c.closed = true;
    this.#clients.delete(c);
    this.#dirty = true;
    try { c.sock.close(code, reason); } catch { /* already gone */ }
    this.#o.log(`browser closed by the service: ${c.session.user.id} (${reason}); ${this.#clients.size} open`);
  }
}

function view(r: CommandRecord, now: number): CommandView {
  return {
    id: r.id, vehicleId: r.vehicleId, action: r.action,
    by: r.actor.kind === 'operator' ? r.actor.operatorId : `system:${r.actor.rule}`,
    status: r.status, summary: summarise(r, now), createdServerMs: r.createdServerMs,
    attempts: r.attempts.length, maxAttempts: r.maxAttempts, open: !SETTLE_CLOSED.has(r.status),
    waitingForLink: r.status === 'pending' && r.hold !== null, needsReconfirm: r.hold?.needsReconfirm ?? false,
    failure: r.failure?.message ?? null,
  };
}
// The gateway link: one connection to the site per service, that recovers on its own and never
// lets an old picture pass for a current one (TESTING.md L2.40-L2.44, L6.1, L6.2, L6.4).
//
// - TLS to GATEWAY_HOST:GATEWAY_PORT, logging in with GATEWAY_EMAIL. Credentials come from the
//   environment only, and are never logged.
// - Reconnects with capped, jittered exponential backoff. A login accepted and then closed before
//   hello is a site-link outage (PROTOCOL.md §1.1), handled the same way.
// - Down after PARAMS.linkDownAfter with no heartbeat: the connection is dropped and redialled, and
//   fleet state is told, so nothing is shown as live meanwhile.
// - Every line goes to fleet state; then to subscribers (the command registry). On hello the
//   registry replays its in-flight commands.
// - Time and randomness are injected: backoff and watchdogs run on the Clock.
import { connect as tlsConnect } from 'node:tls';
import { isIP } from 'node:net';
import { StringDecoder } from 'node:string_decoder';
import type { Clock, TimerHandle } from './clock.ts';
import type { FleetState } from './fleet.ts';
import { parseLine } from './ingest.ts';
import { PARAMS } from './params.ts';
import { AUTH_ERRORS, type AuthErrorReason, type ClientMessage, type CommandMessage, type Hello } from './protocol.ts';
import type { CommandRegistry, CommandTransport } from './registry.ts';

// ---- transport ----

export interface LinkSocket {
  write(line: string): void; // one NDJSON line, without the newline
  close(): void;             // no onClose follows a close we asked for
}

export interface DialHandlers {
  onLine(line: string): void;
  onClose(reason: string): void;
}

export type Dialer = (h: DialHandlers) => LinkSocket;

// PROTOCOL.md §1: the gateway closes a connection that sends a line over 64 KiB. We refuse to send
// one, and treat a peer that sends a far longer one as broken.
export const MAX_LINE_BYTES = 64 * 1024;
const MAX_BUFFER_CHARS = 16 * MAX_LINE_BYTES;

export interface TlsTarget {
  host: string;
  port: number;
  ca?: string | Buffer; // tests only: the fake's throwaway certificate. Production uses the system's trust store
}

export function tlsDialer(t: TlsTarget): Dialer {
  return (h) => {
    const sock = tlsConnect({ host: t.host, port: t.port, ...(isIP(t.host) ? {} : { servername: t.host }), ...(t.ca ? { ca: t.ca } : {}) });
    sock.setNoDelay(true);
    const decoder = new StringDecoder('utf8');
    let buf = '';
    let done = false;
    let why: string | null = null;
    const finish = (reason: string) => {
      if (done) return;
      done = true;
      h.onClose(reason);
    };
    sock.on('data', (chunk: Buffer) => {
      buf += decoder.write(chunk);
      let start = 0;
      for (let i = buf.indexOf('\n'); i >= 0 && !done; i = buf.indexOf('\n', start)) {
        const end = i > start && buf.charCodeAt(i - 1) === 13 ? i - 1 : i;
        h.onLine(buf.slice(start, end));
        start = i + 1;
      }
      buf = start === 0 ? buf : buf.slice(start);
      if (buf.length > MAX_BUFFER_CHARS && !done) {
        sock.destroy();
        finish(`the gateway sent a line over ${MAX_BUFFER_CHARS} characters`);
      }
    });
    sock.on('error', (e: Error) => { why = e.message; });
    sock.on('close', () => finish(why ? `connection failed: ${why}` : 'connection closed by the gateway'));
    return {
      write: (line) => { if (!done) sock.write(line + '\n'); },
      close: () => { done = true; sock.destroy(); },
    };
  };
}

export interface LinkConfig { host: string; port: number; email: string }

// GATEWAY_HOST, GATEWAY_PORT and GATEWAY_EMAIL (BRIEF.md). The error names what is missing and
// never echoes a value.
export function linkConfigFromEnv(env: Record<string, string | undefined>): LinkConfig {
  const missing = ['GATEWAY_HOST', 'GATEWAY_PORT', 'GATEWAY_EMAIL'].filter((k) => !env[k] || env[k]!.trim() === '');
  if (missing.length > 0) throw new Error(`missing environment variables: ${missing.join(', ')}`);
  const port = Number(env.GATEWAY_PORT);
  if (!Number.isInteger(port) || port <= 0 || port > 65_535) throw new Error('GATEWAY_PORT is not a port number');
  return { host: env.GATEWAY_HOST!.trim(), port, email: env.GATEWAY_EMAIL!.trim() };
}

// ---- the link ----

export type LinkState = 'idle' | 'connecting' | 'up' | 'down' | 'stopped';

export interface LinkStatus {
  state: LinkState;
  sinceMs: number;                  // on the injected clock
  reason: string;                   // why it is in this state, in words
  failures: number;                 // consecutive attempts since the last hello
  nextAttemptAtMs: number | null;
  dials: number;                    // connections opened, ever
  lastHeartbeatMs: number | null;
  authError: AuthErrorReason | null;
}

export type LinkEvent =
  | { type: 'status'; status: LinkStatus }
  | { type: 'up'; hello: Hello }
  | { type: 'down'; reason: string }        // only on leaving 'up'
  | { type: 'message'; msg: Record<string, unknown> & { type: string } }
  | { type: 'alarm'; message: string };

export interface LinkOptions {
  clock: Clock;
  fleet: FleetState;

// The fake gateway: connections, the auth flow (PROTOCOL.md §1.1), line parsing, command_id
// de-duplication (§5), and broadcast of everything to every client. The site itself is the model
// (fake/model.ts). Transports plug in through `attach`: the in-process TestClient below for tests,
// and fake/tls.ts for research/probe.py.
//
// Layers: model (truth) -> telemetry faults (fake/faults.ts, in the model's telemetry step) ->
// gateway (this file) -> the site radio (fake/radio.ts: telemetry loss, duplicates, lateness,
// truncation; ack latency and loss) -> every connection -> transport. Link drops and the slow-reader
// cut-off act on connections here. Lines are written as the live gateway writes them (fake/wire.ts).
import type { Clock, TimerHandle } from '../src/clock.ts';
import { ACTIONS, type Action, type AuthErrorReason, type CommandAck, type GatewayMessage } from '../src/protocol.ts';
import { DEFAULT_BEHAVIOUR, type Behaviour } from './behaviour.ts';
import { planTrucks, TelemetryFaults, TruthLog, type Faults, type TruthEntry } from './faults.ts';
import { SiteModel, type AckResult, type Blasts, type SiteConfig, type TruckInit, type TruckTruth } from './model.ts';
import { matches, SiteRadio } from './radio.ts';
import { Rng } from './rng.ts';
import { toWire } from './wire.ts';
import type { ZoneState } from '../src/protocol.ts';

export interface FakeConfig {
  seed: number;
  site: SiteConfig;
  blasts?: Blasts;            // default 'random'
  trucks?: TruckInit[];       // placement for some or all trucks; the rest are spread by the seed
  behaviour?: Partial<Behaviour>;
  faults?: Faults;            // default none: milestone 1's perfect site. LIVE_DAY is the live catalogue
}

export interface Sink {
  write(line: string): void; // one NDJSON line, without the newline
  close(): void;
  behindBytes?(): number;    // bytes written but not yet read by the client, if the transport knows
}

const EMAIL = /^[^@\s]+@[^@\s]+\.[^@\s]+$/;
const MAX_COMMAND_ID = 128;

export class Connection {
  authed = false;
  closed = false;
  email: string | null = null;
  authTimer: TimerHandle | null = null;
  readonly #gw: FakeGateway;
  readonly #sink: Sink;

  constructor(gw: FakeGateway, sink: Sink) {
    this.#gw = gw;
    this.#sink = sink;
  }

  // A line from the client, without its newline.
  receive(line: string): void {
    if (this.closed) return;
    this.#gw.receive(this, line);
  }

  // The transport says the peer has gone.
  disconnect(): void {
    this.#gw.drop(this, false);
  }

  write(line: string): void {
    if (this.closed) return;
    // §1: a client more than about 4 MB behind on reading is disconnected.
    if ((this.#sink.behindBytes?.() ?? 0) > this.#gw.behaviour.maxBehindBytes) { this.#gw.slowReader(this); return; }
    this.#sink.write(line);
  }

  closeSink(): void {
    this.#sink.close();
  }
}

export class FakeGateway {
  readonly model: SiteModel;
  readonly behaviour: Readonly<Behaviour>;
  readonly faults: Readonly<Faults>;
  readonly truthLog = new TruthLog();
  readonly #clock: Clock;
  readonly #conns: Connection[] = [];
  readonly #seen = new Map<string, { key: string; ack: CommandAck }>();
  readonly #radio: SiteRadio;
  readonly #rngCommands: Rng;
  readonly #rngLink: Rng;
  readonly #timers: TimerHandle[] = [];
  #commandCount = 0;
  #linkDown: TruthEntry | null = null;
  #stalled: TruthEntry | null = null;
  #linkDropPlanned = false; // the first random drop waits for a CLOSING; later ones follow on

  constructor(clock: Clock, config: FakeConfig) {
    const faults: Faults = { ...config.faults };
    const b: Behaviour = { ...DEFAULT_BEHAVIOUR, ...(faults.bayClosing ? { blastBay: true } : {}), ...config.behaviour };
    this.behaviour = Object.freeze(b);
    this.faults = Object.freeze(faults);
    this.#clock = clock;
    this.model = new SiteModel(clock, (m) => this.#broadcast(m), {
      seed: config.seed, site: config.site, behaviour: b, blasts: config.blasts ?? 'random', trucks: config.trucks ?? [],
      log: this.truthLog,
    });
    this.#radio = new SiteRadio(clock, b, faults, this.truthLog, config.seed, (line) => this.#fanOut(line));
    const root = new Rng(config.seed);
    this.#rngCommands = root.fork('command-faults');
    this.#rngLink = root.fork('link');
    this.#setUpTruckFaults(config.seed);
  }

  start(): void {
    this.model.start();
    const lf = this.faults.linkDrops;
    if (Array.isArray(lf)) for (const d of lf) this.#later(d.atMs, () => this.#linkDrop(d.durationMs));
    for (const st of this.faults.linkStalls ?? []) {
      this.#later(st.atMs, () => {
        this.#stalled = this.truthLog.start(this.#clock.now(), null, 'link_stall', { durationMs: st.durationMs });
        this.#later(st.durationMs, () => { if (this.#stalled) this.#stalled.untilMs = this.#clock.now(); this.#stalled = null; });
      });
    }
  }

  stop(): void {
    this.model.stop();
    for (const t of this.#timers) this.#clock.clearTimeout(t);
    this.#timers.length = 0;
  }

  #later(ms: number, fn: () => void): void {
    this.#timers.push(this.#clock.setTimeout(fn, ms));
  }

  // Truth and fault access for tests.
  truth(id: string): TruckTruth { return this.model.truth(id); }
  truthAll(): TruckTruth[] { return this.model.truthAll(); }
  zone(id: string): ZoneState { return this.model.zone(id); }
  injectFault(id: string, code: string): void { this.model.injectFault(id, code); }
  get linkUp(): boolean { return this.#linkDown === null; }

  // Per-truck injectors: which truck and when come from the seed (fake/faults.ts planTrucks).
  #setUpTruckFaults(seed: number): void {
    const f = this.faults, b = this.behaviour, m = this.model, log = this.truthLog;
    const plan = planTrucks(f, m.site.vehicles, b, seed);
    const rng = new Rng(seed).fork('truck-faults');
    m.setQueuedDrops(f.queuedDrops === true);
    if (plan.clockSkew) {
      // Every controller's clock is a little off; one is about an hour ahead.
      for (const v of m.site.vehicles) m.setDeviceOffset(v, Math.round(rng.uniform(-b.clockJitterMs, b.clockJitterMs)));
      const skew = Math.round(rng.uniform(b.skewMinMs, b.skewMaxMs));
      m.setDeviceOffset(plan.clockSkew.vehicle, skew);
      log.start(m.startMs, plan.clockSkew.vehicle, 'clock_skew', { offsetMs: skew });
    }
    if (plan.weakPack) {
      // Both live weak packs were empty trucks on their way to load, and died on the climb after it.
      // Unless the truck is pinned, take an empty one that no motion or silence fault is on (a loaded
      // truck already past the load point would die within seconds); the dealt truck if there is none.
      let v = plan.weakPack.vehicle;
      if (typeof f.weakPack !== 'object' || f.weakPack.vehicle === undefined) {
        const busy = new Set([plan.frozenMoving, plan.frozenStationary, plan.silent, plan.hydPressureLow, plan.batteryDepleted].map((p) => p?.vehicle));
        const empty = m.site.vehicles.filter((x) => !busy.has(x) && !m.truth(x).loaded);
        if (empty.length > 0 && !empty.includes(v)) v = rng.pick(empty);
        plan.weakPack.vehicle = v;
      }
      m.weakPack(v, rng.uniform(b.weakFactorMin, b.weakFactorMax), rng.uniform(b.weakDiesMinFraction, b.weakDiesMaxFraction));
    }
    const hyd = plan.hydPressureLow, dep = plan.batteryDepleted;
    if (hyd) this.#later(hyd.atMs, () => m.injectFault(hyd.vehicle, 'HYD_PRESSURE_LOW'));
    if (dep) this.#later(dep.atMs, () => m.deplete(dep.vehicle));
    if (plan.frozenMoving || plan.frozenStationary || plan.silent || plan.seqReset || plan.fractionalSoc || plan.malformed) {
      m.setTelemetryFaults(new TelemetryFaults(plan, b, log, seed, m.startMs));
    }
  }

  // ---- link drops (§1: the whole site link; logins are accepted, then closed before hello) ----

  #linkDrop(durationMs: number): void {
    if (this.#linkDown) return;
    const now = this.#clock.now();
    this.#linkDown = this.truthLog.start(now, null, 'link_drop', { durationMs });
    for (const c of [...this.#conns]) this.drop(c, true);
    this.#later(durationMs, () => {
      if (this.#linkDown) this.#linkDown.untilMs = this.#clock.now();
      this.#linkDown = null;
    });
    if (this.faults.linkDrops === true) {
      const next = Math.round(this.#rngLink.uniform(this.behaviour.linkSpacingMinMs, this.behaviour.linkSpacingMaxMs));
      const duration = this.#randomLinkDuration();
      this.#later(next, () => this.#linkDrop(duration));
    }
  }

  #randomLinkDuration(): number {
    return Math.round(this.#rngLink.uniform(this.behaviour.linkDownMinMs, this.behaviour.linkDownMaxMs));
  }

  // The first random drop lands in a blast notice, as in both complete live runs: shortly after the
  // first CLOSING once the day is under way.
  #onZoneEvent(m: GatewayMessage): void {
    if (this.faults.linkDrops !== true || this.#linkDropPlanned) return;
    if (m.type !== 'zone_event' || m.status !== 'CLOSING') return;
    if (this.#clock.now() - this.model.startMs < this.behaviour.linkFirstAfterMs) return;
    this.#linkDropPlanned = true;
    const after = Math.round(this.#rngLink.uniform(0, this.behaviour.linkInNoticeMaxMs));
    const duration = this.#randomLinkDuration();
    this.#later(after, () => this.#linkDrop(duration));
  }

  slowReader(conn: Connection): void {
    this.truthLog.event(this.#clock.now(), null, 'slow_reader', { email: conn.email });
    this.drop(conn, true);
  }

  // A new connection from a transport. It must authenticate within the timeout.
  attach(sink: Sink): Connection {
    const conn = new Connection(this, sink);
    this.#conns.push(conn);
    conn.authTimer = this.#clock.setTimeout(() => {
      if (!conn.authed && !conn.closed) this.#authError(conn, 'AUTH_TIMEOUT');
    }, this.behaviour.authTimeoutMs);
    return conn;
  }

  // An in-process client, for tests.
  connect(): TestClient {
    return new TestClient(this);
  }

  receive(conn: Connection, line: string): void {
    if (Buffer.byteLength(line, 'utf8') > this.behaviour.maxLineBytes) { this.drop(conn, true); return; } // §7
    if (!conn.authed) { this.#auth(conn, line); return; }
    let m: unknown;
    try { m = JSON.parse(line); } catch { m = undefined; }
    if (!isObject(m)) { this.#sendAck(this.#ack('<unparseable>', null, { status: 'REJECTED', reason: 'BAD_JSON' }), '<unparseable>'); return; }
    if (m.type === 'command') this.#command(m);
    else if (m.type === 'drive') this.model.drive(m);
    // §7: anything else is ignored
  }

  drop(conn: Connection, closeSink: boolean): void {
    if (conn.closed) return;
    conn.closed = true;
    if (conn.authTimer) this.#clock.clearTimeout(conn.authTimer);
    const i = this.#conns.indexOf(conn);
    if (i >= 0) this.#conns.splice(i, 1);
    if (closeSink) conn.closeSink();
  }

  #auth(conn: Connection, line: string): void {
    if (conn.authTimer) this.#clock.clearTimeout(conn.authTimer);
    let m: unknown;
    try { m = JSON.parse(line); } catch { this.#authError(conn, 'BAD_AUTH'); return; }
    if (!isObject(m) || m.type !== 'auth') { this.#authError(conn, 'AUTH_REQUIRED'); return; }
    if (typeof m.email !== 'string' || !EMAIL.test(m.email)) { this.#authError(conn, 'BAD_EMAIL'); return; }
    if (this.#conns.filter((c) => c.authed).length >= this.behaviour.maxConnections) { this.#authError(conn, 'TOO_MANY_CONNECTIONS'); return; }
    if (this.#linkDown) { this.drop(conn, true); return; } // §1: accepted, then closed before hello
    conn.authed = true;
    conn.email = m.email;
    conn.write(toWire(this.model.hello(m.email)));
  }

  #authError(conn: Connection, reason: AuthErrorReason): void {
    conn.write(toWire({ type: 'auth_error', reason }));
    this.drop(conn, true);
  }

  #command(m: Record<string, unknown>): void {
    const vehicle = typeof m.vehicle_id === 'string' ? m.vehicle_id : null;
    const action = String(m.action);
    const id = m.command_id;
    if (typeof id !== 'string' || id.length === 0 || id.length > MAX_COMMAND_ID) {
      const echo = typeof id === 'string' && id.length > 0 ? id : '<missing>';
      this.#sendAck(this.#ack(echo, vehicle, { status: 'REJECTED', reason: 'BAD_COMMAND_ID' }), action);
      return;
    }
    const key = canonical(m);
    const prev = this.#seen.get(id);
    if (prev) {
      // §5: same payload returns the original result and does not execute again
      if (prev.key === key) this.#sendAck({ ...prev.ack, server_time_ms: this.#clock.now() }, action);
      else this.#sendAck(this.#ack(id, vehicle, { status: 'REJECTED', reason: 'COMMAND_ID_REUSED' }), action);
      return;
    }
    const n = ++this.#commandCount;
    const ignored = matches(this.faults.ignoredCommands, this.#rngCommands.chance(this.behaviour.ignoredProbability),
      { n, command_id: id, vehicle_id: vehicle ?? '', action });
    let result: AckResult;
    if (typeof m.operator_id !== 'string' || m.operator_id.length === 0) result = { status: 'REJECTED', reason: 'MISSING_OPERATOR' };
    else if (vehicle === null || !this.model.hasVehicle(vehicle)) result = { status: 'REJECTED', reason: 'UNKNOWN_VEHICLE' };
    else if (!(ACTIONS as readonly unknown[]).includes(m.action)) result = { status: 'REJECTED', reason: 'UNSUPPORTED_ACTION' };
    else {
      result = this.model.command({
        command_id: id, vehicle_id: vehicle, action: m.action as Action, operator_id: m.operator_id, force: m.force, lease_id: m.lease_id, ignored,
      });
    }
    const ack = this.#ack(id, vehicle, result);
    this.#seen.set(id, { key, ack });
    this.#sendAck(ack, action, n);
  }

  // Acks go through the radio: late and sometimes lost, when those faults are on.
  #sendAck(ack: CommandAck, action: string, n = 0): void {
    this.#radio.ack(toWire(ack), ack, n, action);
  }

  #ack(commandId: string, vehicle: string | null, r: AckResult): CommandAck {
    return {
      type: 'command_ack', command_id: commandId, vehicle_id: vehicle, status: r.status, server_time_ms: this.#clock.now(),
      ...(r.reason !== undefined ? { reason: r.reason } : {}),
      ...(r.holder !== undefined ? { holder: r.holder } : {}),
      ...(r.lease_id !== undefined ? { lease_id: r.lease_id } : {}),
      ...(r.lease_idle_timeout_ms !== undefined ? { lease_idle_timeout_ms: r.lease_idle_timeout_ms } : {}),
      ...(r.deadman_ms !== undefined ? { deadman_ms: r.deadman_ms } : {}),
    };
  }

  #broadcast(m: GatewayMessage): void {
    const line = toWire(m);
    if (m.type === 'telemetry') { this.#radio.telemetry(line, String(m.vehicle_id), m.seq); return; }
    if (m.type === 'zone_event') this.#onZoneEvent(m);
    this.#fanOut(line);
  }

  // Every authenticated client gets every line. Nothing is queued for a disconnected client (§1).
  #fanOut(line: string): void {
    if (this.#stalled) return; // a stalled link delivers nothing, and nothing is kept for later
    for (const c of [...this.#conns]) if (c.authed && !c.closed) c.write(line);
  }
}

// An in-process client: what a transport would deliver, as lines and parsed messages.
export class TestClient {
  readonly lines: string[] = [];
  readonly unparseable: string[] = [];
  closed = false;
  readonly #parsed: GatewayMessage[] = [];
  readonly #listeners: Array<(m: GatewayMessage) => void> = [];
  readonly #conn: Connection;
  #paused: string[] | null = null;
  #pausedBytes = 0;

  constructor(gw: FakeGateway) {
    this.#conn = gw.attach({
      write: (line) => {
        if (this.#paused) { this.#paused.push(line); this.#pausedBytes += Buffer.byteLength(line, 'utf8') + 1; return; }
        this.#read(line);
      },
      close: () => { this.closed = true; },
      behindBytes: () => this.#pausedBytes,
    });
  }

  #read(line: string): void {
    this.lines.push(line);
    let m: GatewayMessage;
    try { m = JSON.parse(line) as GatewayMessage; } catch { this.unparseable.push(line); return; } // truncated lines
    this.#parsed.push(m);
    for (const fn of this.#listeners) fn(m);
  }

  // A slow reader: stop reading, so lines pile up unread at the gateway; resume reads them all.
  pause(): void { this.#paused ??= []; }
  resume(): void {
    const lines = this.#paused ?? [];
    this.#paused = null;
    this.#pausedBytes = 0;
    for (const l of lines) this.#read(l);
  }

  send(msg: object | string): void {
    this.#conn.receive(typeof msg === 'string' ? msg : JSON.stringify(msg));
  }

  messages(): GatewayMessage[] {
    return this.#parsed;
  }

  onMessage(fn: (m: GatewayMessage) => void): void {
    this.#listeners.push(fn);
  }

  close(): void {
    this.#conn.disconnect();
    this.closed = true;
  }
}

function isObject(x: unknown): x is Record<string, unknown> {
  return typeof x === 'object' && x !== null && !Array.isArray(x);
}

// Key order does not make a different payload.
function canonical(x: unknown): string {
  if (Array.isArray(x)) return `[${x.map(canonical).join(',')}]`;
  if (isObject(x)) return `{${Object.keys(x).sort().map((k) => `${JSON.stringify(k)}:${canonical(x[k])}`).join(',')}}`;
  return JSON.stringify(x);
}
// Lines as the live gateway writes them: Python's json.dumps defaults, i.e. ", " and ": " between
// items, and floats keep their ".0" (speed_mps 2.0, payload_kg 42000.0). The captures show which
// fields are floats; everything else (seq, t_device_ms, server_time_ms, effective_at_ms, the ack's
// lease timings, last_drive_seq, last_drive_sent_ms) is an integer. Field order is insertion order,
// as JSON.stringify's. Lengths matter: truncated lines are cut at a measured character count.
// Not matched: Python escapes non-ASCII as \uXXXX; nothing the fake sends has any.
const FLOAT_FIELDS = new Set(['soc_pct', 'speed_mps', 'offset_m', 'payload_kg', 'length_m', 'start_m', 'loop_length_m']);

export function toWire(x: unknown): string {
  return enc(x, false);
}

// Hand-rolled for speed: a 15-minute day writes ~55,000 lines (L0.C4 times it).
const KEYS = new Map<string, string>();
const key = (k: string): string => {
  let s = KEYS.get(k);
  if (s === undefined) { s = JSON.stringify(k) + ': '; KEYS.set(k, s); }
  return s;
};

function enc(x: unknown, float: boolean): string {
  if (x === null || x === undefined) return 'null';
  const t = typeof x;
  if (t === 'number') {
    const n = x as number;
    if (!Number.isFinite(n)) return 'null';
    return float && Number.isInteger(n) ? n + '.0' : '' + n;
  }
  if (t === 'string') return JSON.stringify(x);
  if (t === 'boolean') return x ? 'true' : 'false';
  if (t !== 'object') return 'null';
  if (Array.isArray(x)) {
    let out = '[';
    for (let i = 0; i < x.length; i++) out += (i ? ', ' : '') + enc(x[i], false);
    return out + ']';
  }
  let out = '{';
  let first = true;
  const o = x as Record<string, unknown>;
  for (const k in o) {
    const v = o[k];
    if (v === undefined) continue;
    out += (first ? '' : ', ') + key(k) + enc(v, FLOAT_FIELDS.has(k));
    first = false;
  }
  return out + '}';
}
// Run the fake gateway over TLS on the real clock, for research/probe.py and by-hand checks.
//
//   openssl req -x509 -newkey rsa:2048 -nodes -days 1 -subj /CN=127.0.0.1 \
//     -addext subjectAltName=IP:127.0.0.1 -keyout key.pem -out cert.pem
//   node fake/main.ts --key key.pem --cert cert.pem [--port 7443] [--seed 1] [--blasts random|none]
//                     [--fault <vehicle>:<code> ...] [--day live|perfect]
// --day live switches on every injector of a live day (fake/faults.ts LIVE_DAY); the default is perfect.
//
// Then point a client at it with GATEWAY_HOST=127.0.0.1, GATEWAY_PORT and SSL_CERT_FILE=cert.pem.
// The default site is DLH-1 (fake/dlh1.ts). Never point a probe at the real gateway by accident:
// this prints the address it serves.
import { readFileSync } from 'node:fs';
import { parseArgs } from 'node:util';
import { SystemClock } from '../src/clock.ts';
import { FakeGateway } from './gateway.ts';
import { DLH1 } from './dlh1.ts';
import { listenTls } from './tls.ts';
import { LIVE_DAY } from './faults.ts';

const { values } = parseArgs({
  options: {
    key: { type: 'string' },
    cert: { type: 'string' },
    host: { type: 'string', default: '127.0.0.1' },
    port: { type: 'string', default: '0' },
    seed: { type: 'string', default: '1' },
    blasts: { type: 'string', default: 'random' },
    fault: { type: 'string', multiple: true, default: [] },
    day: { type: 'string', default: 'perfect' },
  },
});
if (!values.key || !values.cert) {
  console.error('usage: node fake/main.ts --key key.pem --cert cert.pem [--port N] [--seed N] [--blasts random|none] [--fault VEHICLE:CODE]');
  process.exit(2);
}
if (values.blasts !== 'random' && values.blasts !== 'none') {
  console.error(`--blasts must be random or none, not ${values.blasts}`);
  process.exit(2);
}

if (values.day !== 'live' && values.day !== 'perfect') {
  console.error(`--day must be live or perfect, not ${values.day}`);
  process.exit(2);
}
const gw = new FakeGateway(new SystemClock(), { seed: Number(values.seed), site: DLH1, blasts: values.blasts, ...(values.day === 'live' ? { faults: LIVE_DAY } : {}) });
for (const f of values.fault) {
  const [vehicle, code] = f.split(':');
  if (!vehicle || !code) { console.error(`--fault wants VEHICLE:CODE, not ${f}`); process.exit(2); }
  gw.injectFault(vehicle, code);
}
gw.start();
const server = await listenTls(gw, { key: readFileSync(values.key), cert: readFileSync(values.cert), host: values.host, port: Number(values.port) });
console.log(`fake gateway (site ${DLH1.site_id}, seed ${values.seed}) listening on ${values.host}:${server.port}`);

const shutdown = () => { gw.stop(); void server.close().then(() => process.exit(0)); };
process.on('SIGINT', shutdown);
process.on('SIGTERM', shutdown);

// A fleet state on this site's hello with a manual clock, plus a telemetry builder. Hand-built
// messages are for single-fault cases only; real data comes from research/fixtures/.
import { ManualClock } from '../../src/clock.ts';
import { FleetState, type FleetEvent, type TruckView } from '../../src/fleet.ts';
import type { Hello } from '../../src/protocol.ts';
import { helloAt, readRecords, type FixtureRecord } from './fixtures.ts';

export const T0 = 1_790_000_000_000;

export function telemetry(over: Record<string, unknown> = {}): Record<string, unknown> {
  return {
    type: 'telemetry', vehicle_id: 'HT-01', seq: 1, t_device_ms: T0, state: 'TRAMMING', task: null,
    soc_pct: 60, speed_mps: 3, direction: 'FWD', segment_id: 'SEG-DEC-1', zone_id: 'DECLINE', offset_m: 10,
    payload_kg: 0, faults: [],
    control: { mode: 'AUTO', operator_id: null, deadman: false, last_drive_seq: null, last_drive_sent_ms: null },
    ...over,
  };
}

export interface Rig {
  clock: ManualClock;
  fleet: FleetState;
  events: FleetEvent[];
  send(over?: Record<string, unknown>): void;
  line(text: string): void;
  advance(ms: number): void;
  truck(id?: string): TruckView;
}

export function rig(hello: Hello | null = helloAt(T0)): Rig {
  const clock = new ManualClock(T0);
  const fleet = new FleetState(clock);
  const events: FleetEvent[] = [];
  fleet.subscribe((e) => events.push(e));
  if (hello) fleet.ingest(hello);
  return {
    clock, fleet, events,
    send: (over = {}) => fleet.ingest(telemetry(over)),
    line: (text) => fleet.ingestLine(text),
    advance: (ms) => { clock.advance(ms); fleet.tick(); },
    truck: (id = 'HT-01') => {
      const t = fleet.snapshot().trucks.find((x) => x.vehicleId === id);
      if (!t) throw new Error(`no truck ${id}`);
      return t;
    },
  };
}

// Replays fixture records in arrival order: the clock is set to each record's rx_ms, messages are
// fed as the lines they arrived as, unparseable lines as their raw text. `onRecord` runs after each.
// Records are sorted by rx_ms (stably) first, as a guard: research/trim.py once wrote multi-part
// fixtures part by part, out of arrival order. It now sorts them.
//
// Incremental, for the fixture player (player/): advanceTo() feeds every record up to a moment and
// then moves the clock to it, so the picture ages between records as it would live. Records the
// product never receives ('sent', 'closed_by_peer') only move the clock.
export class Replayer {
  readonly records: FixtureRecord[];
  readonly start: number;
  readonly end: number;
  readonly clock: ManualClock;
  readonly fleet: FleetState;
  readonly events: FleetEvent[] = [];
  readonly #onRecord: ((r: FixtureRecord, f: FleetState, c: ManualClock) => void) | undefined;
  #next = 0;

  // `hello`: the hello to start from. By default this site's, re-timed to the first record with every
  // zone open (helloAt); null for none, when the fixture carries its own.
  constructor(records: FixtureRecord[], opts: { hello?: Hello | null; onRecord?: (r: FixtureRecord, f: FleetState, c: ManualClock) => void } = {}) {
    this.records = records.filter((r) => r.kind !== 'fixture' && typeof r.rx_ms === 'number').sort((a, b) => a.rx_ms! - b.rx_ms!);
    this.start = this.records[0]!.rx_ms!;
    this.end = this.records.at(-1)!.rx_ms!;
    this.clock = new ManualClock(this.start);
    this.fleet = new FleetState(this.clock);
    this.fleet.subscribe((e) => this.events.push(e));
    this.#onRecord = opts.onRecord;
    const hello = opts.hello === undefined ? helloAt(this.start) : opts.hello;
    if (hello) this.fleet.ingest(hello);
  }

  get done(): boolean { return this.#next >= this.records.length; }

  // When the next record arrives, or null at the end.
  nextAt(): number | null { return this.records[this.#next]?.rx_ms ?? null; }

  advanceTo(t: number): void {
    for (let r = this.records[this.#next]; r && r.rx_ms! <= t; r = this.records[++this.#next]) {
      this.clock.advance(Math.max(0, r.rx_ms! - this.clock.now()));
      if (r.kind === 'msg') this.fleet.ingestLine(JSON.stringify(r.m));
      else if (r.kind === 'unparseable') this.fleet.ingestLine(String(r.raw));
      else if (r.kind === 'connected') this.fleet.newConnection();
      this.fleet.tick();
      this.#onRecord?.(r, this.fleet, this.clock);
    }
    if (t > this.clock.now()) {
      this.clock.advance(t - this.clock.now());
      this.fleet.tick();
    }
  }
}

export function replay(records: FixtureRecord[], opts: { hello?: boolean; onRecord?: (r: FixtureRecord, f: FleetState, c: ManualClock) => void } = {}) {
  const r = new Replayer(records, { hello: opts.hello === false ? null : undefined, onRecord: opts.onRecord });
  r.advanceTo(r.end);
  return { clock: r.clock, fleet: r.fleet, events: r.events, start: r.start, end: r.end };
}

export { readRecords };
// A command registry on a manual clock, with fleet state on this site's hello, a store in a temp
// directory, and a scripted transport that records what was sent. Hand-built messages are for
// single-case tests; the fixture tests replay research/fixtures/ instead.
import { mkdtempSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { ManualClock } from '../../src/clock.ts';
import { FleetState } from '../../src/fleet.ts';
import type { CommandMessage } from '../../src/protocol.ts';
import { ALLOW_ALL_GATE_NO_BLAST_SAFETY, CommandRegistry, type Actor, type RegistryEvent, type SafetyGate } from '../../src/registry.ts';
import { Store } from '../../src/store.ts';
import { helloAt } from './fixtures.ts';
import { T0, telemetry } from './rig.ts';

export const PRIYA: Actor = { kind: 'operator', operatorId: 'priya', role: 'operator' };
export const DAVE: Actor = { kind: 'operator', operatorId: 'dave', role: 'operator' };
export const MARTA: Actor = { kind: 'operator', operatorId: 'marta', role: 'supervisor' };
export const BLAST: Actor = { kind: 'system', rule: 'blast-evacuation', inputs: { zone: 'Z', effectiveAtMs: 0 } };

export function tempDir(): { dir: string; dbPath: string; cleanup(): void } {
  const dir = mkdtempSync(join(tmpdir(), 'cr-registry-'));
  return { dir, dbPath: join(dir, 'control-room.db'), cleanup: () => rmSync(dir, { recursive: true, force: true }) };
}

export interface RegRig {
  clock: ManualClock;
  fleet: FleetState;
  store: Store;
  registry: CommandRegistry;
  sent: CommandMessage[];
  events: RegistryEvent[];
  dbPath: string;
  setUp(up: boolean): void;
  feed(msg: Record<string, unknown>): void;
  tel(vehicle: string, over?: Record<string, unknown>): void;
  ack(commandId: string, status: 'ACCEPTED' | 'REJECTED', extra?: Record<string, unknown>): void;
  advance(ms: number, stepMs?: number): void;
  restart(opts?: { gate?: SafetyGate }): RegRig;
  cleanup(): void;
}

export interface RigOptions {
  gate?: SafetyGate;
  onSend?: (m: CommandMessage, rig: RegRig) => void;
  dbPath?: string;
  clock?: ManualClock;
  hello?: boolean;
}

export function regRig(o: RigOptions = {}): RegRig {
  const tmp = o.dbPath ? null : tempDir();
  const dbPath = o.dbPath ?? tmp!.dbPath;
  const clock = o.clock ?? new ManualClock(T0);
  const fleet = new FleetState(clock);
  if (o.hello !== false) fleet.ingest(helloAt(clock.now()));
  const store = new Store(dbPath);
  const sent: CommandMessage[] = [];
  const events: RegistryEvent[] = [];
  let up = true;
  const seq = new Map<string, number>();
  let n = 0;
  // eslint-disable-next-line prefer-const
  let rig: RegRig;
  const registry = new CommandRegistry({
    clock, fleet, store, gate: o.gate ?? ALLOW_ALL_GATE_NO_BLAST_SAFETY,
    newId: () => `r${clock.now() - T0}-${++n}`,
    transport: { isUp: () => up, send: (m) => { if (!up) return false; sent.push(m); o.onSend?.(m, rig); return true; } },
  });
  registry.subscribe((e) => events.push(e));
  const feed = (msg: Record<string, unknown>) => { fleet.ingest(msg); registry.message(msg); };
  rig = {
    clock, fleet, store, registry, sent, events, dbPath,
    setUp(v) { up = v; fleet.setLink(v, v ? 'connected' : 'down'); if (!v) registry.linkDown('test'); },
    feed,
    tel(vehicle, over = {}) {
      const s = (seq.get(vehicle) ?? 0) + 1;
      seq.set(vehicle, s);
      feed(telemetry({ vehicle_id: vehicle, seq: s, t_device_ms: clock.now(), ...over }));
    },
    ack(commandId, status, extra = {}) {
      const vehicle = sent.find((m) => m.command_id === commandId)?.vehicle_id ?? null;
      feed({ type: 'command_ack', command_id: commandId, vehicle_id: vehicle, status, server_time_ms: fleet.serverNow(), ...extra });
    },
    advance(ms, stepMs = 100) {
      for (let left = ms; left > 0; left -= stepMs) {
        clock.advance(Math.min(stepMs, left));
        fleet.tick();
        registry.tick();
      }
    },
    restart(r = {}) {
      store.close();
      return regRig({ dbPath, clock, gate: r.gate ?? o.gate, onSend: o.onSend, hello: o.hello });
    },
    cleanup() {
      try { store.close(); } catch { /* already closed */ }
      tmp?.cleanup();
    },
  };
  return rig;
}
// The gateway link and the command registry, wired together as the service will wire them, against
// the in-process fake gateway on a manual clock.
//
// The fake's milestone 1 has no link faults, so this dialer plays them at the transport, the way
// the live site shows them (research/fixtures/link-drop-in-notice):
//   - 'outage': a login is accepted and the connection closed before hello;
//   - 'blackhole': the connection stays open but nothing arrives (no heartbeats);
//   - dropAll(): the gateway closes every open connection.
// Milestone 2 of the fake adds outages of its own; these stay as the transport-level version.
import { ManualClock } from '../../src/clock.ts';
import { FleetState } from '../../src/fleet.ts';
import { attachRegistry, GatewayLink, type Dialer, type LinkEvent } from '../../src/link.ts';
import { ALLOW_ALL_GATE_NO_BLAST_SAFETY, CommandRegistry, type RegistryEvent, type SafetyGate } from '../../src/registry.ts';
import { Store } from '../../src/store.ts';
import { FakeGateway, type Connection, type FakeConfig } from '../../fake/gateway.ts';
import { DLH1 } from '../../fake/dlh1.ts';
import { T0 } from './rig.ts';
import { tempDir } from './registry-rig.ts';

export type DialMode = 'normal' | 'outage' | 'blackhole';

export class FakeDialer {
  mode: DialMode = 'normal';
  readonly dialTimes: number[] = [];
  readonly sentLines: string[] = [];
  readonly #gw: FakeGateway;
  readonly #clock: ManualClock;
  readonly #open = new Set<{ conn: Connection; close(): void }>();

  constructor(gw: FakeGateway, clock: ManualClock) {
    this.#gw = gw;
    this.#clock = clock;
  }

  get dials(): number { return this.dialTimes.length; }
  get openConnections(): number { return this.#open.size; }

  dial: Dialer = (h) => {
    this.dialTimes.push(this.#clock.now());
    if (this.mode === 'outage') {
      let closed = false;
      return {
        write: (line) => { this.sentLines.push(line); if (!closed) { closed = true; h.onClose('closed by the gateway'); } },
        close: () => { closed = true; },
      };
    }
    let closed = false;
    const conn = this.#gw.attach({
      write: (line) => { if (!closed && this.mode !== 'blackhole') h.onLine(line); },
      close: () => { if (!closed) { closed = true; this.#open.delete(entry); h.onClose('connection closed by the gateway'); } },
    });
    const entry = { conn, close: () => { closed = true; this.#open.delete(entry); conn.disconnect(); } };
    this.#open.add(entry);
    return {
      write: (line) => { this.sentLines.push(line); if (!closed) conn.receive(line); },
      close: () => entry.close(),
    };
  };

  // The gateway drops everyone.
  dropAll(): void {
    for (const e of [...this.#open]) this.#gw.drop(e.conn, true);
  }
}

export interface LinkRig {
  clock: ManualClock;
  gw: FakeGateway;
  dialer: FakeDialer;
  fleet: FleetState;
  store: Store;
  registry: CommandRegistry;
  link: GatewayLink;
  linkEvents: LinkEvent[];
  events: RegistryEvent[];
  dbPath: string;
  advance(ms: number, stepMs?: number): void;
  until(pred: () => boolean, maxMs: number, stepMs?: number): number; // elapsed ms, or -1
  restartService(): LinkRig; // a new process on the same database, the same gateway and clock
  cleanup(): void;
}

export function linkRig(config: Partial<FakeConfig> = {}, o: { gate?: SafetyGate; random?: () => number; email?: string; shared?: { clock: ManualClock; gw: FakeGateway; dialer: FakeDialer; dbPath: string } } = {}): LinkRig {
  const tmp = o.shared ? null : tempDir();
  const clock = o.shared?.clock ?? new ManualClock(T0);
  const gw = o.shared?.gw ?? new FakeGateway(clock, { seed: 7, site: DLH1, blasts: 'none', ...config });
  if (!o.shared) gw.start();
  const dialer = o.shared?.dialer ?? new FakeDialer(gw, clock);
  const dbPath = o.shared?.dbPath ?? tmp!.dbPath;
  const fleet = new FleetState(clock);
  const store = new Store(dbPath);
  const link = new GatewayLink({ clock, fleet, dial: dialer.dial, email: o.email ?? '<redacted-email>', random: o.random ?? (() => 0.5) });
  let n = 0;
  const registry = new CommandRegistry({ clock, fleet, store, transport: link, gate: o.gate ?? ALLOW_ALL_GATE_NO_BLAST_SAFETY, newId: () => `r${clock.now() - T0}-${++n}-${Math.floor(clock.now() % 997)}` });
  attachRegistry(link, registry);
  const linkEvents: LinkEvent[] = [];
  const events: RegistryEvent[] = [];
  link.subscribe((e) => linkEvents.push(e));
  registry.subscribe((e) => events.push(e));
  fleet.start();
  registry.start();
  const rig: LinkRig = {
    clock, gw, dialer, fleet, store, registry, link, linkEvents, events, dbPath,
    advance(ms, stepMs = 50) {
      for (let left = ms; left > 0; left -= stepMs) clock.advance(Math.min(stepMs, left));
    },
    until(pred, maxMs, stepMs = 50) {
      const start = clock.now();
      while (clock.now() - start <= maxMs) {
        if (pred()) return clock.now() - start;
        clock.advance(stepMs);
      }
      return -1;
    },
    restartService() {
      link.stop();
      registry.stop();
      fleet.stop();
      store.close();
      return linkRig(config, { ...o, shared: { clock, gw, dialer, dbPath } });
    },
    cleanup() {
      link.stop();
      registry.stop();
      fleet.stop();
      try { store.close(); } catch { /* closed already */ }
      if (!o.shared) { gw.stop(); tmp?.cleanup(); }
    },
  };
  return rig;
}
// End to end: the real service (`node src/main.ts`, a child process) against the fake gateway over
// TLS (fake/tls.ts) on 127.0.0.1, on the real clock. The certificate is made with openssl at test time
// in a temporary directory and deleted after; the service trusts it through NODE_EXTRA_CA_CERTS, a
// Node feature, so the product has no test-only trust code. The child's environment is built from
// scratch: nothing from the developer's shell (or a .env) leaks in, and it can never reach the real
// gateway.
import assert from 'node:assert/strict';
import { spawn, spawnSync, type ChildProcess } from 'node:child_process';
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { request } from 'node:http';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import WebSocket from 'ws';
import { SystemClock } from '../../src/clock.ts';
import { hashPassword } from '../../src/users.ts';
import { DEFAULT_BEHAVIOUR } from '../../fake/behaviour.ts';
import { DLH1 } from '../../fake/dlh1.ts';
import { LIVE_DAY, planTrucks, type Faults } from '../../fake/faults.ts';
import { FakeGateway, type Connection } from '../../fake/gateway.ts';
import { listenTls, type TlsServer } from '../../fake/tls.ts';

export const HAVE_OPENSSL = !spawnSync('openssl', ['version'], { stdio: 'ignore' }).error;
export const MAIN = new URL('../../src/main.ts', import.meta.url).pathname;
export const EMAIL = '<redacted-email>';

export function tempDir(prefix: string): { dir: string; cleanup(): void } {
  const dir = mkdtempSync(join(tmpdir(), prefix));
  return { dir, cleanup: () => rmSync(dir, { recursive: true, force: true }) };
}

export function makeCert(dir: string): { key: Buffer; cert: Buffer; certPath: string } {
  const r = spawnSync('openssl', ['req', '-x509', '-newkey', 'rsa:2048', '-nodes', '-days', '1', '-subj', '/CN=127.0.0.1',
    '-addext', 'subjectAltName=IP:127.0.0.1', '-keyout', join(dir, 'key.pem'), '-out', join(dir, 'cert.pem')], { stdio: 'pipe' });
  assert.equal(r.status, 0, `openssl failed: ${r.stderr}`);
  return { key: readFileSync(join(dir, 'key.pem')), cert: readFileSync(join(dir, 'cert.pem')), certPath: join(dir, 'cert.pem') };
}

// The fake gateway over TLS, recording every line any client sends it and every login.
export class FakeSite {
  readonly gw: FakeGateway;
  readonly lines: string[] = [];   // every line received from any client, as received
  logins = 0;                      // connections that sent a valid auth line
  #server: TlsServer | null = null;
  #port = 0;
  readonly #tls: { key: Buffer; cert: Buffer };
  readonly seed: number;
  readonly faults: Faults;

  constructor(tls: { key: Buffer; cert: Buffer }, o: { seed?: number; faults?: Faults; blasts?: 'random' | 'none' } = {}) {
    this.#tls = tls;
    this.seed = o.seed ?? 11;
    this.faults = o.faults ?? LIVE_DAY;
    this.gw = new FakeGateway(new SystemClock(), { seed: this.seed, site: DLH1, blasts: o.blasts ?? 'random', faults: this.faults });
    const receive = this.gw.receive.bind(this.gw);
    this.gw.receive = (conn: Connection, line: string) => {
      this.lines.push(line);
      const wasAuthed = conn.authed;
      receive(conn, line);
      if (!wasAuthed && conn.authed) this.logins++;
    };
    this.gw.start();
  }

  get port(): number { return this.#port; }

  async listen(): Promise<void> {
    this.#server = await listenTls(this.gw, { ...this.#tls, port: this.#port });
    this.#port = this.#server.port;
  }

  // The site link drops: every connection closed, nothing listening, until listen() again.
  async down(): Promise<void> {
    await this.#server?.close();
    this.#server = null;
  }

  sent(): Array<Record<string, any>> {
    return this.lines.map((l) => { try { return JSON.parse(l); } catch { return { unparseable: l }; } });
  }

  commands(): Array<Record<string, any>> { return this.sent().filter((m) => m.type === 'command'); }

  // Trucks the fake's live day leaves alone (no telemetry fault planned), so their telemetry can
  // confirm a command.
  cleanTrucks(): string[] {
    const plan = planTrucks(this.faults, DLH1.vehicles, DEFAULT_BEHAVIOUR, this.seed);
    const busy = new Set(Object.values(plan).map((p) => p?.vehicle));
    return DLH1.vehicles.filter((v) => !busy.has(v));
  }

  async stop(): Promise<void> {
    this.gw.stop();
    await this.#server?.close();
  }
}

