export interface RunningService {
  child: ChildProcess;
  url: string;
  port: number;
  origin: string;
  output(): string;
  exited: Promise<number | null>;
  stop(): Promise<number | null>;
}

// Starts `node src/main.ts` with exactly this environment (plus PATH), and waits for "listening on".
export async function startServiceProcess(env: Record<string, string>, o: { cwd?: string; timeoutMs?: number } = {}): Promise<RunningService> {
  const child = spawn(process.execPath, [MAIN], { cwd: o.cwd, env: { PATH: process.env.PATH ?? '/usr/bin:/bin', ...env }, stdio: ['ignore', 'pipe', 'pipe'] });
  let out = '';
  child.stdout!.setEncoding('utf8').on('data', (c: string) => { out += c; });
  child.stderr!.setEncoding('utf8').on('data', (c: string) => { out += c; });
  const exited = new Promise<number | null>((resolve) => child.once('exit', (code) => resolve(code)));
  const url = await new Promise<string>((resolve, reject) => {
    const deadline = setTimeout(() => reject(new Error(`service did not start:\n${out}`)), o.timeoutMs ?? 20_000);
    const check = () => {
      const m = /listening on (http:\/\/127\.0\.0\.1:\d+\/)/.exec(out);
      if (m) { clearTimeout(deadline); resolve(m[1]!); }
    };
    child.stdout!.on('data', check);
    void exited.then((code) => { clearTimeout(deadline); reject(new Error(`service exited with ${code} before listening:\n${out}`)); });
  });
  const port = Number(new URL(url).port);
  return {
    child, url, port, origin: `http://127.0.0.1:${port}`, output: () => out, exited,
    stop: async () => { if (child.exitCode === null) child.kill('SIGTERM'); return exited; },
  };
}

export interface Res { status: number; headers: Record<string, string | string[] | undefined>; body: string }

export function http(port: number, method: string, path: string, o: { headers?: Record<string, string>; body?: string } = {}): Promise<Res> {
  return new Promise((resolve, reject) => {
    const req = request({ host: '127.0.0.1', port, method, path, agent: false, headers: { host: `127.0.0.1:${port}`, ...o.headers } }, (res) => {
      let body = '';
      res.setEncoding('utf8');
      res.on('data', (c: string) => { body += c; });
      res.on('end', () => resolve({ status: res.statusCode!, headers: res.headers, body }));
    });
    req.on('error', reject);
    if (o.body !== undefined) req.write(o.body);
    req.end();
  });
}

export async function login(s: RunningService, user: string, password: string): Promise<string> {
  const res = await http(s.port, 'POST', '/login', {
    headers: { origin: s.origin, 'content-type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({ username: user, password }).toString(),
  });
  const set = (res.headers['set-cookie'] as string[] | undefined)?.[0];
  assert.ok(set, `login as ${user} failed: ${res.status} ${String(res.headers.location)}`);
  return set.split(';')[0]!;
}

// A browser's live connection: every message it got, and a way to wait for one.
export class LiveClient {
  readonly messages: Array<Record<string, any>> = [];
  closeCode: number | null = null;
  readonly ws: WebSocket;
  readonly opened: Promise<void>;

  constructor(s: RunningService, cookie: string) {
    this.ws = new WebSocket(`ws://127.0.0.1:${s.port}/api/live`, { headers: { origin: s.origin, cookie } });
    this.ws.on('message', (d) => { try { this.messages.push(JSON.parse(String(d))); } catch { /* not ours */ } });
    this.ws.on('close', (code) => { this.closeCode = code; });
    this.ws.on('error', () => { /* close follows */ });
    this.opened = new Promise((resolve, reject) => { this.ws.once('open', () => resolve()); this.ws.once('unexpected-response', (_q, r) => reject(new Error(`upgrade refused: ${r.statusCode}`))); });
  }

  frames(): Array<Record<string, any>> { return this.messages.filter((m) => m.type === 'frame'); }
  lastFrame(): Record<string, any> | undefined { return this.frames().at(-1); }
  results(): Array<Record<string, any>> { return this.messages.filter((m) => m.type === 'result'); }

  send(m: unknown): void { this.ws.send(typeof m === 'string' ? m : JSON.stringify(m)); }

  // Sends a message with a ref and waits for its result.
  async ask(m: Record<string, unknown>, timeoutMs = 5_000): Promise<Record<string, any>> {
    const ref = `t${Math.random().toString(36).slice(2, 10)}`;
    this.send({ ...m, ref });
    return waitFor(() => this.results().find((r) => r.ref === ref), timeoutMs, `result for ${JSON.stringify(m)}`);
  }

  close(): void { this.ws.close(); }
}

export async function waitFor<T>(fn: () => T | undefined | null | false, timeoutMs: number, what: string): Promise<T> {
  const start = Date.now();
  for (;;) {
    const v = fn();
    if (v) return v;
    if (Date.now() - start > timeoutMs) throw new Error(`timed out after ${timeoutMs} ms waiting for ${what}`);
    await new Promise((r) => setTimeout(r, 50));
  }
}
// Shared harness for the fake gateway tests: a fake on a ManualClock with one authenticated
// in-process client. Not a test file itself (no .test.ts suffix).
import { ManualClock } from '../src/clock.ts';
import type { CommandAck, GatewayMessage, Telemetry } from '../src/protocol.ts';
import { FakeGateway, type FakeConfig, type TestClient } from '../fake/gateway.ts';
import { DLH1 } from '../fake/dlh1.ts';

export const T0 = 1_790_000_000_000;

export interface Harness {
  clock: ManualClock;
  gw: FakeGateway;
  client: TestClient;
  advance(ms: number): void;
  command(vehicle: string, action: string, extra?: Record<string, unknown>, operator?: string): CommandAck;
  sendCommand(body: Record<string, unknown>): CommandAck | undefined;
  drive(vehicle: string, leaseId: string, seq: number, throttle: number, sentMs?: number): void;
  latest(vehicle: string): Telemetry;
  telemetry(vehicle: string): Telemetry[];
  messages<T extends GatewayMessage['type']>(type: T): Array<Extract<GatewayMessage, { type: T }>>;
  // Advance in ticks until pred holds on the vehicle's telemetry; returns the elapsed ms, or -1.
  until(vehicle: string, pred: (t: Telemetry) => boolean, maxMs: number): number;
}

export function harness(config: Partial<FakeConfig> = {}, email = '<redacted-email>'): Harness {
  const clock = new ManualClock(T0);
  const gw = new FakeGateway(clock, { seed: 7, site: DLH1, blasts: 'none', ...config });
  gw.start();
  const client = gw.connect();
  let n = 0;

  // Indexed as lines arrive: re-scanning every message on every poll is quadratic.
  const byType = new Map<string, GatewayMessage[]>();
  const byVehicle = new Map<string, Telemetry[]>();
  const acks = new Map<string, CommandAck>();
  client.onMessage((m) => {
    const list = byType.get(m.type) ?? [];
    list.push(m);
    byType.set(m.type, list);
    if (m.type === 'telemetry') {
      const v = byVehicle.get(m.vehicle_id) ?? [];
      v.push(m);
      byVehicle.set(m.vehicle_id, v);
    }
    if (m.type === 'command_ack') acks.set(m.command_id, m);
  });
  const messages = <T extends GatewayMessage['type']>(type: T) => (byType.get(type) ?? []) as Array<Extract<GatewayMessage, { type: T }>>;
  const lastAck = (id: string) => acks.get(id);
  const telemetry = (v: string) => byVehicle.get(v) ?? [];
  client.send({ type: 'auth', email });

  const h: Harness = {
    clock, gw, client,
    advance: (ms) => clock.advance(ms),
    command(vehicle, action, extra = {}, operator = 'op1') {
      const command_id = `t-${++n}`;
      client.send({ type: 'command', command_id, vehicle_id: vehicle, action, operator_id: operator, ...extra });
      const ack = lastAck(command_id);
      if (!ack) throw new Error(`no ack for ${command_id}`);
      return ack;
    },
    sendCommand(body) {
      client.send({ type: 'command', ...body });
      return typeof body.command_id === 'string' ? lastAck(body.command_id) : undefined;
    },
    drive(vehicle, leaseId, seq, throttle, sentMs) {
      client.send({ type: 'drive', vehicle_id: vehicle, lease_id: leaseId, seq, throttle, ...(sentMs === undefined ? {} : { sent_ms: sentMs }) });
    },
    latest(v) {
      const t = telemetry(v).at(-1);
      if (!t) throw new Error(`no telemetry for ${v}`);
      return t;
    },
    telemetry,
    messages,
    until(vehicle, pred, maxMs) {
      const start = clock.now();
      while (clock.now() - start <= maxMs) {
        const t = telemetry(vehicle).at(-1);
        if (t && pred(t)) return clock.now() - start;
        clock.advance(50);
      }
      return -1;
    },
  };
  return h;
}

  fleet: FleetState;
  dial: Dialer;
  email: string;
  random?: () => number; // [0, 1); injected so backoff is reproducible in tests
}

const BUSY: ReadonlySet<string> = new Set<AuthErrorReason>(['TOO_MANY_CONNECTIONS', 'SERVER_FULL']);

export class GatewayLink implements CommandTransport {
  readonly #clock: Clock;
  readonly #fleet: FleetState;
  readonly #dial: Dialer;
  readonly #email: string;
  readonly #random: () => number;
  readonly #listeners = new Set<(e: LinkEvent) => void>();
  #socket: LinkSocket | null = null;
  #gen = 0;
  #status: LinkStatus;
  #retryTimer: TimerHandle | null = null;
  #helloTimer: TimerHandle | null = null;
  #watchdog: TimerHandle | null = null;
  #busy = false;

  constructor(o: LinkOptions) {
    this.#clock = o.clock;
    this.#fleet = o.fleet;
    this.#dial = o.dial;
    this.#email = o.email;
    this.#random = o.random ?? Math.random;
    this.#status = { state: 'idle', sinceMs: o.clock.now(), reason: 'not started', failures: 0, nextAttemptAtMs: null, dials: 0, lastHeartbeatMs: null, authError: null };
  }

  subscribe(fn: (e: LinkEvent) => void): () => void {
    this.#listeners.add(fn);
    return () => this.#listeners.delete(fn);
  }

  status(): LinkStatus {
    return { ...this.#status };
  }

  isUp(): boolean {
    return this.#status.state === 'up';
  }

  // Starts the one connection. Calling it again while running does nothing (L6.4).
  start(): void {
    if (this.#status.state !== 'idle' && this.#status.state !== 'stopped') return;
    this.#status.authError = null;
    this.#status.failures = 0;
    this.#connect();
  }

  stop(): void {
    this.#clearTimers();
    this.#dropSocket();
    this.#set('stopped', 'stopped');
  }

  // Commands, from the registry only.
  send(msg: CommandMessage): boolean {
    return this.#write(msg);
  }

  // Drive messages, from the drive relay (a later task). Never queued, never re-sent: a message
  // that can't go now is dropped, and silence lets the deadman stop the truck.
  sendDrive(msg: Extract<ClientMessage, { type: 'drive' }>): boolean {
    return this.#write(msg);
  }

  #write(msg: ClientMessage): boolean {
    if (!this.isUp() || !this.#socket) return false;
    const line = JSON.stringify(msg);
    if (Buffer.byteLength(line, 'utf8') > MAX_LINE_BYTES) return false;
    this.#socket.write(line);
    return true;
  }

  // ---- connection lifecycle ----

  #connect(): void {
    this.#retryTimer = null;
    if (this.#socket) return; // one connection at a time, always
    const gen = ++this.#gen;
    this.#status.dials++;
    this.#status.nextAttemptAtMs = null;
    this.#set('connecting', `connecting (attempt ${this.#status.failures + 1})`);
    const socket = this.#dial({
      onLine: (line) => { if (gen === this.#gen) this.#line(line); },
      onClose: (reason) => { if (gen === this.#gen) this.#closed(reason); },
    });
    if (gen !== this.#gen) { socket.close(); return; } // closed while dialling
    this.#socket = socket;
    this.#helloTimer = this.#clock.setTimeout(() => {
      this.#helloTimer = null;
      if (gen === this.#gen && this.#status.state === 'connecting') this.#fail(`no hello within ${PARAMS.helloTimeout.value / 1000} s of logging in`);
    }, PARAMS.helloTimeout.value);
    socket.write(JSON.stringify({ type: 'auth', email: this.#email }));
  }

  #line(line: string): void {
    const p = parseLine(line);
    if (!p.ok) { this.#fleet.ingestLine(line); return; } // counted as data quality there
    const m = p.msg;
    if (m.type === 'auth_error') { this.#authError(m.reason); return; }
    if (m.type === 'hello') { this.#hello(m as unknown as Hello); return; }
    this.#fleet.ingest(m);
    if (m.type === 'heartbeat') this.#heartbeat();
    this.#emit({ type: 'message', msg: m });
  }

  #hello(h: Hello): void {
    if (this.#helloTimer) { this.#clock.clearTimeout(this.#helloTimer); this.#helloTimer = null; }
    this.#fleet.newConnection();
    this.#fleet.ingest(h);
    this.#status.failures = 0;
    this.#busy = false;
    this.#heartbeat();
    this.#set('up', 'connected');
    this.#fleet.setLink(true, 'connected');
    this.#emit({ type: 'up', hello: h });
  }

  #heartbeat(): void {
    this.#status.lastHeartbeatMs = this.#clock.now();
    if (this.#watchdog) this.#clock.clearTimeout(this.#watchdog);
    const gen = this.#gen;
    this.#watchdog = this.#clock.setTimeout(() => {
      this.#watchdog = null;
      if (gen === this.#gen && this.#status.state === 'up') {
        this.#fail(`no heartbeat for ${PARAMS.linkDownAfter.value / 1000} s`);
      }
    }, PARAMS.linkDownAfter.value);
  }

  #authError(reason: unknown): void {
    const r = (AUTH_ERRORS as readonly unknown[]).includes(reason) ? (reason as AuthErrorReason) : null;
    this.#status.authError = r;
    if (r !== null && BUSY.has(r)) {
      this.#busy = true;
      this.#fail(`the gateway refused the login: ${r === 'SERVER_FULL' ? 'it is full' : 'too many connections to this site'}; trying again`);
      return;
    }
    // Anything else will not fix itself by retrying: stop and say so.
    this.#clearTimers();
    this.#dropSocket();
    const message = `The gateway refused the login (${String(reason)}). The site link is stopped until someone fixes the configuration.`;
    this.#set('stopped', message);
    this.#fleet.setLink(false, message);
    this.#emit({ type: 'alarm', message });
  }

  #closed(reason: string): void {
    this.#socket = null;
    if (this.#status.state === 'connecting') {
      this.#fail(`login accepted, then closed before hello (site link outage): ${reason}`);
    } else {
      this.#fail(reason);
    }
  }

  // Lose the connection and schedule the next attempt.
  #fail(reason: string): void {
    const wasUp = this.#status.state === 'up';
    this.#clearTimers();
    this.#dropSocket();
    if (this.#status.state === 'stopped') return;
    const delay = this.#backoff(this.#status.failures);
    this.#status.failures++;
    this.#status.nextAttemptAtMs = this.#clock.now() + delay;
    this.#set('down', reason);
    this.#fleet.setLink(false, `site link down: ${reason}`);
    if (wasUp) this.#emit({ type: 'down', reason });
    this.#retryTimer = this.#clock.setTimeout(() => this.#connect(), delay);
  }

  // Exponential from the base, capped, with "equal jitter": between half and all of the step, so
  // two services never synchronise and a retry is never instant.
  #backoff(failures: number): number {
    const base = this.#busy ? PARAMS.linkBackoffBusyBase.value : PARAMS.linkBackoffBase.value;
    const cap = this.#busy ? PARAMS.linkBackoffBusyMax.value : PARAMS.linkBackoffMax.value;
    const step = Math.min(cap, base * 2 ** Math.min(failures, 20));
    return Math.round(step / 2 + this.#random() * (step / 2));
  }

  #dropSocket(): void {
    this.#gen++;
    const s = this.#socket;
    this.#socket = null;
    s?.close();
  }

  #clearTimers(): void {
    for (const t of [this.#retryTimer, this.#helloTimer, this.#watchdog]) if (t) this.#clock.clearTimeout(t);
    this.#retryTimer = this.#helloTimer = this.#watchdog = null;
  }

  #set(state: LinkState, reason: string): void {
    if (this.#status.state !== state) this.#status.sinceMs = this.#clock.now();
    this.#status.state = state;
    this.#status.reason = reason;
    this.#emit({ type: 'status', status: this.status() });
  }

  #emit(e: LinkEvent): void {
    for (const fn of this.#listeners) fn(e);
  }
}

// The registry hears everything the link hears, after fleet state has taken it in.
export function attachRegistry(link: GatewayLink, registry: CommandRegistry): () => void {
  return link.subscribe((e) => {
    if (e.type === 'up') registry.linkUp(e.hello);
    else if (e.type === 'down') registry.linkDown(e.reason);
    else if (e.type === 'message') registry.message(e.msg);
  });
}
