206	      const pos = this.#mod(init ? init.positionM : (i + 0.5 + jitter) * (site.loopLengthM / n));
207	      return {
208	        id, pos, speed: 0, dir: 1, state: init?.state ?? 'TRAMMING', task: null,
209	        soc: init?.socPct ?? socDefault, loaded: init?.loaded ?? this.#loadedAt(pos), faults: [],
210	        drainFactor: init?.drainFactor ?? 1, work: null, move: null, queued: null, pending: [],
211	        lease: null, throttle: 0, deadman: false, lastDriveSeq: null, lastDriveSentMs: null,
212	        seq: 0, phase: i % this.#telemetryEvery, deviceOffsetMs: 0,
213	      } satisfies Truck;
214	    });
215	    this.#byId = new Map(this.#trucks.map((t) => [t.id, t]));
216	
217	    this.#randomBlasts = opts.blasts === 'random';
218	    if (opts.blasts === 'random') {
219	      this.#nextRandomBlastAt = this.startMs + this.#onTick(this.#rngBlasts.uniform(this.#b.firstBlastMinMs, this.#b.firstBlastMaxMs));
220	    } else if (Array.isArray(opts.blasts)) {
221	      for (const s of opts.blasts) {
222	        if (!this.#zones.has(s.zoneId)) throw new Error(`blast zone ${s.zoneId} is not on the site`);
223	        const closingAt = this.startMs + s.atMs;
224	        const effectiveAt = closingAt + (s.noticeMs ?? this.#config.noticeMs);
225	        this.#logBlast(s.zoneId, closingAt, s.cancelAfterMs !== undefined);
226	        this.#blasts.push({
227	          zoneId: s.zoneId, closingAt, effectiveAt, reopenAt: effectiveAt + s.closedForMs,
228	          cancelAt: s.cancelAfterMs === undefined ? null : closingAt + s.cancelAfterMs, stage: 'scheduled',
229	        });
230	      }
231	    }
232	  }
