343	  // A weak pack: drains `factor` times faster, and starts with just enough charge to die loaded,
344	  // `fraction` of the way from the load point to the dump point, as both live weak packs did (in the
345	  // incline). Charging is ignored in the sum; a pack this weak is still above the charge threshold
346	  // when it passes the bay. Returns where it should die.
347	  weakPack(id: string, factor: number, fraction: number): { socPct: number; diesAtM: number } {
348	    const t = this.#byId.get(id);
349	    if (!t) throw new Error(`no truck ${id}`);
350	    const load = this.#points.LOADING[0], dump = this.#points.DUMPING[0];
351	    t.drainFactor = factor;
352	    if (load === undefined || dump === undefined) return { socPct: t.soc, diesAtM: NaN };
353	    const stretch = this.#mod(dump - load);
354	    const target = this.#mod(load + fraction * stretch);
355	    const empty = (m: number) => m * (this.#b.drainEmptyPctPerKm / 1000) * factor;
356	    const loaded = (m: number) => m * (this.#b.drainLoadedPctPerKm / 1000) * factor;
357	    const toLoad = this.#mod(load - t.pos), toTarget = this.#mod(target - t.pos), toDump = this.#mod(dump - t.pos);
358	    let need: number;
359	    if (!t.loaded) need = empty(toLoad) + loaded(fraction * stretch);
360	    else if (toTarget <= toDump) need = loaded(toTarget);
361	    else need = loaded(toDump) + empty(this.#mod(load - dump)) + loaded(fraction * stretch);
362	    t.soc = Math.min(100, need);
363	    this.#log.start(this.startMs, id, 'weak_pack', { factor, startSocPct: t.soc, diesAtM: target });
364	    return { socPct: t.soc, diesAtM: target };
365	  }
