371	  // ---- commands (already validated by the gateway: id, operator, vehicle, action) ----
372	
373	  command(c: ModelCommand): AckResult {
374	    const t = this.#byId.get(c.vehicle_id);
375	    if (!t) return reject('UNKNOWN_VEHICLE');
376	    const now = this.#clock.now();
377	
378	    if (c.action === 'ESTOP') {
379	      this.#estop(t, c.operator_id, now);
380	      return ACCEPTED;
381	    }
382	    if (t.state === 'ESTOPPED') {
383	      if (c.action !== 'CLEAR_ESTOP') return reject('ESTOP_ACTIVE');
384	      t.state = t.faults.length > 0 ? 'FAULT' : 'HOLDING';
385	      return ACCEPTED;
386	    }
387	    if (t.faults.length > 0 && !(this.#limpOk(t) && (c.action === 'TAKE_CONTROL' || c.action === 'RELEASE_CONTROL'))) {
388	      return reject('INTERLOCK_ACTIVE');
389	    }
390	    switch (c.action) {
391	      case 'CLEAR_ESTOP': return reject('INVALID_STATE');
392	      case 'TAKE_CONTROL': return this.#takeControl(t, c.operator_id, c.force === true, now);
393	      case 'RELEASE_CONTROL': return this.#release(t, c.lease_id, now);
394	      default: break;
395	    }
396	    if (t.lease) return reject('LEASE_HELD', { holder: t.lease.operator });
397	    return this.#supervisory(t, c.action, now, c.ignored === true ? c.command_id : null);
398	  }
399	
400	  // `ignoredId` set: the ACCEPTED-then-ignored injector. The command is accepted exactly as it would
401	  // be, and then nothing happens (fixture accepted-then-ignored-resume).
402	  #supervisory(t: Truck, action: Supervisory, now: number, ignoredId: string | null): AckResult {
403	    const ignore = (): AckResult => {
404	      this.#log.event(now, t.id, 'accepted_ignored', { command_id: ignoredId, action, state: t.state });
405	      return ACCEPTED;
406	    };
407	    if (action === 'RESUME') {
408	      // §5: RESUME cancels a queued command instead, at once (the controller has it in its queue).
409	      // Guessed: untested live (re-probe Q3's truck had finished loading before the RESUME came).
410	      if (t.queued) { if (ignoredId !== null) return ignore(); t.queued = null; return ACCEPTED; }
411	      // Seen once live (re-probe Q3, fixture resume-during-pending-hold): a command still within its
412	      // 1-6 s delay cannot be called back. RESUME is INVALID_STATE and the pending one takes effect.
413	      if (t.pending.length > 0) return reject('INVALID_STATE');
414	      if (t.state === 'HOLDING' || t.state === 'IDLE') {
415	        if (ignoredId !== null) return ignore();
416	        this.#schedule(t, { action, zoneId: null }, now);
417	        return ACCEPTED;
418	      }
419	      return reject('INVALID_STATE');
420	    }
421	    let zoneId: string | null = null;
422	    if (action === 'EXIT_ZONE') {
423	      const z = this.site.zoneAt(t.pos);
424	      if (!z || z.kinds.includes('bay')) return reject('INVALID_STATE');
425	      zoneId = z.zoneId; // §5: the zone it was in when the command was accepted
426	    }
427	    if (action === 'RETURN_TO_BAY' && this.#points.CHARGING.length === 0) return reject('INVALID_STATE');
428	    if (ignoredId !== null) return ignore();
429	    // Every supervisory command reaches the controller after its 1-6 s delay; one that arrives while
430	    // the truck is loading, dumping or charging is queued then (#apply). Re-probe Q3: a HOLD sent in
431	    // the last second of loading took effect 5.6 s after sending, not when loading ended.
432	    this.#schedule(t, { action, zoneId }, now);
433	    return ACCEPTED;
434	  }
435	
436	  // Supervisory commands take effect 1-6 s after acceptance, in the order they were accepted.
437	  #schedule(t: Truck, e: Omit<Effect, 'due'>, now: number): void {
438	    const delay = Math.round(this.#rngCommands.uniform(this.#b.commandDelayMinMs, this.#b.commandDelayMaxMs));
439	    const due = Math.max(now + delay, t.pending.at(-1)?.due ?? 0);
440	    t.pending.push({ ...e, due });
441	  }
442	
443	  #apply(t: Truck, e: Effect, now: number): void {
444	    if (t.state === 'MANUAL' || t.state === 'ESTOPPED' || t.state === 'FAULT') return;
445	    if (isWork(t.state)) {
446	      if (e.action !== 'RESUME') t.queued = e; // one at a time: a newer one replaces the older (guessed: untested live)
447	      return;
448	    }
449	    switch (e.action) {
450	      case 'HOLD':
451	        this.#hold(t);
452	        return;
453	      case 'RESUME':
454	        if (t.state === 'HOLDING' || t.state === 'IDLE') { t.state = 'TRAMMING'; t.task = null; t.move = null; }
455	        return;
456	      case 'EXIT_ZONE': {
457	        const z = this.site.zoneAt(t.pos);
458	        if (!z || z.zoneId !== e.zoneId) { this.#hold(t); return; } // already left: just hold
459	        t.state = 'TRAMMING';
460	        t.task = 'EXIT_ZONE';
461	        t.move = this.#exitMove(t.pos, z);
462	        return;
463	      }
464	      case 'RETURN_TO_BAY':
465	        t.state = 'TRAMMING';
466	        t.task = 'RETURN_TO_BAY';
467	        t.move = this.#bayMove(t.pos);
468	        if (t.move.remaining <= EPS) this.#arrive(t);
469	        return;
470	    }
471	  }
472	
473	  #hold(t: Truck): void {
474	    t.state = 'HOLDING';
475	    t.task = null;
476	    t.move = null;
477	    t.speed = 0;
478	    t.dir = 1;
479	  }
480	
481	  // Nearest boundary of the zone, forward or reverse, to stop a little outside it.
482	  #exitMove(pos: number, z: Zone): Move {
483	    const stop = this.#b.exitStopOutsideM;
484	    for (const r of z.ranges) {
485	      const back = this.#mod(pos - r.startM);
486	      if (back >= r.lengthM) continue;
487	      const fwd = r.lengthM - back;
488	      return fwd <= back
489	        ? { dir: 1, remaining: fwd + stop, target: this.#mod(pos + fwd + stop) }
490	        : { dir: -1, remaining: back + stop, target: this.#mod(pos - back - stop) };
491	    }
492	    return { dir: 1, remaining: 0, target: pos };
493	  }
494	
495	  // To the charging point at the end of the nearest bay segment, by the shorter direction.
496	  #bayMove(pos: number): Move {
497	    let best: Move | null = null;
498	    for (const p of this.#points.CHARGING) {
499	      const fwd = this.#mod(p - pos), rev = this.#mod(pos - p);
500	      const m: Move = rev < fwd ? { dir: -1, remaining: rev, target: p } : { dir: 1, remaining: fwd, target: p };
501	      if (!best || m.remaining < best.remaining) best = m;
502	    }
503	    return best!;
504	  }
505	
506	  // ---- leases (§6) ----
507	
508	  #takeControl(t: Truck, operator: string, force: boolean, now: number): AckResult {
509	    if (t.lease) {
510	      if (t.lease.operator === operator) return this.#leaseAck(t.lease); // §6.5: the existing lease
511	      if (!force) return reject('LEASE_HELD', { holder: t.lease.operator });
512	      this.#emitLease(t, 'REVOKED', t.lease, now, { reason: 'FORCED_TAKEOVER', by_operator: operator });
513	      t.lease = null;
514	    }
515	    const lease: Lease = { id: `L-${String(++this.#leaseCount).padStart(5, '0')}-${this.#rngLeases.hex(4)}`, operator, lastFresh: now };
516	    this.#stopAll(t); // interrupts loading, dumping or charging, and drops queued and pending commands
517	    t.lease = lease;
518	    t.state = 'MANUAL';
519	    t.throttle = 0;
520	    t.deadman = false;
521	    t.lastDriveSeq = 0; // as seen live: 0 after the grant, before any drive message
522	    t.lastDriveSentMs = null;
523	    this.#emitLease(t, 'GRANTED', lease, now, { forced: force });
524	    return this.#leaseAck(lease);
525	  }
526	
527	  #leaseAck(lease: Lease): AckResult {
528	    return { status: 'ACCEPTED', lease_id: lease.id, lease_idle_timeout_ms: this.#b.leaseIdleTimeoutMs, deadman_ms: this.#b.deadmanMs };
529	  }
530	
531	  #release(t: Truck, leaseId: unknown, now: number): AckResult {
532	    if (!t.lease || leaseId !== t.lease.id) return reject('NOT_LEASE_HOLDER');
533	    this.#emitLease(t, 'RELEASED', t.lease, now, {});
534	    this.#endLease(t);
535	    return ACCEPTED;
536	  }
537	
538	  #endLease(t: Truck): void {
539	    t.lease = null;
540	    t.throttle = 0;
541	    t.deadman = false;
542	    t.lastDriveSeq = null;
543	    t.lastDriveSentMs = null;
544	    t.speed = 0;
545	    t.dir = 1;
546	    t.state = t.faults.length > 0 ? 'FAULT' : 'HOLDING'; // §6.4, §6.6: holds, or back to FAULT
547	  }
548	
549	  #estop(t: Truck, operator: string, now: number): void {
550	    if (t.lease) {
551	      this.#emitLease(t, 'REVOKED', t.lease, now, { reason: 'ESTOP', by_operator: operator });
552	      this.#endLease(t);
553	    }
554	    this.#stopAll(t);
555	    t.state = 'ESTOPPED';
556	  }
557	
558	  #emitLease(t: Truck, event: LeaseEvent['event'], lease: Lease, now: number, extra: Partial<LeaseEvent>): void {
559	    this.#emit({
560	      type: 'lease_event', vehicle_id: t.id, event, lease_id: lease.id, operator_id: lease.operator,
561	      ...(extra.reason !== undefined ? { reason: extra.reason } : {}),
562	      ...(extra.by_operator !== undefined ? { by_operator: extra.by_operator } : {}),
563	      server_time_ms: now,
564	      ...(extra.forced !== undefined ? { forced: extra.forced } : {}),
565	    });
566	  }
567	
568	  drive(msg: Record<string, unknown>): void {
569	    const now = this.#clock.now();
570	    const vehicle = typeof msg.vehicle_id === 'string' ? msg.vehicle_id : String(msg.vehicle_id);
571	    const leaseId = typeof msg.lease_id === 'string' ? msg.lease_id : null;
572	    const t = this.#byId.get(vehicle);
573	    if (!t) return this.#driveRejected(vehicle, leaseId, 'UNKNOWN_VEHICLE', now);
574	    if (!t.lease || leaseId !== t.lease.id) return this.#driveRejected(vehicle, leaseId, 'NO_ACTIVE_LEASE', now);
575	    const throttle = msg.throttle;
576	    if (typeof throttle !== 'number' || !Number.isFinite(throttle) || throttle < -1 || throttle > 1) {
577	      return this.#driveRejected(vehicle, leaseId, 'BAD_THROTTLE', now);
578	    }
579	    const seq = msg.seq;
580	    if (typeof seq !== 'number' || !Number.isInteger(seq) || seq < 1) return this.#driveRejected(vehicle, leaseId, 'BAD_SEQ', now);
581	    if (seq <= (t.lastDriveSeq ?? 0)) return; // §6.2: not higher than the last applied: discarded
582	    t.throttle = throttle;
583	    t.lastDriveSeq = seq;
584	    t.lastDriveSentMs = typeof msg.sent_ms === 'number' ? msg.sent_ms : null;
585	    t.lease.lastFresh = now;
586	    t.deadman = false;
587	  }
588	
589	  #driveRejected(vehicle: string, leaseId: string | null, reason: 'NO_ACTIVE_LEASE' | 'BAD_THROTTLE' | 'BAD_SEQ' | 'UNKNOWN_VEHICLE', now: number): void {
590	    const key = `${vehicle}\u0000${reason}`;
591	    const last = this.#driveRejectedAt.get(key);
592	    if (last !== undefined && now - last < this.#b.driveRejectIntervalMs) return;
593	    this.#driveRejectedAt.set(key, now);
594	    this.#emit({ type: 'drive_rejected', vehicle_id: vehicle, lease_id: leaseId as string, reason, server_time_ms: now });
595	  }
596	
597	  // ---- the tick ----
598	
599	  #tick = (): void => {
600	    const now = this.#clock.now();
601	    const dt = (now - this.#lastTick) / 1000;
602	    this.#lastTick = now;
603	    this.#runBlasts(now);
604	    for (const t of this.#trucks) {
605	      this.#leaseTimers(t, now);
606	      while (t.pending.length > 0 && t.pending[0]!.due <= now) this.#apply(t, t.pending.shift()!, now);
607	      this.#advance(t, dt, now);
608	    }
609	    this.#ticks++;
610	    for (const t of this.#trucks) {
611	      if ((this.#ticks + t.phase) % this.#telemetryEvery !== 0) continue;
612	      const f = this.#telemetryFaults;
613	      if (f?.silent(t.id, now)) continue; // a silent truck sends nothing and its seq does not advance
614	      const m = this.#telemetry(t, now);
615	      if (!f) { t.seq = m.seq; this.#emit(m); continue; }
616	      const shaped = f.shape(m, { speedMps: t.speed, state: t.state, positionM: t.pos }, now);
617	      t.seq = typeof shaped.seq === 'number' ? shaped.seq : m.seq;
618	      this.#emit(shaped as unknown as GatewayMessage);
619	    }
620	    if (now >= this.#nextHeartbeat) {
621	      this.#emit({ type: 'heartbeat', server_time_ms: now });
622	      this.#nextHeartbeat += this.#b.heartbeatPeriodMs;
623	    }
624	    this.#timer = this.#clock.setTimeout(this.#tick, this.#b.tickMs);
625	  };
626	
627	  #leaseTimers(t: Truck, now: number): void {
628	    if (!t.lease) return;
629	    const idle = now - t.lease.lastFresh;
630	    if (idle >= this.#b.leaseIdleTimeoutMs) {
631	      this.#emitLease(t, 'EXPIRED', t.lease, now, { reason: 'NO_DRIVE_INPUT' });
632	      this.#endLease(t);
633	    } else if (idle >= this.#b.deadmanMs) {
634	      t.deadman = true;
635	    }
636	  }
637	
638	  #advance(t: Truck, dt: number, now: number): void {
639	    switch (t.state) {
640	      case 'LOADING':
641	      case 'DUMPING':
642	        t.speed = 0;
643	        if (t.work!.until !== null && now >= t.work!.until) this.#finishWork(t, now);
644	        return;
645	      case 'CHARGING':
646	        t.speed = 0;
647	        t.soc = Math.min(this.#b.chargeToPct, t.soc + this.#b.chargeRatePctPerS * dt);
648	        if (t.soc >= this.#b.chargeToPct) this.#finishWork(t, now);
649	        return;
650	      case 'TRAMMING':
651	        if (t.move) this.#moveTask(t, dt, now);
652	        else this.#moveDuty(t, dt, now);
653	        return;
654	      case 'MANUAL':
655	        this.#moveManual(t, dt, now);
656	        return;
657	      default:
658	        t.speed = 0;
659	    }
660	  }
661	
662	  // The autonomous duty cycle: forward, stopping to load, dump or charge where the route says.
663	  #moveDuty(t: Truck, dt: number, now: number): void {
664	    t.speed = t.loaded ? this.#b.autoSpeedLoaded : this.#b.autoSpeedEmpty;
665	    t.dir = 1;
666	    const d = t.speed * dt;
667	    const kinds: Array<Work['kind']> = [t.loaded ? 'DUMPING' : 'LOADING'];
668	    if (t.soc < this.#b.chargeBelowPct) kinds.push('CHARGING');
669	    let s: { dist: number; point: number; kind: Work['kind'] } | null = null;
670	    for (const kind of kinds) {
671	      for (const p of this.#points[kind]) {
672	        const dist = this.#mod(p - t.pos);
673	        if (dist > EPS && dist <= d + EPS && (!s || dist < s.dist)) s = { dist, point: p, kind };
674	      }
675	    }
676	    if (!s) { this.#travel(t, d, now); return; }
677	    if (!this.#travel(t, s.dist, now)) return;
678	    t.pos = s.point;
679	    t.speed = 0;
680	    t.state = s.kind;
681	    const until = s.kind === 'LOADING' ? now + this.#b.loadMs : s.kind === 'DUMPING' ? now + this.#b.dumpMs : null;
682	    t.work = { kind: s.kind, until, then: 'TRAMMING' };
683	  }
684	
685	  // EXIT_ZONE and RETURN_TO_BAY: to a target, forward or reverse, ignoring the duty cycle.
686	  #moveTask(t: Truck, dt: number, now: number): void {
687	    const m = t.move!;
688	    t.dir = m.dir;
689	    t.speed = m.dir > 0
690	      ? (t.loaded ? this.#b.autoSpeedLoaded : this.#b.autoSpeedEmpty)
691	      : (t.loaded ? this.#b.reverseSpeedLoaded : this.#b.reverseSpeedEmpty);
692	    const d = Math.min(t.speed * dt, m.remaining);
693	    if (!this.#travel(t, d * m.dir, now)) return;
694	    m.remaining -= d;
695	    if (m.remaining <= EPS) {
696	      t.pos = m.target;
697	      this.#arrive(t);
698	    }
699	  }
700	
701	  #arrive(t: Truck): void {
702	    t.move = null;
703	    t.speed = 0;
704	    t.dir = 1;
705	    if (t.task === 'EXIT_ZONE') { t.state = 'HOLDING'; t.task = null; return; }
706	    if (t.soc < this.#b.chargeToPct) {
707	      t.state = 'CHARGING';
708	      t.work = { kind: 'CHARGING', until: null, then: 'IDLE' }; // task stays RETURN_TO_BAY until parked
709	    } else {
710	      t.state = 'IDLE';
711	      t.task = null;
712	    }
713	  }
714	
715	  #finishWork(t: Truck, now: number): void {
716	    const w = t.work!;
717	    t.work = null;
718	    if (w.kind === 'LOADING') t.loaded = true;
719	    if (w.kind === 'DUMPING') t.loaded = false;
720	    if (w.then === 'IDLE') { t.state = 'IDLE'; t.task = null; } else t.state = 'TRAMMING';
721	    if (t.queued) {
722	      const q = t.queued;
723	      t.queued = null;
724	      // Re-probe Q1 (fixture queued-hold-dropped): a queued HOLD was ACCEPTED and never carried out.
725	      // The queued-drop injector does this at a rate; the L0.P pessimistic version always has it on.
726	      const drawn = this.#rngQueue.chance(this.#b.queuedDropProbability);
727	      if ((this.#b.queueing === 'pessimistic' || this.#queuedDrops) && drawn) {
728	        this.#log.event(now, t.id, 'queued_dropped', { action: q.action });
729	        return;
730	      }
731	      this.#apply(t, q, now);
732	    }
733	  }
734	
735	  // Moves only on fresh input: the deadman (set in #leaseTimers) stops it, and nothing re-applies
736	  // an old throttle once it has tripped.
737	  #moveManual(t: Truck, dt: number, now: number): void {
738	    if (t.deadman || t.throttle === 0) { t.speed = 0; return; }
739	    const max = t.faults.length > 0 ? this.#b.limpSpeed : t.loaded ? this.#b.manualSpeedLoaded : this.#b.manualSpeedEmpty;
740	    t.speed = Math.abs(t.throttle) * max;
741	    t.dir = t.throttle > 0 ? 1 : -1;
742	    this.#travel(t, t.speed * dt * t.dir, now);
743	  }
744	
745	  // Moves along the loop, paying for it in charge. Returns false if the pack ran out on the way,
746	  // in which case the truck stops exactly where it did.
747	  #travel(t: Truck, signedM: number, now: number): boolean {
748	    const dist = Math.abs(signedM);
749	    if (dist === 0) return true;
750	    const perM = ((t.loaded ? this.#b.drainLoadedPctPerKm : this.#b.drainEmptyPctPerKm) / 1000) * t.drainFactor;
751	    const cost = dist * perM;
752	    if (cost >= t.soc) {
753	      t.pos = this.#mod(t.pos + Math.sign(signedM) * (t.soc / perM));
754	      t.soc = 0;
755	      this.#fault(t, this.#b.depletedFault, now);
756	      return false;
757	    }
758	    t.pos = this.#mod(t.pos + signedM);
759	    t.soc -= cost;
760	    return true;
761	  }
762	
763	  #stopAll(t: Truck): void {
764	    t.speed = 0;
765	    t.dir = 1;
766	    t.work = null;
767	    t.move = null;
768	    t.task = null;
769	    t.queued = null;
770	    t.pending = [];
771	  }
772	
773	  // ---- blasts ----
774	
775	  #runBlasts(now: number): void {
776	    while (this.#randomBlasts && now >= this.#nextRandomBlastAt) {
777	      this.#scheduleRandomBlast(this.#nextRandomBlastAt);
778	      this.#nextRandomBlastAt += this.#onTick(this.#rngBlasts.uniform(this.#b.blastSpacingMinMs, this.#b.blastSpacingMaxMs));
779	    }
780	    for (const b of this.#blasts) {
781	      if (b.stage === 'scheduled' && now >= b.closingAt) {
782	        this.#setZone(b.zoneId, 'CLOSING', b.effectiveAt, 'BLAST_WINDOW', now);
783	        b.stage = 'closing';
784	      }
785	      if (b.stage === 'closing') {
786	        if (b.cancelAt !== null && now >= b.cancelAt) {
787	          this.#setZone(b.zoneId, 'OPEN', now, 'CANCELLED', now);
788	          b.stage = 'done';
789	        } else if (now >= b.effectiveAt) {
790	          this.#setZone(b.zoneId, 'CLOSED', now, 'BLAST_WINDOW', now);
791	          b.stage = 'closed';
792	        }
793	      }
794	      if (b.stage === 'closed' && now >= b.reopenAt) {
795	        this.#setZone(b.zoneId, 'OPEN', now, 'CLEARED', now);
796	        b.stage = 'done';
797	      }
798	    }
799	    this.#blasts = this.#blasts.filter((b) => b.stage !== 'done');
800	  }
801	
802	  #scheduleRandomBlast(at: number): void {
803	    const r = this.#rngBlasts;
804	    const busy = new Set(this.#blasts.map((b) => b.zoneId));
805	    const candidates = this.site.zones
806	      .filter((z) => this.#b.blastBay || !z.kinds.includes('bay'))
807	      .map((z) => z.zoneId)
808	      .filter((id) => !busy.has(id));
809	    const add = (zoneId: string, closingAt: number) => {
810	      const effectiveAt = closingAt + this.#config.noticeMs;
811	      const cancel = r.chance(this.#b.cancelProbability);
812	      const cancelAt = closingAt + this.#onTick(r.uniform(0.1, 0.9) * this.#config.noticeMs);
813	      this.#logBlast(zoneId, closingAt, cancel);
814	      this.#blasts.push({
815	        zoneId, closingAt, effectiveAt, reopenAt: effectiveAt + this.#onTick(r.uniform(this.#b.closedMinMs, this.#b.closedMaxMs)),
816	        cancelAt: cancel ? cancelAt : null, stage: 'scheduled',
817	      });
818	    };
819	    if (candidates.length === 0) return;
820	    const first = r.pick(candidates);
821	    add(first, at);
822	    const rest = candidates.filter((id) => id !== first);
823	    if (rest.length > 0 && r.chance(this.#b.secondZoneProbability)) add(r.pick(rest), at + this.#onTick(this.#b.secondZoneOffsetMs));
824	  }
825	
826	  // Blasts are scheduled, not faults, but the unusual ones are what L0.F switches on: record them.
827	  #logBlast(zoneId: string, closingAt: number, cancelled: boolean): void {
828	    const zone = this.site.zones.find((z) => z.zoneId === zoneId);
829	    if (zone?.kinds.includes('bay')) this.#log.event(closingAt, null, 'bay_closing', { zoneId });
830	    if (cancelled) this.#log.event(closingAt, null, 'cancelled_blast', { zoneId });
831	    const other = this.#blasts.find((b) => b.zoneId !== zoneId && b.stage !== 'done' && b.closingAt <= closingAt && closingAt < (b.cancelAt ?? b.reopenAt));
832	    if (other) this.#log.event(closingAt, null, 'two_zones', { zoneId, alsoClosing: other.zoneId });
833	  }
834	
835	  #setZone(zoneId: string, status: ZoneState['status'], effectiveAt: number, reason: string, now: number): void {
836	    this.#zones.set(zoneId, { zone_id: zoneId, status, effective_at_ms: effectiveAt, reason });
837	    this.#emit({ type: 'zone_event', zone_id: zoneId, status, reason, effective_at_ms: effectiveAt, server_time_ms: now });
838	  }
839	
840	  // ---- telemetry ----
841	
842	  #telemetry(t: Truck, now: number): Telemetry {
843	    const { seg, offset } = this.#locate(t.pos);
844	    return {
845	      type: 'telemetry', vehicle_id: t.id, seq: t.seq + 1, t_device_ms: now + t.deviceOffsetMs, state: t.state, task: t.task,
846	      soc_pct: round2(t.soc), speed_mps: round2(t.speed), direction: this.#direction(t), segment_id: seg.segmentId,
847	      zone_id: seg.zoneId, offset_m: offset, payload_kg: t.loaded ? this.#b.payloadKg : 0, faults: [...t.faults],
848	      control: {
849	        mode: t.lease ? 'MANUAL' : 'AUTO', operator_id: t.lease?.operator ?? null, deadman: t.deadman,
850	        last_drive_seq: t.lastDriveSeq, last_drive_sent_ms: t.lastDriveSentMs,
851	      },
852	    };
853	  }
854	
855	  #direction(t: Truck): 'FWD' | 'REV' {
856	    return t.speed > 0 && t.dir < 0 ? 'REV' : 'FWD';
857	  }
858	
859	  // ---- geometry ----
860	
861	  #mod(x: number): number {
862	    const l = this.site.loopLengthM;
863	    const m = ((x % l) + l) % l;
864	    return m >= l ? 0 : m;
865	  }
866	
867	  // The segment holding a position, and the offset into it (rounded as the live site reports it,
868	  // and never rounded up onto the next segment's start).
869	  #locate(pos: number): { seg: Segment; offset: number } {
870	    const p = this.#mod(pos);
871	    let seg = this.#segments[0]!;
872	    for (const s of this.#segments) if (s.startM <= p + EPS) seg = s;
873	    const raw = Math.max(0, p - seg.startM);
874	    let offset = round2(raw);
875	    if (offset >= seg.lengthM) offset = Math.floor((seg.lengthM - 0.005) * 100) / 100;
876	    return { seg, offset };
877	  }
878	
879	  #loadedAt(pos: number): boolean {
880	    const load = this.#points.LOADING[0], dump = this.#points.DUMPING[0];
881	    if (load === undefined || dump === undefined) return false;
882	    return this.#mod(pos - load) < this.#mod(dump - load);
883	  }
884	
885	  // Round a duration to whole ticks, so scheduled events land exactly on a tick.
886	  #onTick(ms: number): number {
887	    return Math.round(ms / this.#b.tickMs) * this.#b.tickMs;
888	  }
889	}
890	
891	const ACCEPTED: AckResult = Object.freeze({ status: 'ACCEPTED' }) as AckResult;
892	
893	function reject(reason: RejectReason, extra: { holder?: string } = {}): AckResult {
894	  return { status: 'REJECTED', reason, ...extra };
895	}
