1	// Milestone 2's fault injectors (TESTING.md L0.F): which ones are on, which truck, when, and the truth
2	// log that records what was really wrong, so a test can ask "what was wrong at time t".
3	//
4	// Each injector is switched on in FakeConfig.faults. `true` uses the measured rates and ranges in
5	// fake/behaviour.ts and picks the truck and time from the seed; an object pins the truck or time.
6	// LIVE_DAY switches on what the live site does every day: one truck per fault class, at random.
7	//
8	// Where they act:
9	//   telemetry faults (frozen, silent, seq reset, fractional SoC, malformed, clock skew): the model's
10	//     telemetry step, through TelemetryFaults below; the truth keeps moving underneath;
11	//   radio faults (loss, duplicates, reordering, truncation) and acks (latency, loss): fake/radio.ts,
12	//     once for the whole site, so every client sees the same stream (guessed: the live site's loss
13	//     could be per client; one client cannot tell);
14	//   accepted-then-ignored and queued commands dropped: where the model accepts or applies a command;
15	//   link drops and the slow reader: the gateway's connections;
16	//   two zones, cancelled blasts, BAY closing: the blast schedule's probabilities.
17	import type { Telemetry } from '../src/protocol.ts';
18	import type { Behaviour } from './behaviour.ts';
19	import { Rng } from './rng.ts';
20	
21	export type FaultClass =
22	  | 'link_drop' | 'lost_ack' | 'accepted_ignored' | 'queued_dropped'
23	  | 'frozen_moving' | 'frozen_stationary' | 'silent' | 'seq_reset' | 'truncated' | 'fractional_soc'
24	  | 'malformed' | 'clock_skew' | 'duplicate' | 'late' | 'lost'
25	  | 'weak_pack' | 'fault' | 'two_zones' | 'cancelled_blast' | 'bay_closing' | 'slow_reader' | 'link_stall';
26	
27	// One thing that was really wrong. `untilMs` is null while it lasts (to the end of the day, for a
28	// frozen truck); a one-off event has untilMs equal to atMs.
29	export interface TruthEntry {
30	  atMs: number;
31	  untilMs: number | null;
32	  vehicle: string | null;
33	  fault: FaultClass;
34	  detail: Record<string, unknown>;
35	}
36	
37	export class TruthLog {
38	  readonly #entries: TruthEntry[] = [];
39	
40	  add(e: TruthEntry): TruthEntry {
41	    this.#entries.push(e);
42	    return e;
43	  }
44	
45	  event(atMs: number, vehicle: string | null, fault: FaultClass, detail: Record<string, unknown> = {}): void {
46	    this.add({ atMs, untilMs: atMs, vehicle, fault, detail });
47	  }
48	
49	  start(atMs: number, vehicle: string | null, fault: FaultClass, detail: Record<string, unknown> = {}): TruthEntry {
50	    return this.add({ atMs, untilMs: null, vehicle, fault, detail });
51	  }
52	
53	  // Copies: a test cannot rewrite the truth.
54	  entries(filter: { vehicle?: string; fault?: FaultClass } = {}): TruthEntry[] {
55	    return this.#entries
56	      .filter((e) => (filter.vehicle === undefined || e.vehicle === filter.vehicle) && (filter.fault === undefined || e.fault === filter.fault))
57	      .map((e) => structuredClone(e));
58	  }
59	
60	  // What was wrong at time t: every interval covering t, and every one-off event at exactly t.
61	  activeAt(t: number, filter: { vehicle?: string; fault?: FaultClass } = {}): TruthEntry[] {
62	    return this.entries(filter).filter((e) => e.atMs <= t && (e.untilMs === null || t <= e.untilMs));
63	  }
64	}
65	
66	// A per-truck injector's target. Either part left out is drawn from the seed and the measured range.
67	// `forMs` pins the length of the first silence (silent truck only).
68	export interface TruckTarget { vehicle?: string; atMs?: number; forMs?: number }
69	
70	// Which commands a command fault applies to: by order received (n from 1), id, vehicle or action.
71	export type CommandMatch = (c: { n: number; command_id: string; vehicle_id: string; action: string }) => boolean;
72	
73	export interface Faults {
74	  loss?: boolean;
75	  duplicates?: boolean;
76	  reordering?: boolean;
77	  truncation?: boolean;
78	  ackLatency?: boolean;
79	  lostAcks?: boolean | CommandMatch;
80	  ignoredCommands?: boolean | CommandMatch;
81	  queuedDrops?: boolean;       // a command queued behind LOADING / DUMPING / CHARGING never runs (re-probe Q1)
82	  linkDrops?: boolean | Array<{ atMs: number; durationMs: number }>;
83	  // The connection stays open but nothing arrives, heartbeats included. Not seen live: it was built
84	  // from a misreading of loaded-reverse-into-silence, which was a link drop (the fixture had left out
85	  // the connection events). Kept as a transport failure worth testing. Explicit times only.
86	  linkStalls?: Array<{ atMs: number; durationMs: number }>;
87	  frozenMoving?: boolean | TruckTarget;
88	  frozenStationary?: boolean | TruckTarget; // the undetectable case (L4.R2c); not part of a live day
89	  silent?: boolean | TruckTarget;
90	  seqReset?: boolean | TruckTarget;
91	  fractionalSoc?: boolean | TruckTarget;
92	  malformed?: boolean | TruckTarget;
93	  clockSkew?: boolean | TruckTarget;
94	  weakPack?: boolean | TruckTarget;
95	  hydPressureLow?: boolean | TruckTarget;
96	  batteryDepleted?: boolean | TruckTarget; // on its own; on a live day it comes from the weak pack
97	  bayClosing?: boolean;                    // open question 5: BAY can be blasted
98	}
99	
100	// The live catalogue (research/README.md, CONTEXT.md "What the live site showed"): every day, one
101	// truck each with a frozen message, silences, a seq reset, fractional SoC, malformed fields, a
102	// skewed clock, a weak pack and a hydraulic fault; the radio's loss, duplicates, reordering and
103	// truncation; slow and lost acks, ignored commands and dropped queued ones; link drops; and the
104	// blast schedule's cancellations and second
105	// zones (on by default in the schedule).
106	export const LIVE_DAY: Readonly<Faults> = Object.freeze({
107	  loss: true, duplicates: true, reordering: true, truncation: true,
108	  ackLatency: true, lostAcks: true, ignoredCommands: true, queuedDrops: true, linkDrops: true,
109	  frozenMoving: true, silent: true, seqReset: true, fractionalSoc: true, malformed: true, clockSkew: true,
110	  weakPack: true, hydPressureLow: true,
111	});
112	
113	// The per-truck classes in the order trucks are dealt to them. Distinct trucks while there are
114	// enough, as on every live day; on a smaller site some trucks carry two.
115	// Fractional SoC is dealt last of the live classes: on a site with fewer trucks than classes it is
116	// the one that shares a truck, and it combines harmlessly with any other. The two classes that are
117	// not part of a live day come after it.
118	const TRUCK_CLASSES = [
119	  'frozenMoving', 'silent', 'seqReset', 'malformed', 'clockSkew', 'weakPack', 'hydPressureLow', 'fractionalSoc',
120	  'frozenStationary', 'batteryDepleted',
121	] as const;
122	export type TruckClass = (typeof TRUCK_CLASSES)[number];
123	
124	export interface TruckPlan { vehicle: string; atMs: number; forMs?: number }
125	
126	// Resolve which truck and when, for every per-truck injector that is on. Its own random stream, so
127	// switching one injector on never moves another's truck or time.
128	export function planTrucks(faults: Faults, vehicles: readonly string[], b: Behaviour, seed: number): Partial<Record<TruckClass, TruckPlan>> {
129	  const rng = new Rng(seed).fork('fault-trucks');
130	  const order = [...vehicles];
131	  for (let i = order.length - 1; i > 0; i--) { const j = Math.floor(rng.next() * (i + 1)); [order[i], order[j]] = [order[j]!, order[i]!]; }
132	  const range: Record<TruckClass, [number, number]> = {
133	    frozenMoving: [b.frozenFromMinMs, b.frozenFromMaxMs], frozenStationary: [b.frozenFromMinMs, b.frozenFromMaxMs],
134	    silent: [b.silentFirstMinMs, b.silentFirstMaxMs], seqReset: [b.seqResetMinMs, b.seqResetMaxMs],
135	    fractionalSoc: [0, 0], malformed: [0, 0], clockSkew: [0, 0], weakPack: [0, 0],
136	    hydPressureLow: [b.hydFaultMinMs, b.hydFaultMaxMs], batteryDepleted: [b.depletedMinMs, b.depletedMaxMs],
137	  };
138	  const pinned = new Set(TRUCK_CLASSES.map((c) => faults[c]).filter((f): f is TruckTarget => typeof f === 'object' && !!f.vehicle).map((f) => f.vehicle!));
139	  const free = order.filter((v) => !pinned.has(v));
140	  let next = 0;
141	  const plan: Partial<Record<TruckClass, TruckPlan>> = {};
142	  for (const c of TRUCK_CLASSES) {
143	    const f = faults[c];
144	    const draw = rng.uniform(range[c][0], range[c][1]); // drawn whether on or not: streams stay aligned
145	    const deal = free.length > 0 ? free[next++ % free.length]! : order[next++ % order.length]!;
146	    if (!f) continue;
147	    const target = typeof f === 'object' ? f : {};
148	    if (target.vehicle !== undefined && !vehicles.includes(target.vehicle)) throw new Error(`fault ${c}: no truck ${target.vehicle}`);
149	    plan[c] = { vehicle: target.vehicle ?? deal, atMs: target.atMs ?? Math.round(draw), ...(target.forMs !== undefined ? { forMs: target.forMs } : {}) };
150	  }
151	  return plan;
152	}
153	
154	// ---- telemetry faults, applied by the model to each message it sends ----
155	
156	export interface TelemetryTruth { speedMps: number; state: string; positionM: number }
157	
158	const MALFORMED_KINDS = ['lowercase_state', 'speed_null', 'soc_missing', 'offset_string'] as const;
159	
160	// Per-truck telemetry faults. The model asks before each message whether the truck is silent (then
161	// it sends nothing and its seq does not advance, as live), and passes each message through shape().
162	export class TelemetryFaults {
163	  readonly #b: Behaviour;
164	  readonly #log: TruthLog;
165	  readonly #rng: Rng;
166	  readonly #startMs: number;
167	  readonly #plan: Partial<Record<TruckClass, TruckPlan>>;
168	  #frozen = new Map<string, { body: Record<string, unknown>; entry: TruthEntry }>();
169	  #silence: { vehicle: string; from: number; until: number; entry: TruthEntry | null } | null = null;
170	  #seqResetDone = false;
171	  #fracLogged = false;
172	  #malformedLogged = false;
173	
174	  constructor(plan: Partial<Record<TruckClass, TruckPlan>>, b: Behaviour, log: TruthLog, seed: number, startMs: number) {
175	    this.#plan = plan;
176	    this.#b = b;
177	    this.#log = log;
178	    this.#rng = new Rng(seed).fork('telemetry-faults');
179	    this.#startMs = startMs;
180	    const s = plan.silent;
181	    if (s) this.#silence = { vehicle: s.vehicle, from: startMs + s.atMs, until: startMs + s.atMs + (s.forMs ?? this.#silentFor()), entry: null };
182	  }
183	
184	  #silentFor(): number { return Math.round(this.#rng.uniform(this.#b.silentMinMs, this.#b.silentMaxMs)); }
185	
186	  // True while the truck sends nothing. Silences repeat: talk, then silent again, all day.
187	  silent(vehicle: string, now: number): boolean {
188	    const s = this.#silence;
189	    if (!s || s.vehicle !== vehicle) return false;
190	    if (now >= s.until) {
191	      if (s.entry) s.entry.untilMs = s.until;
192	      s.entry = null;
193	      s.from = s.until + Math.round(this.#rng.uniform(this.#b.talkMinMs, this.#b.talkMaxMs));
194	      s.until = s.from + this.#silentFor();
195	    }
196	    if (now < s.from) return false;
197	    if (!s.entry) s.entry = this.#log.start(s.from, vehicle, 'silent', { plannedUntilMs: s.until });
198	    return true;
199	  }
