201	  // The message as sent. `seq` and `t_device_ms` are already set by the model; a seq reset returns 1.
202	  shape(m: Telemetry, truth: TelemetryTruth, now: number): Record<string, unknown> {
203	    const v = m.vehicle_id;
204	    const p = this.#plan;
205	    let out: Record<string, unknown> = m as unknown as Record<string, unknown>;
206	
207	    if (p.seqReset?.vehicle === v && !this.#seqResetDone && now >= this.#startMs + p.seqReset.atMs) {
208	      this.#seqResetDone = true;
209	      this.#log.event(now, v, 'seq_reset', { fromSeq: m.seq - 1 });
210	      out = { ...out, seq: 1 };
211	    }
212	
213	    for (const cls of ['frozenMoving', 'frozenStationary'] as const) {
214	      const f = p[cls];
215	      if (f?.vehicle !== v) continue;
216	      const fz = this.#frozen.get(cls);
217	      if (fz) {
218	        // The whole body repeats; only seq and the device clock advance (fixture frozen-truck).
219	        out = { ...fz.body, seq: out.seq, t_device_ms: out.t_device_ms };
220	        continue;
221	      }
222	      if (now < this.#startMs + f.atMs) continue;
223	      const moving = truth.speedMps > 0.5 && (truth.state === 'TRAMMING' || truth.state === 'MANUAL');
224	      const still = truth.speedMps === 0 && ['LOADING', 'DUMPING', 'HOLDING', 'IDLE', 'CHARGING'].includes(truth.state);
225	      if (cls === 'frozenMoving' ? moving : still) {
226	        const entry = this.#log.start(now, v, cls === 'frozenMoving' ? 'frozen_moving' : 'frozen_stationary', {
227	          reported: { state: m.state, speed_mps: m.speed_mps, segment_id: m.segment_id, offset_m: m.offset_m }, truePositionM: truth.positionM,
228	        });
229	        const { seq: _s, t_device_ms: _t, ...body } = out;
230	        this.#frozen.set(cls, { body, entry });
231	      }
232	    }
233	
234	    if (p.fractionalSoc?.vehicle === v && typeof out.soc_pct === 'number') {
235	      if (!this.#fracLogged) { this.#fracLogged = true; this.#log.start(now, v, 'fractional_soc'); }
236	      const k = 10 ** this.#b.fractionDigits;
237	      out = { ...out, soc_pct: Math.round((out.soc_pct as number) / 100 * k) / k };
238	    }
239	
240	    if (p.malformed?.vehicle === v) {
241	      if (!this.#malformedLogged) { this.#malformedLogged = true; this.#log.start(now, v, 'malformed'); }
242	      const hits = MALFORMED_KINDS.filter(() => this.#rng.chance(this.#b.malformedProbability));
243	      if (hits.length > 0) {
244	        out = { ...out };
245	        // Shapes as seen live: 'tramming', null, absent, '59.95' (fixture accepted-then-ignored-resume, run captures)
246	        if (hits.includes('lowercase_state') && typeof out.state === 'string') out.state = (out.state as string).toLowerCase();
247	        if (hits.includes('speed_null')) out.speed_mps = null;
248	        if (hits.includes('soc_missing')) delete out.soc_pct;
249	        if (hits.includes('offset_string') && typeof out.offset_m === 'number') out.offset_m = pyFloat(out.offset_m as number);
250	        this.#log.event(now, v, 'malformed', { seq: out.seq, kinds: hits });
251	      }
252	    }
253	    return out;
254	  }
255	}
