544	// The radio between the trucks and the gateway (TESTING.md L0.F): telemetry lost, duplicated, late
545	// (so reordered) and truncated; acks slow and sometimes lost. Applied once for the whole site, so
546	// every client sees the same stream. Gateway messages (hello, heartbeats, zone and lease events,
547	// drive rejections) do not pass through it: live they arrived complete and on time.
548	//
549	// Every fault is drawn from its own seeded stream and written to the truth log with the truck and seq.
550	import type { Clock } from '../src/clock.ts';
551	import type { CommandAck } from '../src/protocol.ts';
552	import type { Behaviour } from './behaviour.ts';
553	import type { CommandMatch, Faults, TruthLog } from './faults.ts';
554	import { Rng } from './rng.ts';
555	
556	export type Deliver = (line: string) => void;
557	
558	export class SiteRadio {
559	  readonly #clock: Clock;
560	  readonly #b: Behaviour;
561	  readonly #f: Faults;
562	  readonly #log: TruthLog;
563	  readonly #deliver: Deliver;
564	  readonly #rngTel: Rng;
565	  readonly #rngAck: Rng;
566	
567	  constructor(clock: Clock, b: Behaviour, faults: Faults, log: TruthLog, seed: number, deliver: Deliver) {
568	    this.#clock = clock;
569	    this.#b = b;
570	    this.#f = faults;
571	    this.#log = log;
572	    this.#deliver = deliver;
573	    const root = new Rng(seed);
574	    this.#rngTel = root.fork('radio-telemetry');
575	    this.#rngAck = root.fork('radio-acks');
576	  }
577	
578	  // One telemetry line. The draws are made whether or not each fault is on, so switching one fault
579	  // on or off never changes another's pattern.
580	  telemetry(line: string, vehicle: string, seq: unknown): void {
581	    const r = this.#rngTel, b = this.#b, f = this.#f;
582	    const lost = r.chance(b.lossProbability);
583	    const truncate = r.chance(b.truncateProbability);
584	    const cutAt = r.int(b.truncateMinChars, b.truncateMaxChars);
585	    const late = r.chance(b.lateProbability);
586	    const lateBy = Math.round(r.uniform(b.lateMinDelayMs, b.lateMaxDelayMs));
587	    const dup = r.chance(b.duplicateProbability);
588	    const dupAfter = Math.round(r.uniform(0, b.duplicateMaxDelayMs));
589	    const now = this.#clock.now();
590	
591	    if (f.loss && lost) { this.#log.event(now, vehicle, 'lost', { seq }); return; }
592	    let sent = line;
593	    if (f.truncation && truncate && line.length > cutAt) {
594	      sent = line.slice(0, cutAt);
595	      this.#log.event(now, vehicle, 'truncated', { seq, chars: cutAt });
596	    }
597	    const delay = f.reordering && late ? lateBy : 0;
598	    if (delay > 0) this.#log.event(now, vehicle, 'late', { seq, byMs: delay });
599	    this.#at(delay, sent);
600	    if (f.duplicates && dup) {
601	      this.#log.event(now, vehicle, 'duplicate', { seq, afterMs: delay + dupAfter });
602	      this.#at(delay + dupAfter, sent);
603	    }
604	  }
605	
606	  // An ack. Its server_time_ms stays the time the gateway got the command, as live; it arrives
607	  // later. `n` is the order the command was received in, for CommandMatch.
608	  ack(line: string, ack: CommandAck, n: number, action: string): void {
609	    const r = this.#rngAck, b = this.#b, f = this.#f;
610	    const invalid = ack.reason === 'BAD_JSON' || ack.reason === 'BAD_COMMAND_ID';
611	    // Commands that act at once (e-stop, leases) were acked within 0.7 s live; the rest up to 2.6 s.
612	    const immediate = ['ESTOP', 'CLEAR_ESTOP', 'TAKE_CONTROL', 'RELEASE_CONTROL'].includes(action);
613	    const max = immediate ? b.ackDelayImmediateMaxMs : b.ackDelayMaxMs;
614	    const delay = invalid
615	      ? Math.round(r.uniform(b.ackDelayInvalidMinMs, b.ackDelayInvalidMaxMs))
616	      : Math.round(Math.exp(r.uniform(Math.log(b.ackDelayMinMs), Math.log(max)))); // log-uniform
617	    const lost = r.chance(b.lostAckProbability);
618	    if (matches(f.lostAcks, lost, { n, command_id: ack.command_id, vehicle_id: ack.vehicle_id ?? '', action })) {
619	      this.#log.event(this.#clock.now(), ack.vehicle_id, 'lost_ack', { command_id: ack.command_id, action, status: ack.status });
620	      return;
621	    }
622	    this.#at(f.ackLatency ? delay : 0, line);
623	  }
624	
625	  #at(delayMs: number, line: string): void {
626	    if (delayMs <= 0) this.#deliver(line);
627	    else this.#clock.setTimeout(() => this.#deliver(line), delayMs);
628	  }
629	}
630	
631	// A command fault switch: off, on at the measured rate (`drawn` is that draw), or a predicate.
632	export function matches(sw: boolean | CommandMatch | undefined, drawn: boolean, c: Parameters<CommandMatch>[0]): boolean {
633	  if (!sw) return false;
634	  if (sw === true) return drawn;
635	  return sw(c);
636	}
637	// Seeded random numbers for the fake (L0.C4). sfc32, seeded through splitmix32. Each concern gets
638	// its own stream (`fork`), so a test's commands never shift the blast schedule or the initial
639	// placement, and milestone 2's fault injectors can add streams without disturbing these.
640	
641	function splitmix32(seed: number): () => number {
642	  let s = seed >>> 0;
643	  return () => {
644	    s = (s + 0x9e3779b9) >>> 0;
645	    let z = s;
646	    z = Math.imul(z ^ (z >>> 16), 0x85ebca6b) >>> 0;
647	    z = Math.imul(z ^ (z >>> 13), 0xc2b2ae35) >>> 0;
648	    return (z ^ (z >>> 16)) >>> 0;
649	  };
650	}
651	
652	export class Rng {
653	  #a: number; #b: number; #c: number; #d: number;
654	
655	  constructor(seed: number) {
656	    const sm = splitmix32(seed);
657	    this.#a = sm(); this.#b = sm(); this.#c = sm(); this.#d = sm();
658	    for (let i = 0; i < 12; i++) this.#nextU32();
659	  }
660	
661	  // A child stream named by `label`: same seed and label, same stream.
662	  fork(label: string): Rng {
663	    let h = 0x811c9dc5;
664	    for (let i = 0; i < label.length; i++) h = Math.imul(h ^ label.charCodeAt(i), 0x01000193) >>> 0;
665	    return new Rng((this.#nextU32() ^ h) >>> 0);
666	  }
667	
668	  // Uniform in [0, 1).
669	  next(): number {
670	    return this.#nextU32() / 4294967296;
671	  }
672	
673	  #nextU32(): number {
674	    const t = (((this.#a + this.#b) >>> 0) + this.#d) >>> 0;
675	    this.#d = (this.#d + 1) >>> 0;
676	    this.#a = this.#b ^ (this.#b >>> 9);
677	    this.#b = (this.#c + (this.#c << 3)) >>> 0;
678	    this.#c = ((this.#c << 21) | (this.#c >>> 11)) >>> 0;
679	    this.#c = (this.#c + t) >>> 0;
680	    return t;
681	  }
682	
683	  uniform(min: number, max: number): number {
684	    return min + (max - min) * this.next();
685	  }
686	
687	  int(min: number, maxInclusive: number): number {
688	    return min + Math.floor(this.next() * (maxInclusive - min + 1));
689	  }
690	
691	  chance(p: number): boolean {
692	    return this.next() < p;
693	  }
694	
695	  pick<T>(items: readonly T[]): T {
696	    if (items.length === 0) throw new RangeError('pick from an empty list');
697	    return items[Math.floor(this.next() * items.length)]!;
698	  }
699	
700	  hex(digits: number): string {
701	    let s = '';
702	    for (let i = 0; i < digits; i++) s += Math.floor(this.next() * 16).toString(16);
703	    return s;
704	  }
705	}
706

// TESTING.md L1.1 and L1.3: rules about what product code may contain, checked over src/.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { existsSync, readFileSync, readdirSync } from 'node:fs';
import { join, relative } from 'node:path';

const SRC = new URL('../src/', import.meta.url).pathname;
// The fake gateway (test infrastructure) is held to the same rules: it takes a Clock, and its model
// knows no site. Its default site config is the one place this site's literals belong.
const FAKE = new URL('../fake/', import.meta.url).pathname;
const FAKE_SITE_CONFIG = 'dlh1.ts';

function sourceFiles(dir: string): string[] {
  if (!existsSync(dir)) return [];
  return readdirSync(dir, { withFileTypes: true }).flatMap((e) =>
    e.name.startsWith('._') ? [] : e.isDirectory() ? sourceFiles(join(dir, e.name)) : e.name.endsWith('.ts') ? [join(dir, e.name)] : [],
  );
}

// L1.1: only the clock adapter may touch the wall clock or timers.
const WALL_CLOCK = [
  /\bDate\.now\s*\(/,
  /\bnew\s+Date\s*\(/,
  /\bperformance\.now\s*\(/,
  /\bprocess\.hrtime\b/,
  /(?<![.\w])(setTimeout|setInterval|setImmediate|clearTimeout|clearInterval)\s*\(/,
];

// L1.3: this site's names and numbers. The product takes them from hello and zone_event instead.
const SITE_LITERALS = [
  /\b(DECLINE|L4_NORTH|DRAW_12|L4_SOUTH|INCLINE|TIP)\b/,
  /['"`]BAY['"`]/,
  /\bSEG-/,
  /\bHT-\d/,
  /\b1600(\.0)?\b/,
  /\b120_?000\b/,
];

function violations(text: string, rules: RegExp[]): string[] {
  return text.split('\n').flatMap((line, i) => rules.filter((r) => r.test(line)).map((r) => `line ${i + 1}: ${line.trim()}  [${r}]`));
}

test('L1.1 the rule catches each kind of wall-clock access', () => {
  for (const planted of ['const t = Date.now();', 'new Date()', 'performance.now()', 'process.hrtime.bigint()', 'setTimeout(f, 10)', 'clearInterval(h)']) {
    assert.equal(violations(planted, WALL_CLOCK).length, 1, planted);
  }
  assert.deepEqual(violations('clock.setTimeout(f, 10); clock.now()', WALL_CLOCK), []);
});

test('L1.1 no product module outside the clock adapter reads the wall clock', () => {
  const found = sourceFiles(SRC)
    .filter((f) => relative(SRC, f) !== 'clock.ts')
    .flatMap((f) => violations(readFileSync(f, 'utf8'), WALL_CLOCK).map((v) => `${relative(SRC, f)} ${v}`));
  assert.deepEqual(found, []);
});

test('L1.3 the rule catches each kind of site literal', () => {
  for (const planted of ["zone === 'DECLINE'", "if (z === 'BAY')", "'SEG-BAY'", "vehicle: 'HT-04'", 'const loop = 1600;', 'const notice = 120_000;']) {
    assert.equal(violations(planted, SITE_LITERALS).length, 1, planted);
  }
  assert.deepEqual(violations("segment.kind === 'bay'; const n = 16000;", SITE_LITERALS), []);
});

test('L1.3 product code contains none of this site\'s literals', () => {
  const found = sourceFiles(SRC).flatMap((f) => violations(readFileSync(f, 'utf8'), SITE_LITERALS).map((v) => `${relative(SRC, f)} ${v}`));
  assert.deepEqual(found, []);
});

test('L1.1 the fake gateway never reads the wall clock', () => {
  const found = sourceFiles(FAKE).flatMap((f) => violations(readFileSync(f, 'utf8'), WALL_CLOCK).map((v) => `fake/${relative(FAKE, f)} ${v}`));
  assert.deepEqual(found, []);
});

// The fixture player paces itself on an injected clock too (task 6a), and knows no site. Its
// screenshot list is the exception for site literals: like a test, it names moments in this site's
// recordings.
const PLAYER = new URL('../player/', import.meta.url).pathname;
const PLAYER_SHOT_LIST = 'shoot.ts';

test('L1.1 and L1.3 the fixture player takes a Clock and contains none of this site\'s literals', () => {
  const found = sourceFiles(PLAYER).flatMap((f) =>
    violations(readFileSync(f, 'utf8'), relative(PLAYER, f) === PLAYER_SHOT_LIST ? WALL_CLOCK : [...WALL_CLOCK, ...SITE_LITERALS])
      .map((v) => `player/${relative(PLAYER, f)} ${v}`));
  assert.deepEqual(found, []);
});

test('L1.3 the fake gateway\'s model contains none of this site\'s literals (only its default config does)', () => {
  const found = sourceFiles(FAKE)
    .filter((f) => relative(FAKE, f) !== FAKE_SITE_CONFIG)
    .flatMap((f) => violations(readFileSync(f, 'utf8'), SITE_LITERALS).map((v) => `fake/${relative(FAKE, f)} ${v}`));
  assert.deepEqual(found, []);
});
// The Overview's words and order (UI.md screen 1): the zone clearance panel, the fleet table sorted
// by attention, and the link indicators. Pure: a fleet snapshot in, plain data out. The browser only
// draws it.
import { zoneClearance, type Verdict } from '../clearance.ts';
import type { FleetSnapshot, TruckView, ZoneView } from '../fleet.ts';
import { age, countdown, dataState, elapsed, faultWords } from '../words.ts';

// ---- zone clearance panel ----

export interface ClearanceRow {
  zoneId: string;
  status: string; // CLOSING, CLOSED, or status unknown
  verdict: Verdict;
  verdictWords: 'CLEAR' | 'NOT CLEAR' | 'UNSURE';
  when: string; // "closes in 1:23", "closed 0:40 ago"
  action: string | null;
  reasons: string[]; // "<truck>: data frozen ..."
}

const VERDICT_WORDS: Record<Verdict, ClearanceRow['verdictWords']> = { CLEAR: 'CLEAR', NOT_CLEAR: 'NOT CLEAR', UNSURE: 'UNSURE' };

export function zoneWhen(z: ZoneView): string {
  const left = z.msUntilEffective;
  if (z.status === 'CLOSING') {
    if (left === null) return 'closing, time not given';
    return left >= 0 ? `closes in ${countdown(left)}` : `was due to close ${elapsed(-left)} ago: treat as closed`;
  }
  if (z.status === 'CLOSED') return left !== null && left <= 0 ? `closed ${elapsed(-left)} ago` : 'closed';
  if (z.status === null) return 'status unknown: treat as closed';
  return 'open';
}

// Every zone that is closing, closed, or of unknown status, in route order: rows stay where they are
// while verdicts change, so the operator finds a zone by its name and place.
export function clearanceRows(snap: FleetSnapshot): ClearanceRow[] {
  return snap.zones.filter((z) => z.status !== 'OPEN').map((z) => {
    const c = zoneClearance(z, snap.trucks);
    return {
      zoneId: z.zoneId,
      status: z.status ?? 'status unknown',
      verdict: c.verdict,
      verdictWords: VERDICT_WORDS[c.verdict],
      when: zoneWhen(z),
      action: c.action,
      reasons: c.reasons.map((r) => `${r.vehicleIds.join(', ')}: ${r.why}`),
    };
  });
}

// ---- fleet table ----

export interface FleetRow {
  vehicleId: string;
  tier: number; // lower needs attention sooner
  attention: string | null; // why it sits where it does, in words
  dataKind: TruckView['confidence'];
  data: string;
  state: string;
  fault: string | null; // the fault codes as the truck reports them
  zone: string;
  zoneAlert: string | null; // a closing or closed zone it is, or might be, in
  soc: string;
  socFlags: string[];
  control: string;
  lastCommand: string;
}

// Attention tiers, most urgent first. A truck that might be in a closing or closed zone outranks
// everything, whatever its data state; then a truck that can't move or will die where it is; then
// doubt about where it is, from most to least; then doubt about its battery; then trucks under a
// person's control; then the rest.
export const TIERS = [
  'might be in a closing or closed zone',
  'faulted or stopped',
  'battery may not get it home',
  'data contradicted',
  'silent',
  'old',
  'no position',
  'battery figure doubted',
  'under manual control or held',
  'normal',
] as const;

function tierOf(t: TruckView, closing: Map<string, ZoneView>): { tier: number; why: string | null } {
  const zs = t.range === null ? [...closing.keys()] : t.mightBeIn.filter((z) => closing.has(z));
  if (zs.length) {
    const reported = (t.confidence === 'live' || t.confidence === 'old') ? t.position?.value.zoneId : undefined;
    const named = (id: string) => `${id} (${closing.get(id)!.status ?? 'status unknown'})`;
    if (reported && zs.includes(reported)) {
      const others = zs.filter((z) => z !== reported);
      return { tier: 0, why: `in ${named(reported)}${others.length ? `; might be in ${others.map(named).join(', ')}` : ''}` };
    }
    return { tier: 0, why: `might be in ${zs.map(named).join(', ')}` };
  }
  const faults = faultWords(t);
  const s = t.state?.value;
  if (faults || s === 'FAULT' || s === 'ESTOPPED') return { tier: 1, why: faults ?? (s === 'ESTOPPED' ? 'e-stopped' : 'faulted') };
  if (t.battery.warning) return { tier: 2, why: t.battery.message };
  if (t.confidence === 'contradicted') return { tier: 3, why: 'data frozen: position unknown' };
  if (t.confidence === 'silent') return { tier: 4, why: null };
  if (t.confidence === 'old') return { tier: 5, why: null };
  if (t.confidence === 'unknown') return { tier: 6, why: null };
  if (t.socFractional || t.battery.drainHigh) return { tier: 7, why: null };
  const c = t.control?.value;
  if (c?.mode === 'MANUAL' || c?.operatorId || s === 'MANUAL' || s === 'HOLDING') return { tier: 8, why: null };
  return { tier: 9, why: null };
}

export function socView(t: TruckView): { text: string; flags: string[] } {
  const flags: string[] = [];
  const v = t.socPct?.value;
  let text = '—';
  if (v !== undefined) {
    text = t.socFractional ? `${v} (as sent)` : `${v.toFixed(1)} %`;
    if (t.socFractional) flags.push(`looks like a fraction, not a percentage; shown as sent, not scaled`);
  }
  const b = t.battery;
  if (b.drainHigh) {
    const r = Math.max(b.ratioToFleet.empty ?? 0, b.ratioToFleet.loaded ?? 0);
    flags.push(`draining ${r.toFixed(1)}× faster than the fleet`);
  }
  if (b.warning === 'DEPLETED') flags.push('depleted: needs a tow');
  else if (b.warning === 'CANNOT_REACH_BAY') flags.push('may not reach the bay on this charge');
  else if (b.warning === 'WONT_FINISH_LAP') flags.push("won't finish its lap: return to bay now");
  return { text, flags };
}

function zoneCell(t: TruckView): string {
  const z = t.position?.value.zoneId;
  if (t.confidence === 'live' || t.confidence === 'old') return z ?? '—';
  if (t.range === null || (t.confidence === 'unknown' && !z)) return 'anywhere';
  const could = t.mightBeIn.join(', ');
  return z ? `last seen ${z}; could be in ${could}` : `could be in ${could}`;
}

function stateCell(t: TruckView): string {
  const parts: string[] = [];
  if (t.state) parts.push(t.state.value);
  if (t.task?.value) parts.push(t.task.value);
  if (t.direction?.value === 'REV' && (t.speedMps?.value ?? 0) > 0) parts.push('reversing');
  return parts.join(' · ') || '—';
}

function controlCell(t: TruckView): string {
  const c = t.control?.value;
  if (!c) return '—';
  const parts: string[] = [c.mode];
  if (c.operatorId) parts.push(`lease: ${c.operatorId}`);
  if (c.deadman) parts.push('deadman stop');
  return parts.join(' · ');
}

// No command on this truck yet, or (in the fixture player) no command registry at all.
export const NO_COMMAND_YET = '—';

// `lastCommands`: each truck's latest command in words ("HOLD by priya: done: ..."), from the live
// service. The fixture player has none.
export function fleetRows(snap: FleetSnapshot, lastCommands: ReadonlyMap<string, string> = new Map()): FleetRow[] {
  const closing = new Map(snap.zones.filter((z) => z.status !== 'OPEN').map((z) => [z.zoneId, z]));
  const rows = snap.trucks.map((t, i) => {
    const { tier, why } = tierOf(t, closing);
    const zs = t.range === null ? [...closing.keys()] : t.mightBeIn.filter((z) => closing.has(z));
    const soc = socView(t);
    return {
      i,
      row: {
        vehicleId: t.vehicleId,
        tier,
        attention: why,
        dataKind: t.confidence,
        data: dataState(t),
        state: stateCell(t),
        fault: (t.faults?.value.length ?? 0) > 0 ? t.faults!.value.join(', ') : null,
        zone: zoneCell(t),
        zoneAlert: zs.length ? zs.map((z) => `${z} ${closing.get(z)!.status ?? 'status unknown'}`).join(', ') : null,
        soc: soc.text,
        socFlags: soc.flags,
        control: controlCell(t),
        lastCommand: lastCommands.get(t.vehicleId) ?? NO_COMMAND_YET,
      } satisfies FleetRow,
    };
  });
  rows.sort((a, b) => a.row.tier - b.row.tier || a.i - b.i);
  return rows.map((r) => r.row);
}

// ---- links ----

export interface LinkView {
  state: 'up' | 'down' | 'not recorded';
  text: string;
}

// The site link, from heartbeat age (PROTOCOL.md §4.3). `recorded` is false only in the fixture
// player, for a recording that kept no heartbeats: then the link's state is not known, and saying
// "down" would grey a picture that is not stale.
// The live service also says when its connection has dropped (snap.link.up false): that is down at
// once, without waiting for the heartbeat to go stale.
export function siteLink(snap: FleetSnapshot, recorded = true): LinkView {
  if (!recorded) return { state: 'not recorded', text: 'Site link: not in this recording' };
  const hb = snap.heartbeat;
  if (hb.ageMs === null) return { state: 'down', text: 'Site link DOWN: no heartbeat yet' };
  if (hb.stale || snap.link.up === false) return { state: 'down', text: `Site link DOWN: no heartbeat for ${age(hb.ageMs)}` };
  return { state: 'up', text: `Site link up: heartbeat ${age(hb.ageMs)} ago` };
}

// `open` false: the browser knows its connection to the service has closed, so it is down at once.
export function serviceLink(sinceLastFrameMs: number | null, staleAfterMs: number, open = true): LinkView {
  if (sinceLastFrameMs === null) return { state: 'down', text: 'Service: not connected yet' };
  if (sinceLastFrameMs >= staleAfterMs || !open) return { state: 'down', text: `Service DISCONNECTED: nothing for ${age(sinceLastFrameMs)}` };
  return { state: 'up', text: 'Service connected' };
}
/// <reference lib="dom" />
// The Overview in the browser: draws what src/ui/track.ts and src/ui/overview.ts compute from each
// frame, and nothing else. All decisions about words, order and shape live in those pure modules.
//
// Frames come from the fixture player (player/server.ts, over server-sent events) or from the live
// service (src/live.ts, over a WebSocket), in the same shape: { player?, live?, site, snapshot }. The
// page is in live mode when the service marks it so (<body data-mode="live">). The browser keeps its
// own clock only to notice frames have stopped, so a stopped feed never looks current (UI.md
// principle 2).
//
// In live mode the browser sends commands (the e-stop for now) over the same WebSocket. It never
// names the operator: the service takes that from the session. It never queues a command it could not
// send: with the service disconnected it says so, and nothing is sent later.
import { SystemClock } from '../clock.ts';
import { PARAMS } from '../params.ts';
import type { FleetSnapshot } from '../fleet.ts';
import type { CommandView, LiveState, Notice } from '../live.ts';
import { clearanceRows, fleetRows, serviceLink, siteLink, type LinkView } from './overview.ts';
import { trackModel, type SiteData, type TrackModel } from './track.ts';

interface PlayerState {
  fixture: string; shows: string; source: string; startMs: number; endMs: number; offsetMs: number;
  playing: boolean; speed: number; atEnd: boolean; heartbeatsRecorded: boolean; helloFrom: string;
  bookmarks: Array<{ offsetMs: number; text: string }>;
}
interface Frame { player?: PlayerState; live?: LiveState; site: SiteData | null; snapshot: FleetSnapshot }
interface You { id: string; name: string; role: string }

const SERVICE_STALE_MS = PARAMS.browserStaleAfter.value; // both the player and the service send a frame at least every second
const RECONNECT_MS = 2_000;
const LIVE = document.body.dataset.mode === 'live';
const SPEEDS = [0.5, 1, 2, 5, 10, 30];
const clock = new SystemClock();
const $ = <T extends HTMLElement = HTMLElement>(id: string) => document.getElementById(id) as T;
const SVG = 'http://www.w3.org/2000/svg';

let frame: Frame | null = null;
let lastFrameAt: number | null = null;
let socket: WebSocket | null = null; // live mode: open, or null
let you: You | null = null;
let notices: Notice[] = [];

// ---- small DOM helpers ----

function el<K extends keyof HTMLElementTagNameMap>(tag: K, attrs: Record<string, string> = {}, ...kids: Array<Node | string | null>): HTMLElementTagNameMap[K] {
  const e = document.createElement(tag);
  for (const [k, v] of Object.entries(attrs)) e.setAttribute(k, v);
  for (const k of kids) if (k !== null) e.append(k);
  return e;
}

function svg(tag: string, attrs: Record<string, string | number> = {}, ...kids: Array<Node | string>): SVGElement {
  const e = document.createElementNS(SVG, tag);
  for (const [k, v] of Object.entries(attrs)) e.setAttribute(k, String(v));
  for (const k of kids) e.append(k);
  return e;
}

const clock2 = (ms: number) => { const s = Math.floor(ms / 1000); return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`; };

// ---- links and banners ----

function setLink(id: string, v: LinkView): void {
  const e = $(id);
  e.dataset.state = v.state;
  e.textContent = v.text;
}

function renderLinks(): void {
  const since = lastFrameAt === null ? null : clock.now() - lastFrameAt;
  const service = serviceLink(since, SERVICE_STALE_MS, !LIVE || socket !== null);
  setLink('service-link', service);
  const site = frame ? siteLink(frame.snapshot, frame.player?.heartbeatsRecorded ?? true) : { state: 'down' as const, text: 'Site link: no data' };
  setLink('site-link', site);
  const aged = service.state === 'down' || site.state === 'down';
  document.body.classList.toggle('aged', aged);
  const banners: HTMLElement[] = [];
  if (service.state === 'down') banners.push(el('div', { class: 'banner down' }, `${service.text}. The picture below is not current.`));
  if (site.state === 'down') banners.push(el('div', { class: 'banner down' }, `${site.text}. Everything below is at least that old; ages keep counting.`));
  const p = frame?.player;
  if (p && !p.playing && service.state !== 'down') {
    banners.push(el('div', { class: 'banner note' }, p.atEnd ? 'End of the recording. Fixture time has stopped: ages are not counting.' : 'Paused. Fixture time has stopped: ages are not counting.'));
  }
  const live = frame?.live;
  if (live && !live.blastSafety.active) banners.push(el('div', { class: 'banner warn' }, live.blastSafety.note));
  $('banners').replaceChildren(...banners);
  if (LIVE) renderEstops();
}

// ---- zone clearance ----

function renderClearance(snap: FleetSnapshot): void {
  const rows = clearanceRows(snap);
  if (rows.length === 0) {
    $('clearance').replaceChildren(el('p', { class: 'none' }, 'No zone is closing or closed.'));
    return;
  }
